WordHunterWoW_QuestEN[46756] = { title = "Mission: Felrage Destruction", description = "", objectives = "" }
WordHunterWoW_QuestEN[46761] = { title = "Brew Bandits", description = "", objectives = "" }
WordHunterWoW_QuestEN[46762] = { title = "Storm Brew Hustle", description = "", objectives = "" }
WordHunterWoW_QuestEN[46763] = { title = "Drol'maz", description = "", objectives = "" }
WordHunterWoW_QuestEN[46764] = { title = "Enable Challenge Boss Fights", description = "", objectives = "" }
WordHunterWoW_QuestEN[46765] = { title = "The Broken Shore: Investigating the Legion", description = "While we focus efforts on the Broken Shore, we must be careful to guard against other threats. We have been getting disturbing reports on the Legion starting or supporting indirect threats to Azeroth.\n\nWhile you are on the Broken Shore, please keep an eye out for strange objects or intelligence that could give us a clue as to what and where these threats are.\n\nI know it is not a lot to go on, we will do our best from here as well.", objectives = "Discover a hidden Legion threat while on the Broken Shore.", progress = "Found something?", completion = "This scroll, fascinating... this confirms our concerns about indirect Legion threats. We must return to Dalaran, <name>!" }
WordHunterWoW_QuestEN[46766] = { title = "Ulgthax", description = "", objectives = "" }
WordHunterWoW_QuestEN[46767] = { title = "Maximillian 1 Week Cooldown", description = "", objectives = "" }
WordHunterWoW_QuestEN[46768] = { title = "Akazamzarak 1 Week Cooldown", description = "", objectives = "" }
WordHunterWoW_QuestEN[46769] = { title = "Relieved of Their Valuables", description = "Not all demons on this shore stomp around in the open. Some slink about in the shadows, finding more subtle ways to advance the Legion's cause.\n\nI have been observing the behavior of smaller demons, these wyrmtongues. They seem to spend considerable time acquiring objects of power. We cannot allow them to use these items against us.\n\nThe wyrmtongues stash their goods in chests spread around the Broken Shore. I suggest you relieve them of their ill-gotten gain.", objectives = "Find 3 Hidden Wyrmtongue Caches on the Broken Shore.", progress = "Have you found the wyrmtongue caches?", completion = "Fine work. It's important to keep powerful treasures out of demon hands.\n\nThere are more ways to undermine the Legion's agenda than simply killing demons... although there's a lot to be said for good old-fashioned violence." }
WordHunterWoW_QuestEN[46772] = { title = "The Mage Tower", description = "Well done {name}. In testament to the efforts of all forces fighting here, we have come together to complete the construction of the Mage Tower.\n\nAll that remains is for you to inspect our work, and complete the construction.", objectives = "Complete the construction of the Mage Tower.", progress = "Inspect the <class> Tower, and complete its construction.", completion = "Our grand efforts have resulted in a boon which all can leverage in the coming days." }
WordHunterWoW_QuestEN[46773] = { title = "The Command Center", description = "Well done {name}. In testament to the efforts of all forces fighting here, we have come together to complete the construction of the Command Center.\n\nAll that remains is for you to inspect our work, and complete the construction.", objectives = "Complete the construction of the Command Center.", progress = "Inspect the Command Center, and complete its construction.", completion = "Our grand efforts have resulted in a boon which all can leverage in the coming days." }
