WordHunterWoW_QuestEN[46777] = { title = "The Bounties of Legionfall", description = "<class>t, thanks to your efforts, our forces have been able to secure additional resources from the battlefield.\n\nThe more you continue to dominate the battlefield the more resources our forces can spare.", objectives = "Speak with Captain Ruysantos on the Broken Shore for your reward.", completion = "Battlelord, thanks to your efforts, our forces have been able to secure additional resources from the battlefield.\n\nThe more you continue to dominate the battlefield the more resources our forces can spare." }
WordHunterWoW_QuestEN[46778] = { title = "Further Advancement", description = "As the war against our enemies progresses, so must we.\n\nWe are now able to perform new research. Seek out Einar the Runecaster to continue advancing the Order Hall.", objectives = "Seek out the Einar the Runecaster.", completion = "Our power grows." }
