WordHunterWoW_QuestEN[46824] = { title = "Shadowstrike and Thunderstrike Anniversary", description = "", objectives = "" }
WordHunterWoW_QuestEN[46825] = { title = "Mud Mucking", description = "", objectives = "" }
WordHunterWoW_QuestEN[46826] = { title = "Battleplate of the Silver Hand", description = "", objectives = "" }
WordHunterWoW_QuestEN[46827] = { title = "Meld Into the Shadows", description = "We should meet back up with the rest of the council and tell them of what we have achieved this day. At your leisure, return to us. We shall be waiting.", objectives = "Return to the Hall of Shadows, and meet Lord Jorach Ravenholdt.", completion = "We've been discussing your recent success, <name>. We walk the shadows, and that often goes taken for granted. But without us, the Armies of Legionfall would have a great many more powerful demons to deal with.\n\nWe do not need the fame. We reap the rewards." }
WordHunterWoW_QuestEN[46829] = { title = "Elemental Abuse", description = "", objectives = "" }
WordHunterWoW_QuestEN[46830] = { title = "Battlefield", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[46831] = { title = "Broken Village", description = "", objectives = "" }
WordHunterWoW_QuestEN[46832] = { title = "Aalgen Point", description = "You wanna hold territory on this chunder puddle of an island, right? Right. That means linkin' up with camps on the outskirts, mate. \n\nI know this bloke called Heidirk. Scrappy fella, loves to get into the thick of it. Headed out to the eastern coast with those drakes of his.\n\nHave a look for him. Remind him he owes me a pint or two!", objectives = "Speak with Heidirk the Scalekeeper at Aalgen Point.", completion = "Chambers sent you? He can down a tankard with the best of 'em, I'll give him that. But if he says I owe him anything, he's a liar!\n\nDon't you worry, my drakes and I will hold the point here. But more of this shore will need to be secured before your campaign can find victory." }
WordHunterWoW_QuestEN[46833] = { title = "Nature Unshackled", description = "", objectives = "" }
WordHunterWoW_QuestEN[46834] = { title = "Khazaduum, First of His Name", description = "The Argunite Matrix that powered this part of Eredath was shattered by a hulking beast. We had never seen another like him.\n\nHe was called Khazaduum and he was a most faithful servant of the Legion. He volunteered to undergo an experimental transformation to become the first of his kind. His arrival was the end of this battle.\n\nAs a prize he took the Argunite Keystone from the shattered matrix. Take it back and we can finally end this bloodshed.", objectives = "Retrieve the Argunite Keystone from the Echo of Khazaduum.", progress = "Please, they should not be made to suffer any longer.", completion = "I cannot right every wrong that happened here, but this is a comfort nonetheless.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[46835] = { title = "Whispers of a Frightened World Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[46839] = { title = "From Darkness", description = "I'm afraid it's only a matter of time before our presence is known.\n\nWe must begin our preparations at once.", objectives = "Walk with High Exarch Turalyon.", completion = "So it begins." }
WordHunterWoW_QuestEN[46840] = { title = "Prisoners No More", description = "Hatuun's people have endured arduous times. Their numbers dwindle as those ripped from beyond the walls of their sanctuary become servants to the annihilan lords in the pits just beyond, sentenced to a life of labor, torture and ultimately, death.\n\nSeek out these captives, release them from their bonds and show our allies we stand as one against the Burning Legion.", objectives = "Rescue 10 Darkfallen Slaves from the Annihilan Pits.", completion = "Hatuun's people will greatly appreciate what you've done for them." }
WordHunterWoW_QuestEN[46841] = { title = "Threat Reduction", description = "In time, Hatuun and his people will set aside their bitterness and become valuable allies. But their trust must be earned.\n\nHe says their village is beset by a demon called Aggonar and his cruel kin.\n\nWe need these fiends out of the way before we can seek out Alleria and the others.\n\nThe chieftain lent us his horn. Use it to call down his people's vengeance upon the demon lieutenants while I carve a path to Aggonar's lair.", objectives = "Slay Kar'aaz, Xeth'tal, and Magraloth in the Annihilan Pits.", progress = "Has the threat been dealt with?", completion = "Now that their lords have been reduced to ash, we may strike at the heart of their power." }
WordHunterWoW_QuestEN[46842] = { title = "A Strike at the Heart", description = "These pits have long been a blight upon the lives of our new allies. The demons hunt them down and torture the poor souls for sport.\n\n<Turalyon shakes his head with disgust, fixing his gaze upon the beast before him.>\n\nIt is time to make them pay for their cruelty and restore hope to this Light-forsaken place.\n\nWe strike on your mark, {name}.", objectives = "Slay Aggonar.", progress = "No rest until the deed is done.", completion = "This victory is only the first link in a long chain, Slayer." }
WordHunterWoW_QuestEN[46843] = { title = "Return to the Vindicaar", description = "That pit lord won't trouble our new allies any longer.\n\n<Turalyon's brow furrows.>\n\nUntil another takes its place, at least. If there's one thing I've learned in our endless war against the Legion, it's to savor victories as you find them.\n\nCome, let us take a moment to regroup back at your vessel. Alleria and I have been waiting a long time for a reunion with our son.", objectives = "Return to the Vindicaar.", completion = "Our absence has wounded Arator. We knew it would. But we had to know that he was safe while we fought the Legion.\n\nNow that we are reunited, I will not let us be separated again." }
WordHunterWoW_QuestEN[46844] = { title = "Cathedral of Eternal Night: Mistress of Blades", description = "", objectives = "" }
WordHunterWoW_QuestEN[46845] = { title = "Vengeance Point", description = "On my way here, I ran across a squad of demon hunters headed northwest to Vengeance Point. You can bet the Legion will try to stop them from establishing a forward position.\n\nI spoke to an elf named Izal Whitemoon. Not the friendliest sort, but I'm sure she'd be grateful if you lent the Illidari a hand... whether she admits it or not.", objectives = "Defeat the Legion siege on Vengeance Point and report to Izal Whitemoon.", progress = "This siege is disabling my bats from their scouting duties.", completion = "The Illidari don't waste time on congratulations. There is more to do, and you're the one to do it.\n\nGet a move on." }
WordHunterWoW_QuestEN[46846] = { title = "The Word of Zul", description = "I have a mundane task for you. Our esteemed Prophet Zul has words to distribute to very specific individuals in de port. \n\nAnd he requested you be de one to deliver dem.\n\nDon't ask me why he didn't just have you deliver these when you were here de first time. De prophet is notorious for not sharing all of his visions.", objectives = "Deliver the Words of Zul to various individuals in the Port of Zandalar.", progress = "Have you finished all of your deliveries?", completion = "Ah, you are a competent errand-<race> after all. Perhaps you could be trusted with more important tasks. Like trash removal." }
WordHunterWoW_QuestEN[46865] = { title = "Cathedral of Eternal Night: Mother of Flame", description = "", objectives = "" }
WordHunterWoW_QuestEN[46866] = { title = "Torture Chamber", description = "", objectives = "" }
WordHunterWoW_QuestEN[46867] = { title = "Cathedral of Eternal Night: Fel Beast", description = "", objectives = "" }
WordHunterWoW_QuestEN[46868] = { title = "Cathedral of Eternal Night: Infernal Dead", description = "", objectives = "" }
WordHunterWoW_QuestEN[46869] = { title = "Cathedral of Eternal Night: Temptress of Pain", description = "", objectives = "" }
WordHunterWoW_QuestEN[46870] = { title = "7.2 Broken Shore - Buildings - Command Center - Buff Activation - Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[46871] = { title = "7.2 Broken Shore - Buildings - Nether Disruptor - Buff Activation - Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[46904] = { title = "Boon of the Command Center", description = "", objectives = "Well done, I can now provide you with a boon that will grant you a benefit while the Command Center is activated." }
WordHunterWoW_QuestEN[46924] = { title = "The Wolf's Tale", description = "Goldrinn sure didn't take any time getting out of here, did he?\n\nLet's go see if we can find him outside.", objectives = "Find Goldrinn outside of the Stormrage Barrow Dens.", completion = "We must warn the Dreamgrove of what is happening." }
WordHunterWoW_QuestEN[46926] = { title = "Shakedown", description = "Where are de guards? \n\nPrincess Talanji has convinced King Rastakhan to permit outsiders in our port. For de first time in centuries, we have allowed non-trolls to set foot on our shores and peddle their wares.\n\nAnd now trolls of lesser tribes seem to think dey can take advantage of these merchants?\n\nI will not allow dis sort of behavior. While I investigate why de merchants are not protected, I want you to work your way through de bazaar and slay any thugs you find. \n\nSend dem a message.", objectives = "Slay 15 Dockside Ruffians.", progress = "If Zuldazar is to once again be a shining jewel, we must learn to work with de other races.", completion = "You have my thanks. I think having someone of de Horde dispense dis justice was extra fitting.\n\nDe fact dat we have left our harbor so unprotected worries me greatly." }
WordHunterWoW_QuestEN[46927] = { title = "Punishment of Tal'aman", description = "Look, Zolani is going about dis all wrong. If you want de Amani, or anyone, to pay attention, take out their leaders.\n\nGo into Tal'aman and look for their mighty gong. Challenge four of their disciples to combat and slay dem.", objectives = "Challenge 4 Amani Disciples.", progress = "De forest trolls can be mighty mean.", completion = "It will not be long before these disciples are replaced with new ones. Hopefully, de next ones will learn from de past." }
WordHunterWoW_QuestEN[46928] = { title = "Punishment of Tal'farrak", description = "De Sandfury tribe may have had a hand in some crime around here, but it is really their false belief system dat makes dem do dis sort of thing. Enter Tal'farrak, bang de gong within, and face de hydra dey keep as a sacred pet.\n\nBring me dis thing's tongues.", objectives = "Collect the tongues of Ghaz'ragon.", progress = "Did you get de tongues?", completion = "Ha ha ha. You can tell a lot about a tribe by what dey worship." }
WordHunterWoW_QuestEN[46929] = { title = "Deterrent", description = "General Jakra'zet had orders to ensure dis place had protection. Guard protection. I see none of dat.\n\nJakra'zet is a stubborn general, and one I have had my eye on for a while now.\n\nRegardless, we must remind dese lesser tribes who rules dis city with a message dey will understand.\n\nI charge you with collecting heads.\n\nEnter Tal'farrak and Tal'aman, and collect a quota of heads.", objectives = "Collect 6 Amani Heads from Tal'aman and 6 Sandfury Heads from Tal'farrak.", progress = "Troll politics are more like a blood sport.", completion = "When visitors do not understand de language of your laws, it becomes necessary to explain your laws in a language dey do understand." }
WordHunterWoW_QuestEN[46930] = { title = "Rastakhan", description = "You stand before General Jakra'zet, lord of de armies of Zandalar, enforcer of her seas and bringer of war.\n\nAnd I do not like you. \n\nIt took years to earn my place here after your Horde laid waste to my people. You will not undo what I have built.\n\nI will see you kneel before King Rastakhan. I will watch you beg as he lets me take your head for a trophy. I will fling your corpse into de wastes of Vol'dun.\n\nHer \"Highness\" may object... but she is not queen yet.\n\nCome. Let us fly to your fate.", objectives = "Meet King Rastakhan.", progress = "Welcome, Champion of de Horde. I am King Rastakhan, lord of Zandalar and her peoples.", completion = "Your deeds had reached my ears before your feet ever set foot in my land. It is time we spoke." }
WordHunterWoW_QuestEN[46931] = { title = "Speaker of the Horde", description = "Your Horde has grown powerful, eclipsing some of de troll empires in its magnitude.\n\nFor saving my daughter, you have earned de right to a presence in my city.\n\nSince my daughter has taken such a fondness to you, you may join her in de Great Seal beneath us. De servants there will answer to you now.\n\nTalanji seems excited by whatever she has planned for your people. I look forward to being amused by it later.\n\nZolani can show you a way down dat does not involve falling.", objectives = "Establish your Embassy.", completion = "Welcome to de Vault of Kings, <name>. We move new treasures dat we find into dis room, all because of dis object on de wall.\n\nDis object dates back farther than anything we know. It is my hope dat I can one day discover its true purpose.\n\nI should not keep you, however. I am sure you have pressing business with Princess Talanji." }
WordHunterWoW_QuestEN[46932] = { title = "A Tad More Corruption", description = "", objectives = "" }
WordHunterWoW_QuestEN[46933] = { title = "Felrglrglrglrgl", description = "", objectives = "" }
WordHunterWoW_QuestEN[46935] = { title = "The Shadow of the Sentinax", description = "This device appears to be used to relay messages to the large demon ship up above. Unfortunately, it is cracked and unresponsive.\n\nPerhaps someone at Deliverance Point will know more about these beacons.", objectives = "Bring the Broken Sentinax Beacon to Warmage Kath'leen in Deliverance Point.\n\nProvided item:", completion = "The Legion uses these beacons to communicate with their fleet up above. If we were to find more of these..." }
WordHunterWoW_QuestEN[46938] = { title = "Alone in the Abyss", description = "Champion, we will suffer the same fate as the Army of the Light if the Legion fires that infernal weapon upon us.\n\nWe must descend into the siege camp below and destroy it while we still can!", objectives = "Speak to Grand Artificer Romuul to disembark the Vindicaar.", completion = "Welcome to Argus, homeworld of the Burning Legion." }
WordHunterWoW_QuestEN[46939] = { title = "Monk Finale", description = "", objectives = "" }
WordHunterWoW_QuestEN[46940] = { title = "Using Lost Knowledge", description = "I'm not sure you realize what this tome could mean for us. We can find even more knowledge on your artifacts to help the war effort!\n\nLet's begin immediately. On your command, we stand by to begin researching again.", objectives = "Start a Research Work Order.", progress = "Yes, Highlord?", completion = "Excellent! Please check back in a while for a progress update." }
WordHunterWoW_QuestEN[46941] = { title = "The Path Forward", description = "<Velen stares beyond the arena for a time.>\n\nWe must continue on, but I feel Eredath is far from finished with us. We should take advantage of this relative safety while we still can.\n\nI will place a signal beacon that will allow the Vindicaar to lock onto our location. Romuul will send us our means of returning to the Vindicaar if there is a need.", objectives = "Call down a Lightforged Beacon.", progress = "Much remains to be seen, <name>. Argus has not forgotten us.", completion = "The way forward is clear, and we have the Army of the Light at our side." }
