WordHunterWoW_QuestEN[46946] = { title = "To the Forge It Goes...", description = "This cloak is too tattered to be usable, but can be obliterated at the Obliterum Forge in Dalaran.", objectives = "Take the Gladiator's Tattered Cloak to the Obliterum Forge in Dalaran and use the forge to obliterate it, then take the result to Violet Shadowmend in Winderunner's Sanctuary.", progress = "Visit the forge recently, have we?", completion = "If you find any other unwanted spoils of war, obliterate them at the forge and I can help you find something more desirable." }
