WordHunterWoW_QuestEN[47000] = { title = "The Council's Call", description = "I'm sorry that I haven't kept your apprised of the situation. We needed more actionable information before bringing the matter before you.\n\nThe Council of the Six has been investigating Legion threats outside of the Broken Shore. I believe this scroll to be the final piece of information we need.\n\nMeet me in Dalaran at the Violet Citadel. We will need the other members of the Council.", objectives = "Seek out the Council of Six in the Violet Citadel.", completion = "<Khadgar gives you a knowing nod.>\n\nI'm glad you came, Huntmaster." }
WordHunterWoW_QuestEN[47001] = { title = "Rare Elite 21", description = "", objectives = "" }
WordHunterWoW_QuestEN[47002] = { title = "The Crown of the Triumvirate", description = "We begin our search now, {name}.\n\nThe Crown of the Triumvirate was created to spread the Light's touch to all. With it, our culture thrived.\n\nWhen I fled Argus with the Draenei, I took one shard of the Crown with me to ensure that it would not fall into the wrong hands.\n\n<Velen tips his staff forward and gestures to the central crystal.>\n\nKil'jaeden and Archimonde's fragments are still here. I will seek them out, but you will need to safeguard me while I search.\n\nStay close, my friend.", objectives = "Protect Velen while he locates fragments of the Crown of the Triumvirate." }
WordHunterWoW_QuestEN[47003] = { title = "Restoration: The Bradensbrook Investigation", description = "We have uncovered forged orders from the Shore. They have a fel influence about them. They guide the reader to believe they are legitimate. It orders Black Rook Hold to attack a \"demonic enclave\" just south of their walls. There's only one enclave they could be talking about, Bradensbrook!\n\nIs it possible these would be able to convince the undead to attack Bradensbrook? You should head there immediately and either warn them, or render aid.\n\nSpecialization: Restoration Shaman", objectives = "Go to Bradensbrook in Val'sharah.", completion = "A bit late for the warning, eh? Still, I appreciate that we haven't been forgotten." }
WordHunterWoW_QuestEN[47004] = { title = "Restoration: The Bradensbrook Investigation", description = "We have uncovered forged orders from the Shore. They have a fel influence about them. They guide the reader to believe they are legitimate. It orders Black Rook Hold to attack a \"demonic enclave\" just south of their walls. There's only one enclave they could be talking about, Bradensbrook!\n\nIs it possible these would be able to convince the undead to attack Bradensbrook? You should head there immediately and either warn them, or render aid.\n\nSpecialization: Restoration Druid", objectives = "Go to Bradensbrook in Val'sharah.", completion = "A bit late for the warning, eh? Still, I appreciate that we haven't been forgotten." }
