WordHunterWoW_QuestEN[47037] = { title = "Balance: The Twisted Twin", description = "I have a request from an old friend, Karam Magespear, to help find his brother, Raest. Karam fears that Raest is dealing with dark powers, and wishes to stop him.\n\nOriginally Raest trained with the Kirin Tor, but such were his aspirations of power that he turned to the forbidden art of Necromancy. He was discovered and expelled from our order.\n\nFind Karam in the Legerdemain Lounge and see if you can lend a hand.\n\nSpecialization: Balance Druid", objectives = "Meet with Karam Magespear at the Legerdemain Lounge in Dalaran.", completion = "You come from the Kirin Tor? So you'll help me find my brother?" }
