WordHunterWoW_QuestEN[47049] = { title = "Demonology: Fate of the Tideskorn", description = "A scout from Stormheim arrived yesterday with a significant discovery - these ancient scrolls. Within they contain a Valkyra prophecy of a new vrykul ruler - one who could turn the Tideskorn against the Legion.\n\nIt complicates matters that this vrykul may in fact be Skovald's heir.\n\nTake the scrolls, find the heir, and bring her to the Valkyra. I think the outcasts they refer to are the vrykul of Jandvik, so that would be a good place to start.\n\nSpecialization: Demonology Warlock", objectives = "Search Jandvik for the vrykul mentioned in the scrolls.", completion = "Yes, outsider? What business do you have here?" }
WordHunterWoW_QuestEN[47050] = { title = "Enhancement: Fate of the Tideskorn", description = "A scout from Stormheim arrived yesterday with a significant discovery - these ancient scrolls. Within they contain a Valkyra prophecy of a new vrykul ruler - one who could turn the Tideskorn against the Legion.\n\nIt complicates matters that this vrykul may in fact be Skovald's heir.\n\nTake the scrolls, find the heir, and bring her to the Valkyra. I think the outcasts they refer to are the vrykul of Jandvik, so that would be a good place to start.\n\nSpecialization: Enhancement Shaman", objectives = "Search Jandvik for the vrykul mentioned in the scrolls.", completion = "Yes, outsider? What business do you have here?" }
