WordHunterWoW_QuestEN[47097] = { title = "A Walk to Remember", description = "It's good to have you at my side, {name}.\n\nI've come to the Broken Shore to see, for myself, the price that my father... that the Alliance has paid to protect our world.\n\nAs long as I am blind to the suffering and sacrifices of my people, I will never be able to lead them to peace.\n\nTime is short, we should move onward.", objectives = "Escort King Anduin to Soul Ruin at the Broken Shore.", completion = "This place is filled with indescribable horrors. To think... I was blind to all of this pain and suffering." }
WordHunterWoW_QuestEN[47098] = { title = "Out Like Flynn", description = "I'm relieved you woke up! Having to carry you would have made this job far less appealing.\n\nThe name's Flynn, and my client in Boralus is paying me a king's bounty to break you out of here.\n\nYou, my friend, are incarcerated in Tol Dagor. Used to be a legit prison... 'til the Ashvane Trading Company bought it. Now it's Priscilla's own personal fortress, riddled with scum on both sides of the bars.\n\nWasn't hard to bribe my way into this cell. Now we just have to get out.\n\nNot to worry. I have a plan!", objectives = "Escape Tol Dagor with Flynn.", progress = "Is that the new powder Flynn was talking about?\n\nI'll take it for safekeeping.", completion = "It's hard to believe the Lord Admiral would willingly hand you and her daughter over to Lady Ashvane.\n\nShe must have had her reasons... right?" }
WordHunterWoW_QuestEN[47099] = { title = "Get Your Bearings", description = "I think a proper introduction is in order!\n\nMy name is Taelia, member of the Proudmoore Guard and squire of Sir Cyrus Crestfall.\n\n<Taelia salutes firmly.>\n\nCyrus asked me and Flynn to break you out of that Ashvane prison and get you settled in here at the market, but he neglected to mention that you're with the Alliance.\n\nI must say, it's an honor.\n\nLet's get you up to speed.", objectives = "Visit the Ferry Dock, the Snug Harbor Inn, the Tradewinds Counting House, and the Flight Master in Tradewinds Market.", progress = "I'll bring you to Cyrus after a brief tour of the market.", completion = "Ready to meet the Harbormaster himself?" }
WordHunterWoW_QuestEN[47100] = { title = "Arkhaan's Pain", description = "Darkness envelops us... the Light has gone from this place...\n\n<Arkhaan mumbles to himself before noticing you are still talking to him.>\n\nArkhaan could not save them. Brothers. Sisters. Whispers twisted them. The Light cannot see them. It turns away from us.\n\nArkhaan failed.\n\n<Arkhaan stares off into space.>", objectives = "Slay 12 Broken in Oronaar Collapse.", progress = "<Arkhaan mutters incoherently to himself.>", completion = "<The broken peers suspiciously at his surroundings, avoiding eye contact with you.>" }
WordHunterWoW_QuestEN[47101] = { title = "Arkhaan's Prayers", description = "<As you near the statue, a somber voice fills your mind.>\n\n\"You must resist the shadow's pull. Come to me, brothers and sisters. Be whole within the Light.\n\nLet Arkhaan show you the way home.\"\n\n<The rest of the message is garbled, though the nearby broken seem to be gnawing on pieces of the statue.>", objectives = "Collect 5 Fragmented Prayers.", progress = "Did you find anything interesting?", completion = "What is this... a sermon? Fascinating." }
WordHunterWoW_QuestEN[47102] = { title = "The Mysterious Missive", description = "<On the body, you find a missive emblazoned with the seal of the Army of the Light. \n\nIf the messenger was killed to prevent the letter's delivery, its contents must be of great import.>", objectives = "Search near the Xenedar for someone with knowledge of the Sealed Missive.", progress = "Our fight goes on, champion. Argus must fall.\n\nWhat is that you've found?", completion = "You've found one of our scouting reports? It was overdue, and I feared it had been intercepted by the enemy.\n\n<The captain looks over the letter.>\n\nYes, this is what I've been expecting. The Legion is planning something and this is the breakthrough we've been looking for!" }
WordHunterWoW_QuestEN[47103] = { title = "Journey to Nazmir", description = "It is time to put an end to de blood trolls in Nazmir before their monstrous horde descends upon Zuldazar.\n\nMy most loyal followers are willing to come with me to dat cursed place. But it will not be enough.\n\nI am relieved dat you and de Horde are willing to help. Rokhan and his darkspears are getting ready to leave.\n\nI will finish my preparations here. Meet with Rokhan and make your way to Nazmir, I will see you there.", objectives = "Meet with Rokhan near flight master Rokota in Dazar'alor.", completion = "<name>! You ready ta go ta a cursed swamp?" }
WordHunterWoW_QuestEN[47104] = { title = "Imprisoned Inquisitor", description = "This report states that the Legion seeks to free an imprisoned Legion inquisitor called Raalgar, a demon from here on Argus who cannot be killed because of a secret magic he alone possesses. \n\nBecause of his immortality, he is held in the Arcatraz in Tempest Keep.\n\nThe Light Mother told us of that naaru stronghold, but I've never set eyes upon it myself, {name}. Turalyon mentioned the Vindicaar has some connection to Tempest Keep. Perhaps your ship's engineer knows more.", objectives = "Travel to the Vindicaar and ask Grand Artificer Romuul about High Inquisitor Raalgar.", completion = "High Inquisitor Raalgar? A fearsome creature but he has been held securely in the Arcatraz at Tempest Keep for a very long time. \n\nIf the Legion plans to free him then they must know that he is particularly dangerous to us." }
WordHunterWoW_QuestEN[47105] = { title = "Into The Darkness", description = "We are in Nazmir to stop de blood trolls from destroying Zuldazar. Dis is de start of our campaign to end dem.\n\nDese monsters want my kingdom and its people destroyed. We are going destroy dem first.\n\nMy father thinks de blood troll threat will go away on its own, like it did in de past. But things are different now.\n\nRokhan and de others are moving north of here to establish a camp for us to stay in, den dey will join us in de fight.\n\nAre you ready?", objectives = "Look for signs of blood trolls ahead with Princess Talanji.", completion = "De blood trolls are monsters, <name>. Dey are all around us. We stop dem today." }
WordHunterWoW_QuestEN[47106] = { title = "7.2 Raid - Tomb - 1 - Quest Item Reward - Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47107] = { title = "7.2 Raid - Tomb - 2 - Quest Item Reward - Tracking Quest", description = "", objectives = "" }
