WordHunterWoW_QuestEN[47112] = { title = "Lost Souls", description = "Never in my life have I beheld such destruction... such misery. The very ground we walk on us paved with the bones of our allies.\n\nEven now I can see the lost spirits of Alliance soldiers wandering the ruins.\n\nI cannot leave this place without putting the souls of our brave soldiers to rest. We owe them... I owe them that much.", objectives = "Release 10 Lost Souls.", completion = "Thank you, <name>. A peaceful rest is all we have to offer those who have made the ultimate sacrifice for the Alliance... for Azeroth." }
WordHunterWoW_QuestEN[47114] = { title = "Tomb of Sargeras: The Tomb's Mistress", description = "Slay the Naga Mistress who is tainting the denizens of the ocean beneath the Tomb.", objectives = "Defeat Mistress Sassz'ine in the Tomb of Sargeras.", progress = "How are you finding the challenges of the Tomb of Sargeras?", completion = "Were you able to overcome the Tomb of Sargeras?" }
