WordHunterWoW_QuestEN[47130] = { title = "Improper Burial", description = "De blood trolls are gathering de corpses of my people for their blood magic. Dis ends today.\n\nI will take care of de corpses here. Take dis torch. Its fires are blessed by priests of Bwonsamdi, de loa of death. \n\nBurn any corpses of my people dat you see. Each corpse burned means less power for dese monsters' blood magic.", objectives = "Use the Ceremonial Torch on Zandalari corpses.", completion = "My people deserve better dan dis. When dis is done, we must properly honor dem in Zuldazar." }
WordHunterWoW_QuestEN[47132] = { title = "Fel Fire and Ice", description = "", objectives = "" }
WordHunterWoW_QuestEN[47133] = { title = "Rare Mob Daily Bonus", description = "", objectives = "" }
WordHunterWoW_QuestEN[47134] = { title = "Foiling the Legion's Jailbreak", description = "High Inquisitor Raalgar has some connection to the fel here on Argus that makes him unkillable. Long ago, the naaru imprisoned him on the Arcatraz. \n\nWhen the forces of Kael'thas Sunstrider attacked the citadel, we were forced to flee on the Exodar.\n\nSome Legion prisoners escaped the Arcatraz when last the Legion invaded Azeroth, but Raalgar did not. Stop them from freeing him and I will study the source of his immortality so it can be broken. \n\nI can get you close. The rest is up to you.", objectives = "Find High Inquisitor Raalgar before the Legion frees him.", progress = "We must stop High Inquisitor Raalgar!", completion = "You did your best, <name>, but the demons won this round.\n\nIt won't take Raalgar long to gather his power to attack us. But I have learned the source of his immortality while you were gone!" }
WordHunterWoW_QuestEN[47135] = { title = "For Their Own Good", description = "", objectives = "" }
WordHunterWoW_QuestEN[47137] = { title = "Champions of Legionfall", description = "The battle to reclaim the Broken Shore is straining our resources. We cannot afford to relent, lest the Legion undo all that we have accomplished.\n\nThe members of your order have given much, but more is needed.\n\nRally your champions and do what you must to bolster their ranks. There may be untapped power in this land that will turn the tide of war in our favor.", objectives = "Return to your class order hall and recruit a new champion.", completion = "Another powerful ally recruited to our cause!\n\nYou have bolstered our strength against the Legion once more, <name>." }
WordHunterWoW_QuestEN[47139] = { title = "Mark of the Sentinax", description = "The Sentinax rains down terror upon the Broken Shore, unleashing hordes of demons that menace our forces. The fiends seek to stop us from taking the Tomb.\n\nThey will fail.\n\nLure out the strongest among their vile ranks. Slay them and seize the marks they bear. Make the Legion fear our strength!", objectives = "Collect 50 Marks of the Sentinax.", progress = "The Sentinax is well defended, but we will crush everything it sends against us.", completion = "Even the mightiest demons unleashed by the Sentinax have fallen before you.\n\nGood. The Legion will be driven from our world, no matter what it takes." }
WordHunterWoW_QuestEN[47144] = { title = "First Win of the Day (BG Brawl)", description = "", objectives = "" }
WordHunterWoW_QuestEN[47148] = { title = "Something Different", description = "Even the most bloodthirsty combatants eventually grow weary and turn their backs to the unending struggle of war. They seek a new way to test their mettle and destroy their enemies. \n\nJoin the Brawl in progress and fight your opponents in a limited time event that tosses traditional rules aside.", objectives = "Win a PvP Brawl.", progress = "Even I could not foresee the strange ways in which you would fight your enemies <name>.", completion = "Even I didn't see that coming." }
