WordHunterWoW_QuestEN[47180] = { title = "The Pulsing Madness", description = "This broken still retains some of his sanity, though not all of it.\n\nI can sense some Void influence nearby, but it is isolated to small pockets. Dispelling these manifestations should help our friend here clear his mind.\n\nPerhaps we can use the prayer fragments you found, as they still contain some Light energy.\n\nI will try and make sense of his chattering in the meantime. Maybe we can learn something about what is happening here.", objectives = "Dispel 5 Void Manifestations.", completion = "I can feel the Void's influence retreating. Perhaps now we can find out what happened here." }
WordHunterWoW_QuestEN[47181] = { title = "The Smoking Gun", description = "The Ashvane Company doesn't know it yet, but throwing you into Tol Dagor was the biggest mistake they've ever made.\n\nThat new powder we swiped could be the key to bringing them down.\n\nFirst, how about we give everyone a little demonstration of just how powerful this stuff is?\n\n<Flynn loads a pinch of the glittering powder into his pistol.>\n\nGo ahead, take a shot at that barrel over there.", objectives = "Fire Flynn's Pistol at the Water Barrel in the Harbormaster's Office.", progress = "Don't worry, it won't hurt anyone.\n\nI think.", completion = "Adds a kick, don't it?" }
WordHunterWoW_QuestEN[47182] = { title = "Long Overdue", description = "I have learned much. High Inquisitor Raalgar has moved to a base near the Legion citadel across the mountains. This is where he keeps the Fel Heart of Argus, the source of his immortality, and it is powered by wells leading directly to the core of Argus. \n\nHe is preparing to attack so you will strike first. Mark the location of the wells and I will rain holy fire upon them with the Vindicaar's guns. With that connection to the fel on Argus broken, Raalgar can be killed and the Fel Heart retrieved.", objectives = "Mark the Argussian Heartwells for the Vindicaar's guns, kill the Legion garrison, and retrieve the Fel Heart of Argus from High Inquisitor Raalgar.", progress = "Have you dealt with High Inquisitor Raalgar yet?", completion = "You are a true hero, <name>. Even though the demons freed Raalgar and thought him immortal, he was no match for you! Perhaps the Fel Heart will be of use to you. It is now available in the Matrix Core." }
WordHunterWoW_QuestEN[47183] = { title = "Arkhaan's Plan", description = "Arkhaan remembers. He remembers something that will... yes... will save us.\n\nFollow Arkhaan. Isolon calls! We will offer soft words to the Light. The Light will banish the darkness.\n\n<Arkhaan eyes Alleria warily.>\n\nArkhaan will watch that one closely.", objectives = "Follow Arkhaan to Isolon.", completion = "I should have seen this coming." }
WordHunterWoW_QuestEN[47184] = { title = "Arkhaan's Peril", description = "Whatever called to him, it cannot have good intentions. We need to go in after him.\n\nBefore we step through this portal, {name}... ensure you are prepared to fight. The Void's influence is rarely peaceful.", objectives = "Enter the Void Tear and deal with Arkhaan.", progress = "We must address this threat.", completion = "As I said, the Void's influence is rarely peaceful. We must press on." }
WordHunterWoW_QuestEN[47185] = { title = "Invasion Boss Weekly Bonus", description = "", objectives = "" }
WordHunterWoW_QuestEN[47186] = { title = "Sanctum of the Sages", description = "Sounds like you'll be working with us for awhile.\n\nCyrus will charter a naval transport between here and Stormwind, but I expect you'll want something a bit faster for day to day use.\n\nHead back upstairs and take a left when you get outside. You'll find an old study where the Tidesages used to conduct their magic rituals.\n\nSurely your Alliance mages have already sensed its power.\n\nInform them they may open their portals there. The harbor guards will keep the room secure.", objectives = "Speak with a 7th Legion Mage in the Sanctum of the Sages.", progress = "The Tidesages abandoned that place months ago when they pulled back to their monasteries. We still don't know why.", completion = "All set?\n\nGood timing. I have your briefing ready." }
WordHunterWoW_QuestEN[47188] = { title = "The Aid of the Loa", description = "De blood trolls are stronger than ever, thanks to dis G'huun... and now dey are empowering a giant construct!\n\nWe need a plan to destroy dat construct, G'huun, and de blood trolls. It is not going to be easy.\n\nBut I have an idea.", objectives = "Hold council with Talanji and Rokhan to decide your next steps.", progress = "We have a lot to talk about.", completion = "Getting de loa's help may be de only chance we have at stopping de blood trolls. \n\nLet's get moving." }
WordHunterWoW_QuestEN[47189] = { title = "A Nation Divided", description = "Kul Tiras must be unified before it can be of any help to the Alliance.\n\nLet's get you briefed on the current situation in each of our major territories.\n\nThen you can take a look at the map behind me and make the call on where you want to go first.", objectives = "Inspect the Scouting Map in the Harbormaster's Office.", progress = "Have you figured out your next move? Use the planning map to help you decide.", completion = "We'll support you however we can." }
WordHunterWoW_QuestEN[47191] = { title = "Illusion - Demonic Tyranny", description = "", objectives = "" }
WordHunterWoW_QuestEN[47193] = { title = "Battle for Azsuna", description = "", objectives = "" }
WordHunterWoW_QuestEN[47194] = { title = "Battle for Highmountain", description = "", objectives = "" }
WordHunterWoW_QuestEN[47195] = { title = "Battle for Stormheim", description = "", objectives = "" }
WordHunterWoW_QuestEN[47196] = { title = "Battle for Val'sharah", description = "", objectives = "" }
WordHunterWoW_QuestEN[47198] = { title = "They Want Us Alive", description = "Blood troll poisons are made to paralyze, not kill. See, dey want us alive.\n\nI do not feel good thinking about why.\n\nI am making antitoxins as quickly as I can, but I need someone like yourself to get out dere and test dem. Take what I have made so far and see if we can get those soldiers back on their feet.", objectives = "Cure 8 Wounded Captives.", completion = "It worked? Good! I shall have some of de wounded help me craft more." }
WordHunterWoW_QuestEN[47199] = { title = "The Blood Gate", description = "We just received word that the Northern border is under heavy attack by an army of blood trolls.\n\nKing Rastakhan has called for reinforcements.\n\nYou are more familiar with that threat than any of us. Go and do what you can to help them.", objectives = "Journey to the Blood Gate.", completion = "Welcome to de edge of my domain, in more ways than one." }
WordHunterWoW_QuestEN[47200] = { title = "Ticks", description = "Kill those bloodbellies before dey take off with all of my soldiers! I will have my troops prepare for a flanking charge.", objectives = "Slay 6 Bloodbelly Fliers.", progress = "We are losing too many, too quickly.", completion = "At last, some breathing room. Now we must press our advantage." }
WordHunterWoW_QuestEN[47201] = { title = "Rokhan", description = "My scouts have informed me dat your Darkspear shadow hunter, Rokhan, has returned from Nazmir. He is pinned down at de far side of de gate.\n\nWe need to break dis onslaught with a flanking maneuver.\n\nOld Rotana is in position. Mount up and smash through de side of those blood troll ranks.\n\nOnce down dere, try to find Rokhan.\n\nOh, and {name}, be careful. A lot of dark magic is being tossed around down dere.", objectives = "Ride the Old Rotana into the fray and then find Rokhan.", completion = "Ha! Thought I be singin' with Bwonsamdi soon. But no." }
WordHunterWoW_QuestEN[47202] = { title = "A Personal Message", description = "The time has come for me to travel to the Broken Shore and see, for myself, the place where my father died.\n\nIf I am to be the king my father was... the king Stormwind deserves, I must know firsthand the threat my people face.\n\nPlease tell my advisors that I've gone to the Broken Shore. If I told them myself they'd only try and stop me.\n\nI'll wait for you at Deliverance Point. Farewell.", objectives = "Speak with Prophet Velen.", completion = "<Velen listens closely to your words as you tell him of King Anduin's plan.>\n\nThe Broken Shore is a dangerous place... far too dangerous to travel alone. But perhaps this journey is necessary for Anduin to find peace.\n\nWhen the moment is right, I'll inform King Greymane of Anduin's departure. Until then, go and see that Anduin is not alone on the Broken Shore. I trust that you will return him safely." }
WordHunterWoW_QuestEN[47203] = { title = "Throwing Shade", description = "That was Locus-Walker. He taught me all that I know about the Void, and he still has more to teach me.\n\nIf he is here, then the ethereals' presence only intrigues me further. I had thought him the only one of his kind, but now that I have seen another tangling with the Void...\n\nCome, we must play his game if we want to learn what he knows. He appears to have gone toward the Umbra Hollows to the north.", objectives = "Investigate the Umbra Hollows with Alleria and Locus-Walker.", progress = "Move quickly, or we may lose him.", completion = "<Alleria seems momentarily speechless.>" }
WordHunterWoW_QuestEN[47204] = { title = "The New Frontline", description = "Kill anything ya see dat not a Zandalari!", objectives = "Slay Blood Troll forces.", completion = "It may seem like a lot, but trust me when I say we saw a lot more comin' when on our way here." }
WordHunterWoW_QuestEN[47205] = { title = "Warmother", description = "Old Rotana be cursed by da warmother dese vile blood trolls brought with dem. We need to take her down so we can get dis old direhorn back in da field.", objectives = "Slay Warmother Shazraka.", completion = "Dat vile creature took out half da scouts who came with me. Ya did good." }
WordHunterWoW_QuestEN[47207] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47208] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47209] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47210] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47211] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47212] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47213] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47214] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47215] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47217] = { title = "Sources of Darkness", description = "I think I understand what he was trying to show us, {name}.\n\nI feel a surge of power building ahead. They must be cultivating the Void, calling it here.\n\nWe need to stop them before they plunge this entire city into shadow. Find the source and cut it off by any means necessary.\n\nLocus-Walker and I have unfinished business to attend to.", objectives = "Deactivate 5 Void Harvesters.", progress = "Locus-Walker and I have some unfinished business to attend to.", completion = "We buy time but nothing more." }
WordHunterWoW_QuestEN[47218] = { title = "The Shadowguard Incursion", description = "As you have surely gathered by now, a certain subset of my people have tragically succumbed to the call of the Void.\n\nI had hoped to find more who possess the necessary strength of mind. I am disappointed to find such an utter lack of resistance.\n\nIt cannot be helped. To advance your cause, and mine, we will need to eradicate these weak-willed beings.", objectives = "Slay 15 Shadowguard Ethereals.", progress = "Walking the razor's edge does have risks, <name>.", completion = "It is good to know we can share a common goal. Perhaps I will find some use for your kind yet." }
WordHunterWoW_QuestEN[47219] = { title = "A Vessel Made Ready", description = "After some consideration, I have decided to allow Alleria another opportunity to pursue her destiny.\n\nI suppose you want to know what that means, mortal.\n\n<Locus-Walker laughs.>\n\nMeet us deep in the Shadowguard camp ahead- my brethren are preparing a summons that will provide adequate energy for Windrunner to begin again.\n\nWitness what happens when you harness the Void's power.", objectives = "Defeat Nhal'athoth and collect his heart.", progress = "I see the path clearly, <name>.", completion = "<Alleria takes the heart in her hands.>\n\nThis is the next step, <name>. Thank you for bringing me to this point." }
WordHunterWoW_QuestEN[47220] = { title = "A Beacon in the Dark", description = "That was... an intense experience.\n\n<Alleria rubs her forehead.>\n\nIt is difficult to focus. I need you to return to Velen. Give him this.\n\n<She places something cold and dense in your palm.>\n\nI feel as though he should have it, though I am not sure why.\n\nTell him all that we have learned. I am sure Romuul will have been watching our progress. With any luck, a beacon is already headed our way.", objectives = "Take the Remnant of Nhal'athoth to Velen on the Vindicaar.", progress = "What is this? Such darkness...", completion = "What is it you bring, <name>?\n\n\n\nIntriguing..." }
WordHunterWoW_QuestEN[47221] = { title = "The Hand of Fate", description = "{name},\n\nWe have won many battles against the Burning Legion, but it is time to end this war once and for all. \n\nFinal preparations have begun to depart for Argus.\n\nMake haste to Stormwind Harbor. A ship awaits you there to grant you and your allies passage to Azuremyst.", objectives = "Meet your escort to the Exodar at Stormwind Harbor.", completion = "I'm glad you were among those called for the expedition to Argus. There will be plenty of fighting ahead." }
WordHunterWoW_QuestEN[47222] = { title = "Two If By Sea", description = "The Tomb of Sargeras was only the beginning. If we do not destroy the Legion utterly, they will return even stronger.\n\nWe will travel to Azuremyst by sea to avoid drawing unnecessary attention. The less time the Legion has to react to our assault, the better.\n\nJust say the word when you are ready to depart.", objectives = "Speak to Vereesa Windrunner to set sail for the Exodar.", completion = "May the Light protect us all this day." }
WordHunterWoW_QuestEN[47223] = { title = "Light's Exodus", description = "Prophet Velen and the others have gathered within the Vault of Lights below. There is an entrance just down this path.\n\nWe should find the Prophet at once so that we do not stall the invasion.", objectives = "Meet Prophet Velen in the Vault of Lights in the Exodar.", completion = "Thank the Light you have arrived." }
WordHunterWoW_QuestEN[47224] = { title = "The Vindicaar", description = "Everything is prepared for our assault. We need only establish the beacon to transport us to the vessel.\n\nOnce the beacon arrives, place your hand upon its surface to board the Vindicaar, the instrument of our retribution.", objectives = "Board the Vindicaar.", progress = "Today marks the beginning of the Legion's downfall.", completion = "I have waited many years for this day.\n\nBehold the triumph of the draenei, the Vindicaar!" }
WordHunterWoW_QuestEN[47226] = { title = "The Orphaned Hatchling", description = "<The surviving hatchling bleats piteously as it gazes at its mother's corpse.\n\nIt inspects you hopefully and seems to want to follow you.\n\nPerhaps you can find someone in Warbeast Kraal who can care for it?>", objectives = "Find someone in Warbeast Kraal who cares for young direhorn.", completion = "Are you de Hordemon I have been hearing so much about? I expected you to be a bit larger. Ha!\n\nHey! What do you have dere?" }
WordHunterWoW_QuestEN[47228] = { title = "Xibalan Ecology", description = "I had really hoped this area would be more hospitable.\n\nThe Zandalari have been no help whatsoever in clearing this space for archaeological exploration. Before we can even begin to uncover Xibala's secrets, we must make it safe for those less combat savvy to do their work.\n\nYou will find the ruins ahead infested with all manner of carnivorous beasts. The few intrepid explorers who ventured within have all failed to return.\n\nLocal ecology will not stand in the way of progress, {name}. Understand?", objectives = "Slay 8 Xibalan predators.", completion = "I hear this region is very supportive of such life. Their numbers will recover... elsewhere." }
WordHunterWoW_QuestEN[47229] = { title = "Bulwark of Torcali", description = "We got Old Rotana up on her feet again. Load up an' take her reins.\n\nGive us some cover so Talanji can fight her way in from her side.", objectives = "Ride Old Rotana into battle against the blood trolls.", completion = "Thank you! Though we must not stay here. More blood trolls are coming. Where is my father?" }
WordHunterWoW_QuestEN[47235] = { title = "Scrying for the Eye", description = "On behalf of the Horde we seek a relic called the Eye of Xibala.\n\nThe locals have been no help whatsoever and Miss Tae'shara insists that we use her survey equipment.\n\nI abhor guesswork. Instead we shall use a more direct method: scrying.\n\nI will mark three locations on your map. I would like you to place a scrying vessel at each of them. I will use their measurements to isolate the relic's location and we will be on our way.", objectives = "Place 3 Scrying Vessels in Xibala.", completion = "Excellent work. Allow me to review the results and we will be on our way." }
WordHunterWoW_QuestEN[47238] = { title = "The Seat of the Triumvirate", description = "Even with the Sigil of Awakening in hand, the Crown cannot save us until it is whole.\n\nThat is why we must enter the Seat of the Triumvirate, even knowing that L'ura awaits us there.\n\nThis is a dire task, one that I would not ask if it were not completely necessary.\n\nWe will descend together. Come.", objectives = "Seek the Crest of Knowledge.", progress = "Such a task I cannot undertake alone. Your help is greatly appreciated, <name>.", completion = "This is grave news indeed. It would be wise to follow Alleria's lead from here." }
WordHunterWoW_QuestEN[47241] = { title = "The Shadow of Death", description = "We have four loa, but we only know where one is: Bwonsamdi.\n\nAs uncomfortable as it makes me, I am prepared to do anything to stop de blood trolls... even if it means dealing with de loa of death.\n\nAges ago, Bwonsamdi had a temple here in Nazmir. My scrying has revealed a few locations to de north where I sense a magical presence. Search dem for clues.\n\nHurry, {name}. Zuldazar will fall if we cannot obtain Bwonsamdi's help!", objectives = "Search for clues to the location of the loa, Bwonsamdi.", progress = "Having any luck in de search?", completion = "You are looking for Bwonsamdi's temple? You must be desperate to be going dere.\n\nLucky for you, I am headed dat way myself." }
WordHunterWoW_QuestEN[47244] = { title = "A Culling of Souls", description = "Only two types enter Bwonsamdi's temple anymore: those looking to make a deal with death, and de dead. You do not stink, so I guess you are de former.\n\nI am headed to de temple myself, so how about a trade?\n\nSee de land across de bridge? Dere is a witch named Najima dat I have been tracking. De blood trolls are corrupt to de core, but their souls are useful as offerings to Bwonsamdi. She is too strong for me to deal with, but if you can slay her, I will take you to de temple.\n\nI give you my word.", objectives = "Defeat Blood Witch Najima.", completion = "Dis should do it. Her soul is perfect for an offering.\n\nNow, before we go to de temple, there is one more thing to do..." }
WordHunterWoW_QuestEN[47245] = { title = "Getting the Message", description = "Da loa be powerful, but we be needin' soldiers if we gonna have a chance of stopping dem blood trolls from building dat giant of theirs. If we not be able ta destroy dat thing before it be finished, den Zuldazar and all of our people gonna be dead!\n\nWe need da help of da Horde!\n\nWord of da situation already be sent to da warchief. As soon as we be hearin' her reply, we can mov-- \n\nWait... what be dat noise?", objectives = "Investigate the disturbance.", completion = "Goblins... of all da worthy units in da Horde, why da warchief have ta be sendin' us goblins?" }
WordHunterWoW_QuestEN[47246] = { title = "Remnants of the Damned", description = "Ever since da spirits have begun calling upon this \"G'huun\" me temple has been covered with the unbearable taint of the undead. \n\nDa undead be an abomination, but da bloodstones that create them be powerful. They could be of use ta Bwonsamdi.\n\nIf you wish ta show me your fervor, then cleanse me temple of their filth and bring me their bloodstones.", objectives = "Collect 6 Decaying Bloodstones for Bwonsamdi." }
WordHunterWoW_QuestEN[47247] = { title = "That Which Haunts the Dead", description = "Bwonsamdi knows why ya be here. Ya be seekin' me favor.\n\n<Bwonsamdi ponders you silently.>\n\nA test, ta see if ya be worth Bwonsamdi's time.\n\nDere be spirits whose prayers sing of something called \"G'huun.\" Dey pay me homage no more. I will not allow da desecration of me own temple!\n\nGo and subdue da strongest of da ancient spirits.\n\nIf ya do dis for me, ya may be worth da trouble after all.", objectives = "Defeat Hex Priestess Tizeja and Warlord Malaja.", completion = "Ah, I feel their souls strengthening me powers. I knew ya be worth Bwonsamdi's time." }
WordHunterWoW_QuestEN[47248] = { title = "'Til Death Do Us Part", description = "I don't know who you are, but I need your help.\n\nMy precious Valjabu always told me he didn't care dat he took de vows of a priest... we would be together forever. \n\nWell, my time came to pass, and I knew I'd not be able to go on without him. I came back and have been waiting in dis spot for... it seems forever, and Valjabu never showed!\n\nI've been walking around dis world for far too long.\n\nPlease, I beg you, bring a memento of my Valjabu back to me!", objectives = "Obtain Valjabu's Tusk Ring.", progress = "Did you find Valjabu yet? His urn is around here somewhere.", completion = "<Salazae looks distraught.>\n\nOh! Valjabu... why did you go on without me?\n\n<A ghostly tear drops from her eye.>\n\nThank you, stranger. Now I can pass on with no regrets." }
WordHunterWoW_QuestEN[47249] = { title = "Soulbound", description = "Ya did well with me tasks. I be thinkin' ya show promise. Ya might be worthy of a deal.\n\nVery well, I pledge ta lend ya me powers ta use against ya foes. In exchange, ya be sendin' one million souls ta Bwonsamdi! No need ta look shocked, ya be plenty capable of doing dis.\n\nCome, meet with me at da Court of Spirits. Dere, we will finalize our agreement.", objectives = "Speak to Bwonsamdi in the Court of Spirits and complete the ritual.", completion = "Dese blood trolls and their \"god\" G'huun, dey be far more of a threat than I realized. Da ritual ta seal da pact between ya and I be incomplete, but considerin' da circumstances, I tink we can skip da formalities.\n\nAs long as da price be paid, ya can count on Bwonsamdi's aid." }
WordHunterWoW_QuestEN[47250] = { title = "We'll Meet Again", description = "Now, it be time for ya ta leave. \n\nDere be many of dem blood troll souls for ya ta be sendin' to da Other Side for Bwonsamdi, and ya not gonna find any more of dem here.", objectives = "Travel to Zo'bal Ruins and speak with Hanzabu.", completion = "So, you formed a pact with Bwonsamdi, too? Good, de more souls for Bwonsamdi, de stronger he is, and dat works out better for de both of us. Just leave some hunting for Hanzabu. I have my own pact to pay for!" }
WordHunterWoW_QuestEN[47251] = { title = "Interesting Times", description = "{name}, I don't mean to alarm you, but we may be experiencing some... temporal disturbances.\n\nHave you ever heard the phrase 'I hope the past doesn't come back to haunt you?'\n\nCome visit me in the Valley of Spirits and we can speak more.", objectives = "Meet with Historian Ju'Pa in the Valley of Spirits of Orgrimmar.", completion = "<name>, you're here. You must have received my letter." }
WordHunterWoW_QuestEN[47252] = { title = "Interesting Times", description = "{name}, I don't mean to alarm you, but we may be experiencing some... temporal disturbances.\n\nHave you ever heard the phrase 'I hope the past doesn't come back to haunt you?'\n\nCome visit me in the Stormwind Royal Library and we can speak more.", objectives = "Meet with Historian Llore in the Royal Library of Stormwind.", completion = "<name>, you're here. You must have received my letter." }
WordHunterWoW_QuestEN[47253] = { title = "The Originals", description = "Long ago, great terrors walked our lands, and drove even the smallest to flights of heroism.\n\nI speak, of course, about Lord Kazzak, Azuregos, and the Dragons of Nightmare.\n\nLegends have it that so sought after were their treasures, that armies would camp overnight to hunt them down.\n\nWe have felt disturbances in the timeways, coincidentally located where these giants once roamed. \n\nWould you mind investigating for us? Strange things happen during this time of year.", objectives = "Defeat Lord Kazzak in Blasted Lands, Azuregos in Azshara, and the Dragon of Nightmare at one of the portals to the Emerald Dream.", progress = "They're just memories, right?", completion = "Let us use this moment to reflect upon the past, lest we forget the lessons it teaches us, and doom ourselves to repeat it once more." }
WordHunterWoW_QuestEN[47254] = { title = "The Originals", description = "Long ago, great terrors walked our lands, and drove even the smallest to flights of heroism.\n\nI speak, of course, about Lord Kazzak, Azuregos, and the Dragons of Nightmare.\n\nLegends have it that so sought after were their treasures, that armies would camp overnight to hunt them down.\n\nThe dragons have felt disturbances in the timeways, coincidentally located where these giants once roamed. \n\nThey have tasked me with finding champions to investigate.", objectives = "Defeat Lord Kazzak in Blasted Lands, Azuregos in Azshara, and the Dragon of Nightmare at one of the portals to the Emerald Dream.", progress = "They're just memories, right?", completion = "Let us use this moment to reflect upon the past, lest we forget the lessons it teaches us, and doom ourselves to repeat it once more." }
WordHunterWoW_QuestEN[47255] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47256] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47257] = { title = "The Bones of Xibala", description = "Far to the south you will find the bones of an ancient creature. This is Xibala, the progenitor, first of the devilsaurs. She was mother to Rezan, mother to all that came after. The Zandalari do not live there, as it belongs to beasts now.\n\nI have heard rumors of some of your Horde arriving in search of something among her bones.\n\nThis is ill advised. Look into it, won't you?", objectives = "Travel to Xibala and speak with Examiner Tae'shara Bloodwatcher.", completion = "I've waited for such a find all my life. I will make my father proud." }
WordHunterWoW_QuestEN[47258] = { title = "Prepare for a Siege", description = "It would seem we must make ready for a siege. For now, return to your Horde in Dazar'alor. Prepare for de coming conflict.\n\nShould de forces of Nazmir surge, I will send word.", objectives = "Speak with Baine Bloodhoof.", completion = "Though our warchief may balk at further delays, I believe we are honor-bound to assist the Zandalari. \n\nThis is about more than gaining an ally in wartime. The Horde was founded on the idea of aiding those facing their hour of need.\n\nJust as Thrall once came to the defense of my people, so we must help save Zandalar." }
WordHunterWoW_QuestEN[47259] = { title = "Direhorn Daycare", description = "Handler Bazkoji had a real gift with de little ones. If dis hatchling is following you, it must mean Bazkoji is dead.\n\nI don't have time to find another handler. Are you up to de task?\n\nIt's a lot of work, and de little ones get attached real fast. If you're going to care for it, it will be a commitment. That baby will be depending on you. I hope you will be up to de task of feeding and protecting it.\n\nFirst things first: food. Dere is plenty of fodder in de pens and river below.", objectives = "Feed your hatchling.", completion = "Not bad. Dat baby is looking stronger already." }
WordHunterWoW_QuestEN[47260] = { title = "Side Effects May Include...", description = "<Your direhorn companion hiccoughs repeatedly. Each time, it either shrinks or grows by a perceptible amount. It whines at you in distress. \n\nYou could use some help.>", objectives = "Speak to Beastlord L'kala in Warbeast Kraal.", completion = "I knew it was a bad idea to trust this small green mon." }
WordHunterWoW_QuestEN[47261] = { title = "How to Train Your Direhorn", description = "I have to get some of whatever you fed your baby! Wow!\n\nNow dat it's bigger, it is time to teach it to be a reliable battle companion.\n\nLet's see how it does against a tougher challenge, hmm?\n\nTalk to Kraal Master B'khor when you are ready to begin.", objectives = "Talk to Kraal Master B'khor and choose to train your direhorn.", progress = "How did de training go?", completion = "Whoops. At least dat was quite entertaining to watch! Ha ha ha!\n\nI guess you two have earned your places here for sure!" }
WordHunterWoW_QuestEN[47262] = { title = "Ending the Blood Trolls", description = "De loa are smiling on us today. De \"matriarch\" of dese blood trolls, a sick monster named Ateena, is up ahead.\n\nWe have a change in plans, {name}. We will end dis threat now. We kill Ateena and de blood trolls will be thrown into chaos.\n\nShe is a powerful hexxer. Go start de fight and I will ambush and catch her off guard.\n\nLet us get moving. We will be back in Zuldazar before de day is over.", objectives = "Kill Ateena, the Matriarch of the blood trolls.", completion = "Ateena will not get away from us, we have to keep moving." }
WordHunterWoW_QuestEN[47263] = { title = "A Time of Revelation", description = "I can feel Ateena's dark voodoo up ahead. We need to stop whatever she is planning with dis \"G'huun\".\n\nBe ready for anything, {name}. We do not know what power Ateena truly has.\n\nI do know one thing. If G'huun is threatening my people, den it will die, just like Ateena.", objectives = "Help Talanji chase down Ateena.", completion = "De blood troll threat is bigger than I ever imagined. Dat construct is enough to destroy all of Zuldazar\n\nWe need more than de Horde to stop dis." }
WordHunterWoW_QuestEN[47264] = { title = "Leave None Standing", description = "Now you see what my father refuses to acknowledge. De blood trolls are slaughtering us, and dey need to be stopped.\n\nOur plan is simple, {name}. We will go out dere and kill as many of dese blood trolls as we can. You go east, I go north.\n\nMeet with me after and we will see what is left to do. We will teach dese blood trolls to fear de Zandalari!", objectives = "Slay 6 blood trolls.", completion = "Are you finished? Good, because we are close to ending dis menace." }
WordHunterWoW_QuestEN[47272] = { title = "Direhorn Growth Hormone", description = "Nice little critter you got there. Seems a tad too small to be much more than a nuisance though. \n\nWanna help a friend make a profit? There's an abundance of opportunity here, but these trolls won't listen to me!\n\nTell you what, I can make a supplement of sorts that'll make hair grow on your chest! Er, your hatchling's chest! \n\nI know direhorn are vegetarians and all, but there's a reason all the biggest predators eat meat!\n\nRapid growth requires protein. LOTS of protein.\n\nYou interested?", objectives = "Collect 10 Steaming Fresh Carrion.", progress = "So? Did you get everything I need?", completion = "Meat is pretty miraculous stuff, you know!\n\nEr, you might want to keep the details about this to yourself for the time being." }
WordHunterWoW_QuestEN[47282] = { title = "First Aid Shop Searched", description = "", objectives = "" }
WordHunterWoW_QuestEN[47283] = { title = "Chop, Chop!", description = "Throm-ka, {name}.\n\nI'm always looking for someone who thinks they can swing an axe with the best of them.\n\nIf you can remove that sapling without much trouble, I'm sure we can find a better use for your skills.", objectives = "Pick up a Sturdy Axe, then gather 5 Freshly-Chopped Wood from the nearby Sapling.", progress = "Hmm?", completion = "Just the kind of strength we need around here." }
WordHunterWoW_QuestEN[47287] = { title = "The Vindicaar Matrix Core", description = "Much has happened on Argus that concerns me but none moreso than Xe'ra's fate. I wonder sometimes if we are doing the right thing? \n\nBut we must carry on. I can rig the Matrix Core that powers the Vindicaar to allow you to call on the power of our guns when you have need of them on the planet. \n\nGo to the Matrix Core in the room at the heart of our ship. Once linked, whatever powers the core has installed now and in the future will be at your disposal.", objectives = "Link Light's Judgment into the Vindicaar Matrix Core.", progress = "Have you linked Light's Judgment into the Vindicaar Matrix Core?", completion = "Light's Judgment will now fire on your command when you use the Matrix Uplink. \n\nPerhaps you will find more objects that we can link into the Matrix on your travels. I have routed enough energy to that part of the Core to handle anything that you can link into it. \n\nGo well, my friend." }
WordHunterWoW_QuestEN[47288] = { title = "Valuable Fossils", description = "", objectives = "" }
WordHunterWoW_QuestEN[47289] = { title = "Teddies and Tea", description = "There's nobody to play with here anymore. But you'll play with me, right mister?\n\nIt's time for tea! Help me find the other guests, please!", objectives = "Gather Mr. Munchykins, Trunksy, and Mayor Striggs for the tea party.", progress = "This is going to be the best tea party ever!", completion = "Hooray! Only one more guest left to find." }
WordHunterWoW_QuestEN[47290] = { title = "World Event Dungeon - Hummel", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[47310] = { title = "Naptime", description = "Your not-so-little guy is looking a bit ragged after such an exciting day. I bet you both need a rest, hm?\n\nCome back later when you're a bit stronger.", objectives = "Stable your direhorn in the Beast Pen.", progress = "I bet you and your direhorn need a bit of rest, hm?", completion = "I will look after your little one for de time being. Go on your adventures. Learn de ways of de Zandalari. When you are both ready, I will have an offer for you." }
WordHunterWoW_QuestEN[47311] = { title = "Headbutting 101", description = "Your beast is looking well fed. Good. Try and keep it dat way.\n\nNow, next you need to teach your little one to defend itself. Direhorns in de wild are prey for much larger creatures and de young are easy pickings for saurid and their like.\n\nGo out into de Savagelands and show your little one how to fend dem off.\n\nIt's all in de horn, {name}.", objectives = "Assist your hatchling in fighting 12 creatures.", completion = "I see a gleam of confidence in your hatchling's eyes. Good. It will need it." }
WordHunterWoW_QuestEN[47312] = { title = "Queenfeather", description = "Ah, so you are de one who inherited Bazkoji's herd. What is left of it, anyway.\n\nI know what killed him, and I tried to warn him. Queenfeather is a vicious ravasaur, bigger than de rest and smarter as well. Most of de eggs around here are hers.\n\nUsually I praise de strength of such a beast, but she has become a nuisance.\n\nYou will find her guarding her nests in de feeding grounds. Kill her and bring back one of her head feathers as proof dat de deed is done.", objectives = "Slay Queenfeather and claim one of her feathers.", progress = "Does Queenfeather still stalk us?", completion = "Good. Now dat de bloodthirsty matriarch is gone, maybe we can plant one of ours back into de brood as a replacement... Hmmm." }
WordHunterWoW_QuestEN[47313] = { title = "Discreet Discussions", description = "General Jakra'zet cannot be trusted. \n\nHe is up to something, but I do not know what.\n\nAny who question his actions earn demselves a trip to de sands. \n\nAs long as he remains in power, my city will never be safe.\n\nSpeak to his guards. See what you can find out, but be discreet. We do not want to alert Jakra'zet to our actions.", objectives = "Question Enforcers within Dazar'alor.", progress = "It is not safe to ask questions about de general around here.", completion = "You are going to make more enemies than allies asking questions like dat around here." }
WordHunterWoW_QuestEN[47314] = { title = "Rumors of Exile", description = "Talanji sent you, didn't she? \n\nDe princess needs to know dat it is no longer safe to ask such questions so openly. \n\nWarguard Rakera spoke out, and no one has heard from her since. \n\nRumor has it she was exiled to Vol'dun.", objectives = "Follow Bladeguard Kaja.", completion = "We will not let Rakera and whatever she knows be lost to de sands." }
WordHunterWoW_QuestEN[47315] = { title = "Into the Dunes", description = "Whatever Rakera uncovered, it was important enough to earn her a death sentence to de sands. \n\nWe must head into Vol'dun to find her. \n\nWe cannot let whatever she knows about Jakra'zet die with her in de dunes.", objectives = "Fly into the deserts of Vol'dun and search for Warguard Rakera.", completion = "These snakemen will pay for what they've done to my home." }
WordHunterWoW_QuestEN[47316] = { title = "Secrets in the Sand", description = "I found this journal buried in the sand. \n\nKiro tried to toss it in the fire.\n\n\"Our wagon has no space for a diary, Meerah. What practical use does it have?\"\n\nDon't tell him I said so, but I think it's fascinating! Can you imagine what kinds of secrets it holds? \n\nQuite a few pages are missing, but I bet you can recover them out on the dunes!", objectives = "Recover the journal's missing pages.", progress = "What have you found?", completion = "Dis is Rakera's handwriting. I'd know it anywhere." }
WordHunterWoW_QuestEN[47317] = { title = "Searching for Survivors", description = "It is good to see you are safe, but what of de others? Have dey been lost to de sands?\n\nYou need to head back to de crash site and see if de others survived.\n\nI will ask around and see if these fox people can tell us anything about Rakera.", objectives = "Search for survivors near the crash site.", completion = "Jorana knew de risks when she agreed to enter de sands, but I still can't help but feel responsible for her death.\n\nI can only hope dat Tarkaj somehow made his way to safety." }
WordHunterWoW_QuestEN[47319] = { title = "Restorative Venom", description = "Meerah here found your friend in the dunes. The lightning strike nearly killed her. It might still, without treatment. \n\nThe wasps within the grove have a painful sting, but their venom also has restorative properties. \n\nI can extract what I need from their glands.\n\nWith an ample amount of venom, we should be able to soothe your friend's wounds.", objectives = "Collect 15 Sandstinger Venom Glands.", progress = "Have you brought the glands? We can't heal your friend without them.", completion = "<Kiro quickly inspects the glands.>\n\nThese should work well." }
WordHunterWoW_QuestEN[47320] = { title = "A Balm to Calm", description = "As promised, here is the balm that should remedy your companion's injuries. \n\nApply it liberally to any bits of exposed flesh.\n\nIts effects should be felt immediately.", objectives = "Use the Restorative Balm on Bladeguard Kaja.", completion = "Did these creatures come to our aid?\n\nDe last thing I remember, we were flying over de sethrak empire. There was a blinding flash of light before things went dark..." }
WordHunterWoW_QuestEN[47321] = { title = "Knickknack Takeback", description = "Nisha told me you came here in search of an exile. One named Rakera? \n\nWe don't know her, but we might be able to help you find her. \n\nYou help us, and we help you. Deal?\n\nWe survive by scavenging. We trade what we find, but the sethrak that raided our burrows made away with many of our knickknacks.    \n\nI always knew they were ruthless, but never imagined they'd be so greedy.\n\nTake back what the sethrak have taken, and I'll see that you are provided safe passage through the dunes.", objectives = "Collect 6 Knickknacks from sethrak within The Serpent's Maw.", progress = "You help us, and we help you. Deal?", completion = "You're more resourceful than you look." }
WordHunterWoW_QuestEN[47322] = { title = "Aided Escape", description = "The sethrak may be strong, but we're quick. Well, at least Mekaru and I are.\n\nWe just barely made it back to the wagon with our tails attached. \n\nThe others weren't so lucky, I guess. We've been waiting a while, and still no sign of them. \n\nIf you're headed into the thick of it, would you mind looking for our friends?", objectives = "Free Hakasi and Kipp from within The Serpent's Maw.", progress = "We abandoned our scavenging as soon as the sethrak showed up. Not all of us made it to safety...", completion = "Thanks, <name>. We owe you our lives." }
WordHunterWoW_QuestEN[47324] = { title = "Unlikely Allies", description = "I believe this is one of the Keepers' keys! Only Vorrik would know for sure. \n\nWe need to head to the temple at once. \n\nMy pterrordax can take us there when you're ready, but we need to hurry.", objectives = "Fly to the Sanctuary of the Devoted.", completion = "We cannot let the Faithless take this temple!" }
WordHunterWoW_QuestEN[47327] = { title = "Answering Their Attacks", description = "The sethrak's attacks on our burrows cannot go unanswered. \n\nThey need to learn that not all within the desert will give up so easily. \n\nThe only thing the sethrak understand is blood, so that's the language we'll use to teach them.\n\n<Nisha pauses and looks at you, skeptical that you understood her.>\n\nI'm saying we need to kill the sethrak here. All of them.", objectives = "Kill sethrak in the Abandoned Burrows.", progress = "The sethrak will answer for what they have done.", completion = "Their blood flows down the dunes back to their fortress. The sethrak will think twice before attacking our burrows again." }
WordHunterWoW_QuestEN[47329] = { title = "The Bloodwatcher Legacy", description = "Greetings, {name}.\n\nI have been sent on behalf of my father, High Examiner Tae'thelan Bloodwatcher, to oversee the extraction of all fossils, relics, and artifacts from this area.\n\nMy sources inform me that an object that could advance the Horde's cause may be buried beneath this very site.\n\nI will require your help extracting it. You see, these nightborne are not precisely good with their hands. Nor do they enjoy getting dirty.\n\nCould you be a dear and set a good example?", objectives = "Help Examiner Tae'shara Bloodwatcher recover a Xibalan fossil.", progress = "By all means, let us assist young Tae'shara. Such enthusiasm is to be rewarded.", completion = "You used your hands! How quaint. The nightborne have devised a number of ways to avoid such petty labors." }
WordHunterWoW_QuestEN[47330] = { title = "Whispers of a Frightened World", description = "Champion, Magni needs your help!\n\nThe Speaker has a message for you, perhaps from Azeroth herself. He seems to be having trouble understanding her, but I'm sure he can explain everything better.\n\nHe said he was in Sholazar Basin, in Northrend. He should be contacting you shortly.", objectives = "Meet Magni in Sholazar Basin and hear the warning.", progress = "Yes, <name>? What news do you bring?", completion = "This warning is an ill omen indeed, <name>. It seems the fate of Azeroth is tied to that of Argus, the homeworld of the Legion.\n\nWe must uncover the Dark Titan's plan! I believe the Speaker's connection to the world soul will prove crucial to our efforts.\n\nStay vigilant, Huntmaster. We must trust in Magni's guidance... and Azeroth's as well." }
WordHunterWoW_QuestEN[47331] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47332] = { title = "Your Next Move", description = "Princess Talanji plans to travel north to Nazmir. The blood trolls there are a threat she believes her father refuses to acknowledge.\n\nGeneral Jakra'zet detests the Horde and cannot be trusted. As long as he remains in power, the city will never be safe.\n\nYou will also need to win over King Rastakhan here in Zuldazar. This city is vast and has many secrets.", objectives = "Choose your next move in Zandalar.Princess Talanji plans to travel north to Nazmir. The blood trolls there are a threat she believes her father refuses to acknowledge.\n\nGeneral Jakra'zet detests the Horde and cannot be trusted. As long as he remains in power, the city will never be safe.\n\nYou will also need to win over King Rastakhan here in Zuldazar. This city is vast and has many secrets." }
