WordHunterWoW_QuestEN[47416] = { title = "Shadow of the Triumvirate", description = "Talgath's words carry more gravity than I think he knew. In an attempt to hurt me one final time, he has given us the answer.\n\nThe Crest of Knowledge is hidden away in the Seat of the Triumvirate, and it is not unguarded.\n\nIf my suspicions are correct, we may be facing a greater threat than any of us dared imagine.\n\nA dark naaru.\n\nLet us return to the Vindicaar. We will plan our next steps there.", objectives = "Return to the Vindicaar.", completion = "I worried for L'ura, but this is... unthinkable.\n\nHow she must have suffered..." }
WordHunterWoW_QuestEN[47418] = { title = "Growing Pains", description = "These trolls are missing a real opportunity here! They complain about not having enough beasts to go around, yet have they really tried to mass produce them? Nope!\n\nWith my Direhorn Growth Hormone, they'll be able to fill these pens to overflowing! Sure, the overcrowding might lead to disease and excess waste issues, but I'm sure those are solvable.\n\nHa ha ha this is gonna be great!", objectives = "Feed the Direhorn Growth Hormone to your hatchling.", progress = "Well? Did your hatchling try the DGH yet?", completion = "Wow! That worked even better than I thought! I'm gonna make a fortune!" }
WordHunterWoW_QuestEN[47422] = { title = "Dire Situation", description = "Good news, we found de source of de corruption.\n\nDe bad news, it is a ritual on de apex of Zanchul.\n\nBlood magic wielding heretics are empowering some sort of dire troll up dere.\n\nHow it made it all de way to de apex without us catching it is something I am sure Raal and I will be arguing about for de next year.\n\nCome, let us stop dis heresy.", objectives = "Slay Dregada.", progress = "What wisdom did de loa priests give you?", completion = "I will not have dat blood in my temple!" }
WordHunterWoW_QuestEN[47423] = { title = "Forbidden Practices", description = "You come at a good time, {name}. I have need of a weapon such as yourself.\n\nYazma's spies say dere are blood cultists in our ranks. King Rastakhan has charged me with tracking down any trolls guilty of practicing blood magic and purging dem.\n\nTake dis totem, route out those with de stench of blood magic, and cleanse dem from dis holy place.\n\nWhen you are done, tell dat lazy Hexlord Raal to get off his perch and help keep dis place secure.", objectives = "Find and slay 9 Crimson Cultists in the Terrace of the Chosen.", progress = "Hello dere.", completion = "What? Dat sneering, vile raptor zealot is calling me out for not doing my share? Bah!" }
WordHunterWoW_QuestEN[47424] = { title = "FLAG - First Chromie Saved", description = "", objectives = "" }
WordHunterWoW_QuestEN[47428] = { title = "Kitty?", description = "You have to find our last guest before it's time for tea!\n\nSmoochums really likes the woods, I bet we'll find him there!", objectives = "Find Smoochums in Glenbrook Woods.", completion = "Mrrow?\n\n<You find Smoochums, but Abby is nowhere to be seen.>" }
WordHunterWoW_QuestEN[47430] = { title = "Moonkin Monitoring", description = "<Makkaw motions for you to observe the other moonkin in the area.>", objectives = "Observe the nearby dancing, moonfiring, and napping Moonkin Hatchlings and see what you can learn.", completion = "<Makkaw seems very pleased about what you have learned.>" }
WordHunterWoW_QuestEN[47431] = { title = "Gathering Light", description = "Alleria and I long for more time with our son, but we cannot afford to wait any longer, {name}. We must strike now.\n\nThe Army of the Light is scattered, but not defeated. Any survivors should have stayed near the crash site of the Xenedar. If there is any hope of victory, we must rally them and rescue Xe'ra.\n\nWith the pit lords dealt with, we should have a safer route to the Xenedar. Meet me in the krokul hovel as soon as you can.", objectives = "Meet Turalyon in the Krokul Hovel.", completion = "We've secured a foothold. Good.\n\nNow we take the fight to them!" }
WordHunterWoW_QuestEN[47432] = { title = "The Bargain is Struck", description = "Now dat you have declared a patron loa for your time here in Zuldazar, you should inform de king of your decision.\n\nHe will appreciate dat you chose to follow de great Pa'ku.", objectives = "Speak with King Rastakhan.", completion = "So, you have chosen de path of Pa'ku. May de winds of war be ever in your favor.\n\nFor myself, I follow Rezan, de devilsaur loa of kings. He and I have not spoken for many years, though.\n\nPerhaps I shall pay him a visit one of dese days." }
WordHunterWoW_QuestEN[47433] = { title = "Offensively Defensive", description = "Let me guess, Loti had you kill any trolls dat smelled of blood magic, yes? Well, dat is barely a half measure.\n\nSee, blood magic comes from de old ways, and our people have only been giving in to its allure since de walls fell on our northern border.\n\nCome, we will go for a little ride and patrol de border to Nazmir. Dat is where all dese bad ideas are coming from.", objectives = "Patrol the skies with Hexlord Raal.", progress = "Winds be our ally.", completion = "Oh, so dat bent-tusk nose-breather is trying to win you over with a little flight and some charm, eh?" }
WordHunterWoW_QuestEN[47434] = { title = "Restraining Order", description = "\"Something feels different\"? Dat was all Raal said?\n\nHis flock of pterrordaxes have swarmed de courtyard of Zanchul. Dey are being driven mad.\n\nShoo dem away before dey hurt demselves or others.", objectives = "Shoo away 20 Pterrordax Hatchlings.", completion = "Why are you scaring away my flock?" }
WordHunterWoW_QuestEN[47435] = { title = "Pterrortorial Dispute", description = "De courtyard of Zanchul has been overrun by pterrordaxes driven mad by some dark ritual. Power is coalescing here, and it is hard to tell who or what is causing it.\n\nI need to track down de source. In de meantime, you take dis, de power of Gonk, and call his allies to help you in battle. Slay dese maddened pterrordaxes.\n\nWhen you are done, tell Raal to get his flock under control.", objectives = "Slay 6 Bloodraged Pterrordaxes.", completion = "Did you have to kill so many?" }
WordHunterWoW_QuestEN[47437] = { title = "Competitive Devotion", description = "Okay, I know dis situation is serious, but she gave you de power of her loa? Sounds to me like Loti is more big on recruiting than on dealing with dis blood troll threat.\n\nInside de temple behind me are three guardians. When I walked in dere, de things tried to kill me. Me!\n\nSomeone has corrupted our own guardians.\n\nHere, I will lend you de voice of my own loa, Pa'ku, de pterrordax. Use it to crush dis corruption.", objectives = "Slay the 3 Corrupted Guardians of Zanchul.", completion = "Dis is worse than we thought." }
WordHunterWoW_QuestEN[47438] = { title = "Picking a Side", description = "Look, dis has gone on long enough, {name}. I am not one to hold a grudge, but I will be damned if I let you double dip with Raal's loa and my own.\n\nTime has come to pick a loa. De loa are not de sharing type.", objectives = "Choose a loa.", progress = "Have you made a choice?", completion = "Your choice is made." }
WordHunterWoW_QuestEN[47439] = { title = "Gonk, Lord of the Pack", description = "You can find Gonk in his lair west of here, in de Garden of the Loa.\n\nYou should be able to see his totems. Run near dem to improve your speed.\n\nI will continue to purge de heretics from dis temple.\n\nMind your manners around de loa, or he may rip your throat out.", objectives = "Bargain with Gonk.", progress = "What did he say to you?", completion = "Oh, good. He did not rip your throat out. Dat is a good sign. Come, let us show de public your choice." }
WordHunterWoW_QuestEN[47440] = { title = "Pa'ku, Master of Winds", description = "Come, ride Ata de Winglord with me, and he will take us to Pa'ku.\n\nOh, and mind your manners around dat loa. Pa'ku has been known to drop followers she is not fond of from a really great height onto really hard stone.", objectives = "Bargain with Pa'ku.", progress = "What did she say to you?", completion = "Oh, good. She did not have you dropped. Dat is a good sign. Come, let us show de public your choice." }
WordHunterWoW_QuestEN[47441] = { title = "Pests", description = "Let me guess, de saurid stole something of yours as well, eh? Look, I don't have de time to run down every little thing dese ankle-biters snap off with.\n\nYou want some coin? Help me kill some of dese snappers.\n\nOtherwise, leave me be.", objectives = "Slay 8 Thieving Snappers in the Zocalo.", completion = "A thief has come to steal from thieves?" }
WordHunterWoW_QuestEN[47442] = { title = "Curse of Jani", description = "Thief and killer, know dat ya be standin' before da Patron of Scavengers, da Lord of Thieves, da God of Garbage, Master of Minions, and da Keeper of Secrets.\n\nYa be standin' before me in raiment worth entire kingdoms of gold, bearin' weapons dat cost more than even me most devout and renowned followers will ever earn.\n\nI tink now be a good time ta teach ya a lesson. Maybe show ya high and mighty greatness what it means ta be snappin' in da gutters.", objectives = "Survive the Trial of Jani.", progress = "You be bitin' that ratmon yet?", completion = "Haha! Well done, wealthy stranger. When ya out and about in dese lands, keep ya eyes open. Ya never know when one of de children might be pointin' ya ta a useful place." }
WordHunterWoW_QuestEN[47444] = { title = "Vindictive Combatant's Leather Armor", description = "", objectives = "" }
WordHunterWoW_QuestEN[47445] = { title = "The Zanchuli Council", description = "You there, Speaker of de Horde.\n\nMy spies have told me of dark heresies being practiced in our sacred temple of Zanchul.\n\nDe king sent Loti and Raal to deal with de situation, but those two bickering council members are soft on their own followers.\n\nWe need someone more... ruthlessly neutral.\n\nGo meet Wardruid Loti down at de Zocalo and she can tell you de rest.", objectives = "Speak with Wardruid Loti in the Zocalo.", completion = "Welcome to de steps of Zanchul, <name>. You will be treading on sacred ground soon." }
WordHunterWoW_QuestEN[47446] = { title = "Vindictive Combatant's Leather Armor", description = "", objectives = "" }
WordHunterWoW_QuestEN[47456] = { title = "Calming the Void", description = "", objectives = "" }
WordHunterWoW_QuestEN[47460] = { title = "Interact - Doodad & Creature Test [DO NOT LOCALIZE]", description = "Please complete this quest in order to testing the Interact - Doodad & Interact - Creature quest objective types.You will learn:", objectives = "Interact 3 Wards and speak with Wardkeeper Malo." }
WordHunterWoW_QuestEN[47461] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47462] = { title = "Tracking Quest", description = "", objectives = "" }
