WordHunterWoW_QuestEN[47464] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47465] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47466] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47473] = { title = "Sizing Up The Opposition", description = "Turalyon was no doubt hoping for better news, but I fear I cannot provide it. Attempting to drive into the heart of the Legion now would cost us everything.\n\nThere must be another way. I do not know what it is, but I trust that we will find it.\n\nBest not keep Turalyon waiting. We must move forward.", objectives = "Speak with Turalyon.", completion = "<Turalyon listens in grim silence.>" }
WordHunterWoW_QuestEN[47485] = { title = "The Ashvane Trading Company", description = "So, Ashvane's goons are walking around with a new powder that can blow a galleon clean in half and the military has no idea.\n\nWe need to find out how much of this powder they have and where it's going.\n\nAn old buddy of mine works the ferry down by the Ashvane Foundry. He may know something about this.\n\nYou can take the ferry from Tradewinds Market to Eastpoint Station. Once you get there, look for a man named Cagney. Tell him I sent you. He owes me a favor.", objectives = "Speak with Cagney at Eastpoint Station. Take the ferry from Will Melborne in Tradewinds Market.", completion = "Eh? What do you want?" }
WordHunterWoW_QuestEN[47486] = { title = "Suspicious Shipments", description = "Normally I wouldn't tell you nothin'... but I'll spill it for Cyrus.\n\nAshvane's onto somethin' big.\n\nThey got guys workin' round the clock in there. Even brought in some muscle to keep everyone uh... \"motivated.\"\n\nI don't know anything about what they're makin', but I know it ain't passin' through here to Boralus.\n\nIf I were dumb enough to go snooping around in there, I'd look at the goods themselves. See if they got shipping labels.\n\nBut I ain't that dumb, so you gotta do it.", objectives = "Inspect 5 Marked Goods in the Ashvane Foundry.", completion = "Sounds like they're making a ton of this stuff and keeping it under wraps.\n\nThat's bad." }
WordHunterWoW_QuestEN[47487] = { title = "Labor Dispute", description = "The Ashvane Company has been workin' their people so hard they even tried to strike! \n\nThe company brought in a bunch of goons to break it up and get everyone back to work. \n\nHeard they even shot a couple guys who tried to walk off the job.\n\nWhat say you give 'em a taste of their own brutality while you're in there?", objectives = "Slay 10 Company Watchmen, Company Enforcers, or Company Fusiliers.", completion = "Nobody likes livin' under the thumb of company men like that - they ain't gonna be missed." }
WordHunterWoW_QuestEN[47488] = { title = "Small Haulers", description = "<sniff>\n\nThey said they would feed us. Said they'd keep us warm.\n\n<Olive runs the sleeve of her coat across her nose.>\n\nBut they were mean! And it was really hard work. And when we tried to rest, they yelled at us!\n\n<sniff>\n\nI got away, but my friends are still in there.", objectives = "Free 6 Urchin Workers from the Ashvane Foundry.", completion = "These kids are gonna have it hard enough without being under Ashvane's thumb. Thanks for getting them out." }
WordHunterWoW_QuestEN[47489] = { title = "Stow and Go", description = "<Flynn lifts his collar to hide his face and speaks to you under his breath.>\n\nYou see that ship? I know that ship.\n\nLet's just say her captain and I have a little history.\n\nIt's a smuggling vessel. Our illegal weapons are on there for sure. I'd bet my coat on it... and I love this coat.\n\nWe need to find out where it's going...\n\nHow are you in tight spaces?", objectives = "Stow away on The Maiden's Virtue.", completion = "You alright, mate? I'm afraid your ship's gone.\n\nSomethin' tells me you weren't really a part o' that crew anyway, were ya? Har har!" }
WordHunterWoW_QuestEN[47491] = { title = "Remnants of the Damned", description = "Ever since da spirits have begun calling upon dis \"G'huun,\" me temple has been covered with da unbearable taint of da undead. \n\nDa undead be an abomination, but da bloodstones dat create dem be powerful. Dey could be of use ta Bwonsamdi.\n\nIf ya wish ta show me ya fervor, den cleanse me temple of their filth and bring me their bloodstones.", objectives = "Collect 6 Decaying Bloodstones for Bwonsamdi.", progress = "Ya got dem bloodstones for me?", completion = "Mmm, dese will do nicely." }
WordHunterWoW_QuestEN[47493] = { title = "A Lonely Spirit", description = "Da spirit of a child named Keula be wanderin' me temple grounds. Her ma'da gave her child up ta me long ago, she be thinkin' that a great sacrifice would spare her from me call, from going to da other side.\n\nWell she be right, I not claim her yet. But she be wrong too. Her child be da one to decide when ta be reunited with her ma'da, and it seem ta me dat da child be no longer be content ta wait.\n\nDey both belong in my realm.\n\nGo, bring da child to her ma'da.", objectives = "Seek out Keula within the Necropolis.", completion = "Who be you? Have ya seen ma'da?" }
WordHunterWoW_QuestEN[47495] = { title = "Insatiable Appetite [UNUSED]", description = "That was incredible! I've never seen such rapid growth! \n\nYour strange friend here be welcome to stay as long as he likes if he be willing to share his secret with the Kraal.\n \nAs for you and your beast, he be looking awfully hungry again. I suspect you'll find it will take a lot more food to satisy him now.\n\nGood luck, Apprentice!\n\n[NYI - will be a lengthy progress bar though - preferably filled while doing Nessingwary quests!]You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Feed your direhorn." }
WordHunterWoW_QuestEN[47496] = { title = "Bunker Buster", description = "", objectives = "" }
WordHunterWoW_QuestEN[47497] = { title = "Meet the Goldtusk Gang", description = "Greetings, traveler, and welcome to de Goldtusk Inn!\n\nUnless you're here to kill us... In which case, get out.\n\nOtherwise, sit down and enjoy de mess!\n\nI mean, don't mind de mess. EAT DE MESS! No, don't eat de mess. Ignore it!\n\n<Rhan'ka turns to the skull with the eyepatch and shouts furiously in Zandalari.>\n\nHa, don't mind him. All exiles are welcome to rest at de Goldtusk Inn, de only luxury lodge in dese harsh dunes.\n\nCome, let me introduce you to de staff.", objectives = "Meet the staff of the Goldtusk Inn.", progress = "My friends are waiting... Don't be rude.", completion = "Don't mind half of what those trolls say. Dey don't really mean it." }
WordHunterWoW_QuestEN[47498] = { title = "Rhan'ka's Lost Friend", description = "When you head up to Dead Man's Pass, be sure to say hello to Zulsan.\n\nHe's my best friend, even if he doesn't want to be near me most of de time. Ha!\n\nSeriously, though, he's been up on de cliffs for days. If you find him, convince him to come back down to de inn. We need him to restock our breakfast buffet.\n\nOh, and a completely unrelated question dat has nothing to do with you not being able to find Zulsan and my needing to replace him: How wide is ya head?", objectives = "Find Zulsan in Dead Man's Pass.", progress = "Did you find Zulsan yet?", completion = "Thank de spirits you found Zulsan. Sandfury trolls kidnapped de rest of de gang!" }
WordHunterWoW_QuestEN[47499] = { title = "The Grinning Idols", description = "Before de curse, we were a loyal crew to a good captain. But de curse corrupted Pirate-King Zem'lan, made him cruel and controlling.\n\nNow, he treats us more like slaves than crewmates. Forced to fight and die for his gain, no treasure for ourselves. No speakin' up without punishment.\n\nWell, us four, we ain't gonna be his slaves no more.\n\nA few of de crew hold onto de idols dat Zem'lan used to curse us. Kill dem and take de idols. I wanna see if we can break dem. Just for fun.", objectives = "Collect the Idol of Binding, Idol of Immortality, and Idol of Sacrifice.", progress = "I'd hoped I'd never have to see those idols again.", completion = "Dese be cursed and evil things." }
WordHunterWoW_QuestEN[47501] = { title = "Dirty Work for Dirty Drinks", description = "Guests gotta earn their keep at de Goldtusk Inn. What say you help me clear out some scorpids at one of our off-site excursion locations? De delightful Dead Man's Pass!\n\nNormally, you'd need to purchase our Warlord Package to be allowed access, but I'll make an exception dis time.\n\nI'll even throw in our Scorpid King Package. Unlimited scorpid blood drinks all day, every day!\n\nDere's one catch: we're out of scorpid blood. Bring some back and I'll whip up a batch of drinks for us.", objectives = "Collect 20 Caustic Scorpid Blood from deathsnap scorpids in Dead Man's Pass.", progress = "My scorpid blood drinks are famous in de Goldtusk Gang!", completion = "I'll hold onto dis blood until we can get back to de inn to make de drinks.\n\nDon't worry, I won't let you miss out on dem. I know you're excited to try my famous scorpid blood drinks!" }
WordHunterWoW_QuestEN[47502] = { title = "The Great Cranium Caper", description = "Sandfury thugs attacked de inn after you left and kidnapped de whole Goldtusk Gang!\n\nWe gotta get dem back.\n\nMan'zul was usually de brains behind our thefts back in Zuldazar, but I'll try to come up with a plan to get dem outta dis mess.\n\n<Rhan'ka thinks for awhile.>\n\nI got it! You rescue 'em all!", objectives = "Rescue the kidnapped members of the Goldtusk Gang in the Sandfury Hideout.", progress = "We nothin' without our gang.", completion = "Ya one of us now, <name>." }
WordHunterWoW_QuestEN[47503] = { title = "Gozda'kun the Slaver", description = "Dat's it. De Sandfury are officially banned from de Goldtusk Inn!\n\nYou can't just ransack a place, kidnap its staff, and mock its owner with an assortment of fruits and vegetables and expect to get away with it!\n\nWe gotta teach those thugs what happens when you mess with de Goldtusk Gang!\n\nGozda'kun de Slaver was bossing around de rest of de Sandfury during de attack.\n\nTake him out, and leave some Sandfury behind to spread de word.", objectives = "Kill Gozda'kun the Slaver in the Sandfury Hideout.", completion = "Dat'll teach de Sandfury to fear de Goldtusk Gang!" }
WordHunterWoW_QuestEN[47506] = { title = "REUSE", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[47507] = { title = "Khazaduum", description = "", objectives = "" }
WordHunterWoW_QuestEN[47508] = { title = "Fire At Will", description = "Look out there, the wings of the bats fill the sky. We must offer what ranged support we can, but our hands are full here.\n\nIt looks like the Legion has not yet destroyed all of the artillery batteries. If you can get to one, you should be able to show those flying fiends the Light.", objectives = "Enter a Lightforged Battery and slay 30 Frenzied Plaguewings.", progress = "Those bats are always a nuisance to deal with. This method will be more... efficient, I believe.", completion = "We may be grounded, but that does not mean they have to rule the skies!" }
WordHunterWoW_QuestEN[47509] = { title = "Terrace of the Chosen", description = "This betrayal has cut deep into the heart of Zandalar. Half of the Zanchuli Council and their followers have sided with Zul and his... blood god.\n\nLucky for us not all of Zandalar is behind this betrayal.\n\nWe need to topple Zul's cultists before they can rally too many to their cause. Zanchul is the place to start.\n\nGo and see if you can muster any of the Zandalari still loyal to their king.", objectives = "Meet Kaza'jin the Wavebinder near the Terrace of the Chosen.", completion = "<name>, glad to see you are not dead yet." }
WordHunterWoW_QuestEN[47512] = { title = "Nazmir", description = "The blood trolls within the cursed swamp Nazmir threaten to destroy all of Zuldazar. \n\nPrincess Talanji wants the Horde's help in an expedition to strike at the heart of the blood trolls and end their threat to Zuldazar.", objectives = "Speak with Princess Talanji.", completion = "The swamp of Nazmir represents the largest threat to my people. I am glad you chose to help me in this." }
WordHunterWoW_QuestEN[47513] = { title = "Vol'dun", description = "General Jakra'zet detests the Horde and cannot be trusted. As long as he remains in power, the city will never be safe.\n\nWe are not alone in our suspicions. Speak to Princess Talanji to follow up.", objectives = "Speak with Princess Talanji.", completion = "Jakra'zet poses a serious threat to my kingdom and your Horde. It would be good for you to investigate his activities." }
WordHunterWoW_QuestEN[47514] = { title = "Zuldazar", description = "King Rastakhan is an ancient ruler who is not quick to trust new allies. We must earn his trust if we are to earn his fleet.\n\nZuldazar is the seat of power for the Zandalar empire and a good place to start in winning over these potential allies.", objectives = "Speak with Princess Talanji.", completion = "My father's trust is not easily earned.\n\nBelieve me." }
WordHunterWoW_QuestEN[47518] = { title = "Raal", description = "Crazzak is a traitor in priest's clothing who thinks if he tortures enough of us it will hurt our loa.\n\nDey even have my husband Raal up on de apex of Zanchul. Normally I would say dey could have him, but dey are using his connection to Pa'ku to weaken de loa.\n\nCan't have dat. Let's get to de top of Zanchul and rescue my worthless husband.", objectives = "Kill Crazzak and free Hexlord Raal.", progress = "Dis is a problem!", completion = "Aya... did you have to bring Loti? She is never going to let me forget about dis." }
WordHunterWoW_QuestEN[47520] = { title = "Walls Have Ears", description = "Yazma, mistress of spies.\n\nBah! A traitor who is into creepy crawlies. She chose to side with Zul, and she uses de children of her loa, Shadra, to watch and track everything we do.\n\nWe have to kill all de spiders we see, or dat traitor Yazma will know every move we make.", objectives = "Kill 8 spiders in Zanchul.", progress = "Are dey dead?", completion = "Well done. Dat should blind Yazma." }
WordHunterWoW_QuestEN[47521] = { title = "Midnight in the Garden of the Loa", description = "Yazma and her henchtroll Vol'kaal have pulled most of their forces back to de Garden of de Loa. \n\nSomething bad is afoot, I can feel it in my spirit. Pa'ku is in danger, along with all de loa who have followers dere.\n\nCome, let's fly dere and put an end to dese heresies.", objectives = "Fly with Hexlord Raal to the Garden of the Loa.", completion = "From here we can strike back at our enemies." }
WordHunterWoW_QuestEN[47522] = { title = "The Hunter", description = "Gonk is in danger. I can hear his call.\n\nMy loa has saved my life so many times, it is about time I return de favor.\n\nCome, join me at de Lair of Gonk on de west side of de Garden of the Loa, and we will save a god.", objectives = "Rescue Gonk.", progress = "These zealots who follow Yazma do not fight like normal priests or traitors. Dey have dark magics, and have been planning this for a long time.", completion = "They seek to kill us. They seek to break us.\n\nAll they have done is unite us in what will be the greatest hunt the Zandalari have ever known." }
WordHunterWoW_QuestEN[47523] = { title = "Disturbance Detected: Black Temple", description = "{name}, right on time, as always.\n\nGood news first, because they're happening at the same time for me anyway. Thanks to the various timewarped objects past and future you discovered, we've figured out how to detect when a new one turns up.  \n\nThe bad news is, we know our technique works because something has changed in the Black Temple, and it's wreaking havoc across the timescape! We need you to ensure the fateful raid turns out exactly like it did before, and to remove the source of this disturbance.", objectives = "Relive the assault on the Black Temple.", progress = "Be extra careful the raid on the temple turns out exactly like it did before.  One extra flap of dragonfly wings, and you might end up killing Illidan for real!  Then imagine the mess we'd be in!", completion = "What's this, <name>?\n\n\n\n\n\nThese are the plans for the raid on Mardum, were we too late?\n\nWhat's strange, is the new plan seems better than the original!  It's unlikely this is the Legion's doing, Illidan surely would have detected any fel manipulation.  So if not the Legion, who is behind this?" }
WordHunterWoW_QuestEN[47525] = { title = "Staying Hidden", description = "Dere be trouble brewin', mon. Da blood trolls be on da move! Dey set up a large camp nearby and have been sending a small force to da isle south of here. \n\nIf dey discover our position while we be havin' no defenses, it gonna be game over! We need ta see what dey be up to and get rid of dem.\n\nOur best bet be ta investigate da isle south a here. Ya want ta join me? I be ready ta head out.", objectives = "Investigate the Frogmarsh.", completion = "I can fight no more. De blood trolls, dey are making a move on Krag'wa in a big way. Dey are going to feed him to their bloody god!" }
WordHunterWoW_QuestEN[47526] = { title = "Bringing the Big Guns", description = "Light's Judgment has a security feature to prevent it from falling into enemy hands. We can trigger its recall mechanism, which will teleport it back to a vessel.\n\nWith the Xenedar out of commission, the gun should recall to your ship instead. You can make good use of its firepower.\n\nThe process takes time, though, and will likely attract the Legion's attention. Be on your guard.", objectives = "Locate and secure Light's Judgment.", completion = "<The panel is now pulsing a soft golden glow. According to Romuul, activating it should teleport the cannon to the Vindicaar.>" }
WordHunterWoW_QuestEN[47527] = { title = "Rituals of Heresy", description = "", objectives = "" }
WordHunterWoW_QuestEN[47528] = { title = "Mistress of Lies", description = "If you are done dealing with dese peasant loa, den perhaps you can help with my own loa: Shadra.\n\nMy \"high\" priestess, Yazma, is behind all of dis. If she is having her minions slay other loa, den I can only guess she is also trying to sacrifice my own loa as well.\n\nShadra's shrine is on de northwest side of de Garden of the Loa. You must stop her from slaying de Mistress of Spies.", objectives = "Defeat Yazma and Vol'kaal in the Garden of the Loa.", completion = "Shadra was... consumed? I have heard of such heresies in Zul'Drak, but to hear of it in Zuldazar..." }
WordHunterWoW_QuestEN[47529] = { title = "Supernatural Support", description = "The loa can bestow powerful boon's to their followers, aid that can be the difference between victory or defeat in our efforts here.\n\nThink carefully which of the two you would like to ask for their blessing. The loa will not give their assistance to those who are currently pledged to another loa.", objectives = "Choose which loa you wish to obtain a blessing from." }
WordHunterWoW_QuestEN[47540] = { title = "Totemic Restoration", description = "I am fed and my body is prepared. I can now be instilled with my power of old and for a time will be immune to their blood curses and leeching powers.\n\nUse the magic of the glowflies to channel my power from the totems into me.\nSoon you will see me restored. Then we will destroy the army that prepares across the river to take all that is mine by force.", objectives = "Activate the power of the totems and restore Krag'wa.", progress = "I had hoped this ritual would never be needed.", completion = "I feel like myself again, back when I had hundreds of followers pouring their faith into me. My power will fade, but the trolls shall learn to fear Krag'wa once more!" }
WordHunterWoW_QuestEN[47541] = { title = "The Best Prevention", description = "If you've brought the High Exarch back to us, you are a welcome ally indeed.\n\nMore is needed of you. You see our soldiers out there, fighting against all odds? Defend them. Slay the enemy.\n\nStrong words for a priest, perhaps, but every dead man'ari is one less blade at our throats.\n\nShow them that the Light protects its chosen even as it scorches the unfaithful.\n\nWhen you are finished, seek out Y'mera. She will have fewer troops, and more need of your abilities.", objectives = "Slay 20 attackers in the Shattered Fields.", completion = "You fought well. The Light shines brighter, thanks to your efforts." }
WordHunterWoW_QuestEN[47542] = { title = "Siegemaster Voraan", description = "", objectives = "" }
WordHunterWoW_QuestEN[47543] = { title = "The Day That Chromie Dies", description = "Oh, {name}! I was just thinking about you! Talk about being at the right time in the right place!\n\nI was just reviewing some aberrations in the timeways, when I discovered something... unexpected. Something not-so-great.\n\nI'm going to die in the near future. Bad times.\n\nI was just about to jump ahead and see if I can figure out why, how, who... but I'd feel better with a {race} like you by my side. Care to join me?", objectives = "Speak with Chromie, then travel to the future to find out how she dies.", progress = "I'm sure I just fall into a hole or something. This wouldn't be the first time!", completion = "That didn't go so great, did it? Maybe next time." }
WordHunterWoW_QuestEN[47545] = { title = "Rewind", description = "Now we know when the attack happens, and vaguely where it's coming from. Progress! All we need to do now is to find out more details and stop that attack!\n\nLet me know when you're ready to try again.", objectives = "Speak with Chromie again, then travel to the future and gather information from the other Wyrmrest emissaries.", progress = "I sure hope we don't cause a paradox!", completion = "I guess we have plenty of leads to follow up on.\n\nWow, whoever wants to kill me really thought this through!" }
WordHunterWoW_QuestEN[47550] = { title = "The Many Advantages of Being a Time Dragon", description = "Well, unfortunately for... whomever is fixated on blasting me into oblivion, I am a fairly skilled master of the timeways! We have the advantage of trying that again, and again, and again, until I'm not dead anymore.\n\nWe're going to need a little more than a few seconds to stop this attack. How does four hours sound?", objectives = "Speak with Chromie a third time, then travel to the future and attempt to save her again.", completion = "Fifteen minutes isn't a whole lot of time. We're going to have to move quickly." }
WordHunterWoW_QuestEN[47551] = { title = "Lessons of Fire and Pain", description = "", objectives = "" }
WordHunterWoW_QuestEN[47552] = { title = "Mistress Il'thendra", description = "", objectives = "" }
WordHunterWoW_QuestEN[47554] = { title = "Intercepting the Legion's Plans", description = "Our scout Skara writes in the missive that she learned of a major Legion initiative. She was after two encoded orders held by Legion troops near us to get the details and this must be when she was killed. The Legion splits their messages into encoded parts so that we cannot read them. \n\nSkara also writes that her partner Brae, a codebreaker, was slain trying to reach our lines with a code book that we will need to translate the Legion's orders. It is vital you find the orders and that code book!", objectives = "Search the battlefield for Legion troops and kill them to get their Enigmatic Legion Orders. Retrieve the Army of the Light Code Book to decipher the orders.", progress = "Have you found the orders and the code book?", completion = "Skara and Brae gave their lives to get us this information and the codebook. Their sacrifice will not be forgotten.\n\nNow, let us decipher the orders and see what the Legion is up to." }
WordHunterWoW_QuestEN[47557] = { title = "Smoldering Chronoshard", description = "This shard of crystal is hot to the touch. The void creature that carried it wasn't a wielder of flame in any noticeable way, so perhaps the chronoshard is related to fire in some other way.", objectives = "Bring the Smoldering Chronoshard to Wyrmrest to unlock a time portal.This shard of crystal is hot to the touch. The void creature that carried it wasn't a wielder of flame in any noticeable way, so perhaps the chronoshard is related to fire in some other way.", completion = "Yeeeeeowch! It's hot! What could it possibly... oh, yeah, that makes sense." }
WordHunterWoW_QuestEN[47558] = { title = "Fel-Touched Chronoshard", description = "This shard of crystal is scarred with deep rivets of green, malevolent energy. Being held by a dreadlord will do that to you.", objectives = "Bring the Fel-Touched Chronoshard to Wyrmrest to unlock a time portal.This shard of crystal is scarred with deep rivets of green, malevolent energy. Being held by a dreadlord will do that to you.", completion = "A chronoshard, you say? I know what to do with those." }
WordHunterWoW_QuestEN[47559] = { title = "Gleaming Chronoshard", description = "This shard of crystal glitters with a metallic sheen. Based on Chromie's reaction, it may be used to connect you to another time and place.", objectives = "Bring the Gleaming Chronoshard to Wyrmrest to unlock a time portal.This shard of crystal glitters with a metallic sheen. Based on Chromie's reaction, it may be used to connect you to another time and place.", completion = "Hand over that chronoshard, <name>. If you don't mind." }
WordHunterWoW_QuestEN[47560] = { title = "Frozen Chronoshard", description = "This shard of crystal is encased in a thin, frigid layer of permafrost. It still has that distinctive lich smell to it.", objectives = "Bring the Frozen Chronoshard to Wyrmrest to unlock a time portal.This shard of crystal is encased in a thin, frigid layer of permafrost. It still has that distinctive lich smell to it.", completion = "I hate when they get all chilly like this." }
WordHunterWoW_QuestEN[47561] = { title = "Blistermaw", description = "", objectives = "" }
WordHunterWoW_QuestEN[47563] = { title = "Spirits of the Fallen", description = "", objectives = "" }
WordHunterWoW_QuestEN[47564] = { title = "Restocking the Buffet", description = "Imagine for a moment, {name}. You wake up in de Goldtusk Inn after a long day of drinking scorpid blood, slaughtering Sandfury, and sharing jokes with your best friend Zulsan.\n\nYa not fully awake yet, and not feeling ya best. What do you need most at dat exact moment?\n\nAn all-you-can-eat breakfast buffet, of course!\n\nI'm working on it, but I need some fruit to balance out my menu. Luckily, I've seen some in de oasis outside.\n\nBring me some, and I'll give you lifetime access to de buffet.", objectives = "Collect 10 Whistlebloom Juicy Fruit.", progress = "Dis buffet is going to be a disaster if we don't get dat fruit!", completion = "Breakfast is served!" }
WordHunterWoW_QuestEN[47566] = { title = "Gar'zoth", description = "", objectives = "" }
WordHunterWoW_QuestEN[47570] = { title = "Hidden Motives", description = "I do not understand why the naga would bother attacking a small fishing village.\n\nWhy waste their time on our simple tribe? The naga seek power and we have none. It makes no sense!\n\nThey must be after something else entirely...\n\nSearch Darkwood Shoal and learn of their plans. Whatever the naga are after, it must be quite powerful.\n\nPerhaps if we find it first, we can use it against them!", objectives = "Locate the naga invasion plans.", progress = "Have you uncovered their plans?", completion = "According to the invasion plans, the naga are after an ancient relic of extraordinary power known as the Ring of Tides. Apparently, it was lost hundreds of years ago in a battle not far from here..." }
WordHunterWoW_QuestEN[47571] = { title = "The Elder's Wisdom", description = "The naga are searching for a powerful artifact called the Ring of Tides.\n\nAccording to the invasion plans, the ring was lost long ago in a battle with Eraka no Kimbul, the great tiger loa.\n\nThe temple of Eraka no Kimbul is just to the north. If the loa was strong enough to defeat the naga before, maybe he can do it again!\n\nWe must let the tribe know what we've found!\n\nTake the invasion plans to Elder Kuppaka. He is the oldest, and wisest member of our tribe. He will know what to do.", objectives = "Deliver the Invasion Plans to Elder Kuppaka.", progress = "Elder Kuppaka will know what to do.", completion = "The temple is not far away, but it lies in ruin... abandoned and overgrown." }
WordHunterWoW_QuestEN[47573] = { title = "Jungleweb Infestation", description = "The walls of the temple could provide us with vital protection against the naga, but the temple is overrun with jungle spiders.\n\nWe'll need to clear out the infestation before the tribe can take refuge at the temple.\n\nVenture into the lower ruins and lay waste to the spiders that have nested there.", objectives = "Slay 6 Jungleweb Crawlers and 30 Jungleweb Hatchlings.", completion = "Now that the spider infestation has been removed, we can safely relocate the rest of our tribe to the temple. Thank you, <name>." }
WordHunterWoW_QuestEN[47574] = { title = "All Webbed Up", description = "The lower ruins of the temple are covered in thick webs and spider egg sacs.\n\nSome of our tribesman went down to the lower ruins to clear out the spiders, but they haven't come back.\n\nI fear for their safety.\n\nPlease head into the lower ruins and free our brethren before it's too late.", objectives = "Free 8 Tortaka Tribesman.", completion = "Thank you for rescuing our trapped tribesman. We'll be more careful in dealing with the infestation in the future." }
WordHunterWoW_QuestEN[47576] = { title = "Wrath of the Tiger", description = "The Tortaka shall have my protection. Even as we speak, an army of the naga have risen from the depths to attack my temple.\n\nHow soon the naga have forgotten their previous defeat!\n\nThey seek to reclaim the Ring of Tides, a powerful artifact that I took as my trophy when I killed Azshara's previous champion, Mepjila.\n\nI will send you to the battlefield as my avatar to rain destruction upon the naga. They have forgotten what happens to those who trespass against my followers.\n\nRemind them.", objectives = "Defeat the naga invasion.", progress = "Send the naga army back to the sea!", completion = "You fought bravely against the naga army and defended my temple. From this day forward, you will be an honored guest at my temple." }
WordHunterWoW_QuestEN[47577] = { title = "They Came From The Sea", description = "You are free to rest your weary legs in our camp, but I'm afraid we have little more to offer you.\n\nNaga have driven us from our village by the sea. We can no longer fish or hunt crabs. I fear we may not survive long if we cannot take back our lagoon.\n\nBut taking back the lagoon will not be enough. We must find out why the naga attacked us. What is it they are looking for?\n\nTake this ancient scroll and use it summon the spirits of the naga.\n\nThey will only speak truth while under its spell.", objectives = "Question 8 Naga Spirits.", completion = "Thanks to your efforts, Darkwood Shoal is much safer now. Still, I fear that the naga will return in force to search for this Ring of Tides.\n\nWe must find a more permanent solution to this problem..." }
WordHunterWoW_QuestEN[47578] = { title = "Mark of the Loa", description = "You have proven worthy of my blessing, {name}.\n\nThis means should you choose me as your loa, you can call upon my power when needed.\n\nCommune at my shrine and make your decision. \n\nKnow that whatever you choose, you will always be welcome within these walls.", objectives = "Commune at Kimbul's Shrine.", progress = "I bestow my blessing upon my followers.", completion = "So the choice has been made.\n\nIf you ever wish to change your mind, you can commune at any loa's shrine to receive their blessing." }
WordHunterWoW_QuestEN[47580] = { title = "The Curse of Mepjila", description = "Centuries ago, the sea witch Mepjila attacked my temple with an army of naga invaders.\n\nMy followers fought bravely, but I arrived too late to save them.\n\nI defeated the naga army with ease. But as I closed my jaws around Mepjila, she placed a curse upon the spirits of my followers, locking them in an eternal battle they can never win.\n\nThis mask will give you the power to enter the spirit realm and end their nightmare.\n\nDefeat the spirit of Mepjila and the curse will be broken.", objectives = "Defeat the spirit of Mepjila.", progress = "You must break the curse and free the captive souls of my followers.", completion = "At long last, my ancient followers have found peace. You have served well, <name>." }
WordHunterWoW_QuestEN[47581] = { title = "Blessing of Kimbul", description = "The entrance to the temple is sealed by a magical barrier.\n\nAccording to my scrolls, the barrier can only be lowered by one who has gained the Ring of Tides.\n\nThere is a statue somewhere in the temple grounds with the power to bestow the ring, but the ruins are overrun with jungle spiders. Tulu and I are not strong enough to explore the lower ruins ourselves.\n\nIf you can gain the Ring of Tides and enter the temple, we may finally be able to face the naga head on!", objectives = "Acquire the Ring of Tides.", progress = "The statue is somewhere within the temple ruins.", completion = "Now that you have the Ring of Tides, you'll be able to enter the temple and make contact with the loa." }
WordHunterWoW_QuestEN[47583] = { title = "Die, Die, Diemetradon", description = "We are competing, you and I and these other savages.\n\nI find this... amusing.\n\nSouth of here you will find a number of diemetradons. I challenge you, {class}, to slay more of these creatures than I.\n\nDo you accept my wager?", objectives = "Slay 8 Venomous Diemetradons.", completion = "<It does not seem as though Tracker Burke was prepared for what befell him. He appears to be covered in small punctures and lacerations.\n\nFortunately for you, he appears to have stashed his wager in his hat.>" }
WordHunterWoW_QuestEN[47584] = { title = "A Thorn in the Side", description = "You fools speak of \"big game\" hunting like it is a thing of wonder. Bah! \n\nNone know big game hunting like my kin. Mastery of the hunt, passed down from parent to child, for generations. \n\nI am here to prove it.\n\nI wager that you could not slay more than eleven of the ankylodon beasts that wander this region.", objectives = "Slay 12 Ankylodons in the Preserve.", completion = "<The fresh corpse of Erak appears to have been slain from behind by darts and is disturbingly missing some pieces. Conveniently, the prize money of his wager still adorns the body.>" }
WordHunterWoW_QuestEN[47585] = { title = "Predatory", description = "<There is a wound in his back, possibly from a knife.\n\nIt seems more than the wildlife is fighting back out here.>", objectives = "Find 2 more hunters in the Preserves.", completion = "Hmmm. Dese were left behind on purpose. Someone wanted us to find dem." }
WordHunterWoW_QuestEN[47586] = { title = "Hunting the Hunter", description = "Your hunter king, Nesingwary, is a mighty fine bit of prey here. I even thought of hunting him myself.\n\nBut someone else is on his trail now. And dat hunter, he is a dangerous one.\n\nIf you wish to save your hunter king, you best start tracking quickly. If he made camp, you may be too late already. You cannot paint a target and wonder why you were shot!\n\nI believe he was last seen heading west...", objectives = "Track down Hemet Nesingwary.", completion = "Ye shouldn't have come." }
WordHunterWoW_QuestEN[47587] = { title = "Headhunter Jo", description = "He said he's hunting you. I'm not the prey, I'm the bait!\n\nBehind ye!", objectives = "Slay Headhunter Jo.", progress = "He's a sly one!", completion = "Ye have my thanks, <class>. I'll be on the look out for ye in the future." }
WordHunterWoW_QuestEN[47588] = { title = "King of the Hunt", description = "", objectives = "" }
WordHunterWoW_QuestEN[47589] = { title = "Righteous Fury", description = "The devastators bombarding our forces prevent us from advancing any further. I can only protect us from their blasts for so long.\n\nChampion, you must pierce their lines and remove the barriers protecting the devastators.\n\nIf you can destroy the anchors that maintain the shields, I can cleanse them from afar.", objectives = "Destroy 3 Legion Devastators.", progress = "Unless the anchors are destroyed, the devastators cannot be touched.", completion = "We may yet stand a chance." }
WordHunterWoW_QuestEN[47590] = { title = "Tier 3 Mob Daily Bonus (DNT)", description = "", objectives = "" }
WordHunterWoW_QuestEN[47591] = { title = "Wanna Buy a Lamp?", description = "Ey dere, wanna buy a lamp? You be not regrettin' it.", objectives = "Purchase the Dubious Lamp from Griftah.", progress = "I promise ya don' regret dis.", completion = "See, I told ya it be a great idea!" }
WordHunterWoW_QuestEN[47592] = { title = "Shine Bright Like a Diamond", description = "Oh, I be sorry. Dat lamp look like it could use some shinin'. I happen to have just da ting.", objectives = "Purchase a Certified Organic Lamp Shining Kit from Griftah and use it to shine the Grimy Lamp.", progress = "I'm sure dis will all be worth it.", completion = "Ooh, ooh, lemme see!" }
WordHunterWoW_QuestEN[47593] = { title = "Magical Coins, You Say?", description = "", objectives = "" }
WordHunterWoW_QuestEN[47594] = { title = "I'll Take Those, Thanks!", description = "These coins, dey be vanishin' inta air ya say? Dat be soundin' perfect, as I have jus the fella ta give dem to.", objectives = "Obtain 10,000 Coins of Air for Griftah.", progress = "Oh man, I can't wait to use these. I be thankin' you.", completion = "Dis be da best day. I'm going ta fleece dat Baron so hard his eyes be covered in more wool than a flock of sheep." }
WordHunterWoW_QuestEN[47595] = { title = "I Don't Need Them, But I'll Take Them", description = "If you wanna collect more, Griftah not gonna argue with dat. Dat bein' said, I don't need dem as much anymore, so I be givin' you less for dem.", objectives = "Collect 10,000 Coins of Air for Griftah.", progress = "Another batch, huh? You be really enthusiastic about dese.", completion = "Be you sure ya wanna do dis? I got other wares that be much more interestin' and next week I be needin' more of these." }
WordHunterWoW_QuestEN[47596] = { title = "There Is No Plan \"B\"", description = "Look, I'll be honest with you. Our mech, the A.M.O.D., was the best we've ever made. It was mobile. It was powerful. It was one of a kind! \n\nWhat I'm trying to say is, without it, our whole plan is ruined! We have to salvage and rebuild it!\n\nThat big oaf of a sea giant broke the A.M.O.D. apart and scattered its pieces all over the shore. Find its parts and I'll try to hammer them back together.", objectives = "Locate all parts of the A.M.O.D.", progress = "Got those parts yet?", completion = "Looks like you've got everything, well... we've got the important stuff at least. Now we've got a big repair job to do." }
WordHunterWoW_QuestEN[47597] = { title = "No Goblin Left Behind", description = "Our mission is dead in the water unless we move fast!\n\nI've found the perfect spot for a new base. While I secure the location, I need you to rescue the team and bring them back. We've trained for this a million times. Just direct them toward the rendezvous point and they'll find the way.\n\nWe don't have much time, let's go!", objectives = "Locate and rescue the missing members of the Gob Squad.", completion = "Everyone's present and accounted for. Outstanding job!" }
WordHunterWoW_QuestEN[47598] = { title = "Pilfering and Fencing", description = "Our ships are sunk. Our A.M.O.D.'s gone. We've lost a LOT on this mission... and the Bilgewater Cartel don't offer insurance. The debt collectors will be all over us! We gotta make up for these losses. \n\nThe beach is swarmin' with naga tryin' to collect artifacts from the ruins. How 'bout we grab some of that treasure and make back our money? I'm sure we could find a buyer willing to take 'em off our hands. \n\nWe'll split the proceeds 80/20. Sounds fair to me.", objectives = "Collect 20 Ancient Titan Relics from the naga at the Sundered Span", progress = "Got anything for me?", completion = "Nice haul! This should keep the cartel off our backs." }
WordHunterWoW_QuestEN[47599] = { title = "Revenge: Served Hot", description = "Look, the boss might be keeping a level head here, but we should show these naga what happens when you mess with the Gob Squad. Don't you agree?\n\nThe naga are sending their behemoths to destroy what's left of our ship. Why don't you take my rocket launcher and make an example out of them. That'll send the message loud and clear!", objectives = "Use Ticker's Rocket Launcher to slay 4 Vilescale Behemoths.", completion = "There you go! Let's have a moment of silence for the not so dearly departed.\n\nAaaaaaand... done!" }
WordHunterWoW_QuestEN[47601] = { title = "Field Evaluation", description = "We got the A.M.O.D. back together. It's a fine piece of equipment, but we're gonna have to give it a tune up. We don't want to end up digging shrapnel out of our rears.\n\nLucky for us, there are a few naga camps remaining along with the giant that broke the gun in the first place. They'll be great for target practice.\n\nWe'll deploy the A.M.O.D. just outside the building here. After we deploy, go man it. I'll have you fire a few rounds while I tune its gun.\n\nEverything'll be fine... unless it isn't.", objectives = "Use the A.M.O.D. to destroy the naga camps and defeat Grobathan.", completion = "Great job! The A.M.O.D. needs a few more tweaks but it'll be nothing we can't handle.\n\nOh, and hey... good shooting!" }
WordHunterWoW_QuestEN[47602] = { title = "Ready For Action", description = "It's gonna take a bit to get the gun chassis set up. Who knew lifting big equipment could be so hard?\n\nIn the meantime, why don't you go check back with your friends. Make sure everything's ready on their end. I'd hate to drive this gun into ANOTHER ambush because they're not ready.", objectives = "Travel to Gloom Hollow and speak with Princess Talanji.", completion = "Naga, you say?\n\nSounds like quite de crisis dere. I am glad you were able to get things back together!" }
WordHunterWoW_QuestEN[47603] = { title = "The Mysterious, Magnificent Al'Abas", description = "I see you, puny mortal! I appreciate your concern for my lamp!", objectives = "Speak to Al'Abas.", progress = "The very world trembles, trembles with the weight of magic. Their pockets are full of it.", completion = "You really don't see it? I can sense the magic in their pockets!" }
WordHunterWoW_QuestEN[47604] = { title = "In the Land of Magic", description = "I think I see the problem. Your puny eyes are too weak to detect the mana-infused finery that these elves have spread throughout the land. They've been wearing jewelry the entire time, and you simply couldn't see it.\n\nI propose a partnership, my newly minted associate. My lamp currently suffers from an embarrassing lack of magic and could always use more beautiful decorations. I propose a trade. I shall pierce this sinister veil, and you shall give me the spoils of your theft.", objectives = "Speak to Al'Abas... again.", completion = "Fantastic, simply fantastic. This will be a profitable partnership, my puny associate." }
WordHunterWoW_QuestEN[47605] = { title = "Coins of Air", description = "I would be much interested in these magical trinkets that reside in the pockets of the denizens of this land, and humbly offer my services in helping you acquire them, {name}. \n\nHowever, I sadly cannot pay you in the coin of this realm. What I can offer are ephemera - coins of purest air. They're better than nothing, though!\n\nCarry my lamp with you. Drop the treasures you steal within, and I will grant you these coins. Perhaps the former owner of my lamp would have a use for them.", objectives = "Speak to Al'Abas yet again.", completion = "I entrust you with my lamp. May our partnership be fruitful." }
WordHunterWoW_QuestEN[47606] = { title = "Loyalty Is Its Own Reward", description = "I offer you a challenge, mortal. Obtain a thousand of my coins, and I believe that I can empower my lamp and the vision within.", objectives = "Obtain a thousand Coins of Air.", progress = "My goodness, already!?", completion = "Yes, yes, YES! Do you see the power radiating from the lamp? I can sense objects of great power that were concealed even from my mighty eyes." }
WordHunterWoW_QuestEN[47607] = { title = "High Fash-Djinn", description = "With my newly empowered lamp, I sense further, more valuable trinkets in the pockets of these elves and demons. Fetch them for me!", objectives = "Find rare treasures in the pockets of the denizens of the Broken Isles.", progress = "Well, well, well. You continue to amuse and amaze, mortal.", completion = "You've done it! My lamp has never shone brighter. I shall continue to grant you coins, but I shall have to find new uses for the magic you provide." }
WordHunterWoW_QuestEN[47608] = { title = "I Wish You Could See It", description = "", objectives = "" }
WordHunterWoW_QuestEN[47609] = { title = "Wild Gladiator's Chain Armor", description = "", objectives = "" }
WordHunterWoW_QuestEN[47610] = { title = "Golden King Plate", description = "", objectives = "" }
WordHunterWoW_QuestEN[47611] = { title = "Betrayer Regalia", description = "", objectives = "" }
WordHunterWoW_QuestEN[47612] = { title = "Windfury Set", description = "", objectives = "" }
WordHunterWoW_QuestEN[47613] = { title = "Silent Assassin Armor", description = "", objectives = "" }
WordHunterWoW_QuestEN[47614] = { title = "Light Regalia", description = "", objectives = "" }
WordHunterWoW_QuestEN[47615] = { title = "Holy Warrior Plate", description = "", objectives = "" }
WordHunterWoW_QuestEN[47616] = { title = "Regal Lord Armor", description = "", objectives = "" }
WordHunterWoW_QuestEN[47617] = { title = "Elemental Triad Regalia", description = "", objectives = "" }
WordHunterWoW_QuestEN[47618] = { title = "Howling Beast Set", description = "", objectives = "" }
WordHunterWoW_QuestEN[47619] = { title = "Cycle Armor", description = "", objectives = "" }
WordHunterWoW_QuestEN[47620] = { title = "Lich Lord Plate", description = "", objectives = "" }
WordHunterWoW_QuestEN[47621] = { title = "A True Loa Feast", description = "The blood troll attacks have not stopped until now. They have weakened me significantly and I need to get my strength back. My followers used to bring me offerings of meat from the nearby lands.\n\nGo and bring back a mighty feast. My strength will return and we will stop these attacks once and for all.", objectives = "Kill beasts for their meat in the Upper Frogmarsh in Nazmir.", progress = "I hunger.", completion = "<Krag'wa consumes all of the meat in a couple of gulps.> Yes! I have been hungry for so long. As my followers died, my hunger increased.\n\nPerhaps when more come to follow, eating will once again be just an enjoyable pastime." }
WordHunterWoW_QuestEN[47622] = { title = "A Magical Glow", description = "Long ago when the trolls began listening to the whispering darkness, I instilled portions of my power into the totems that surround my lair. I need that power now.\n\nIn the swamps north of here are glowflies. Their magical essence will aid me in drawing the stored power from the totems. Collect them and return. Then you will see what I was capable of at the height of my strength.", objectives = "Collect Beautiful Glowflies in the Upper Frogmarsh.", completion = "I should have done this long ago as my followers were being murdered, but the blood trolls were always too strong.\n\nWith you lies the last and best chance of our survival." }
WordHunterWoW_QuestEN[47623] = { title = "The Last Witch Doctor of Krag'wa", description = "I am Krag'wa, the once mighty. Curse the blood trolls and their dark god! They have slain my worshippers until only Zentimo remained, and now even he is gone.\n\nI want revenge on the blood trolls, but first I must honor the last of my witch doctors. As I have no others, I must request you perform the ritual.\n\nThen we can talk of revenge.", objectives = "Obtain the Scepter of Rebirth and use it to perform the Rite of Krag'wa Ritual upon Zentimo.", progress = "Zentimo must be honored.", completion = "Your ritual was done well.\n\nWith your help, I will not be fed to the blood trolls' god. It is I who will do the eating!" }
WordHunterWoW_QuestEN[47624] = { title = "Bury It", description = "", objectives = "" }
WordHunterWoW_QuestEN[47625] = { title = "The Ritual We Share", description = "", objectives = "" }
WordHunterWoW_QuestEN[47627] = { title = "Vengeance", description = "The Army of the Light will not have fallen in vain.\n\nOur forces will assault the main encampment while we destroy their siege weapon.\n\nThis will be but the beginning of our vengeance.", objectives = "Destroy the siege weapon at the Crown of Destruction.", progress = "Until their weapon is no longer a threat, we are cornered here like vermin.", completion = "It seems we underestimated the Legion's cunning." }
WordHunterWoW_QuestEN[47631] = { title = "Rendezvous with the Libation", description = "I be honest wit' ya, mon. I be havin' little patience for goblins and their antics.\n\nGo meet with their leader and ensure dat his crew and da weapon be ready for da assault. Zuldazar gonna be overrun by da blood trolls if we fail.\n\nGood luck, {name}!", objectives = "Speak with Patch at the Wayward Shoals.", completion = "Our mission is a disaster, a complete disaster!\n\nWe were about to drop anchor when naga swarmed the ship! The battle was hard, but we had the upper hand until a sea giant came out of nowhere. It beat the ship harder than a foreman beats a lazy peon.\n\nDon't worry, <name>. We'll get this plan back on track. But first, we need to get the crew together." }
WordHunterWoW_QuestEN[47638] = { title = "Powerful Spirits", description = "You prove your worth, {name}. We be willin' to initiate you into de ranks of de Goldtusk Gang, if you wanna join.\n\nDe ritual drink is ready. Boiled scorpid blood spiked with bilewing honey!\n\nDon't mind de smell, it's mostly delicious. It's not terrible. It won't kill you. Usually.\n\nWhen you are ready to join de Goldtusk Gang, let me know. I'll unite you with de whole gang. It's time you see what we see.", objectives = "Participate in the Goldtusk Gang initiation ritual.", progress = "Embrace de spirits.", completion = "You are a Goldtusk now, <name>. Welcome home." }
WordHunterWoW_QuestEN[47641] = { title = "Signs of Resistance", description = "Our forces sustained heavy losses defending the Vindicaar, {name}. We require allies.\n\nThe Army of the Light was known to take in survivors of the Legion's crusade to bolster their ranks. We must do the same.\n\nI sense the presence of the Legion slaves you freed nearby. I suspect that they have carved out a resistance against their masters.\n\nI would appreciate your company, {name}.", objectives = "Search for signs of resistance.", completion = "This must be it." }
WordHunterWoW_QuestEN[47642] = { title = "Soul Crystal", description = "<The three shards combine neatly into a large crystal. Once reassembled, the image of a powerful lich appears above the crystal's surface.>\n\n<The lich speaks:>\n\nKeep the Ruby Shrinewardens occupied. I shall carry out our master's attack from within the great tree itself.", objectives = "Seek out the lich hidden within the Ruby Dragonshrine's tree.<The three shards combine neatly into a large crystal. Once reassembled, the image of a powerful lich appears above the crystal's surface.>\n\n<The lich speaks:>\n\nKeep the Ruby Shrinewardens occupied. I shall carry out our master's attack from within the great tree itself.", completion = "I think this is the spot." }
WordHunterWoW_QuestEN[47643] = { title = "The Ancients' Wisdom", description = "The three ancients left three clues:\n\n\"...the great nightmare...\"\n\n\"...by the water...\"\n\n\"...within the dragon's palm...\"\n\nPerhaps Chromie's attacker lies in the place the ancients describe?", objectives = "Seek out the satyr hidden in the Emerald Dragonshrine.The three ancients left three clues:\n\n\"...the great nightmare...\"\n\n\"...by the water...\"\n\n\"...within the dragon's palm...\"\n\nPerhaps Chromie's attacker lies in the place the ancients describe?", completion = "Based on the clues the ancients gave us, this must be the spot. It HAS to be!\n\nLet's do this, <name>!" }
WordHunterWoW_QuestEN[47644] = { title = "Demonic Corestone", description = "<Deep within the demonic corestone, the image of a dreadlord speaks ominously:>\n\nYes, master. It shall be done, at the exact time that you specified. The bronze dragon will see nothing. One shot from outside the Obsidian Dragonshrine is all I require.", objectives = "Uncover the dreadlord hidden near the entrance to the Obsidian Dragonshrine's cave.<Deep within the demonic corestone, the image of a dreadlord speaks ominously:>\n\nYes, master. It shall be done, at the exact time that you specified. The bronze dragon will see nothing. One shot from outside the Obsidian Dragonshrine is all I require.", completion = "I'm not a big fan of dreadlords, but I think you and I can handle one if we stick together. You ready, <name>?" }
WordHunterWoW_QuestEN[47645] = { title = "Voidcallers' Scroll", description = "<The scroll pieces combine to form a tattered, but readable message:>\n\nThe time is nigh. The invocation will take place above the azure shrine. The void will swallow the bronze dragon. Our master has spoken, and we obey.", objectives = "Seek out the creature of void hidden above the Azure Dragonshrine.<The scroll pieces combine to form a tattered, but readable message:>\n\nThe time is nigh. The invocation will take place above the azure shrine. The void will swallow the bronze dragon. Our master has spoken, and we obey.", completion = "I sense something... bad." }
WordHunterWoW_QuestEN[47646] = { title = "Rope Around", description = "", objectives = "" }
WordHunterWoW_QuestEN[47647] = { title = "Monsters of Zem'lan", description = "", objectives = "" }
WordHunterWoW_QuestEN[47652] = { title = "The Light Mother", description = "We must know for sure whether the Light Mother survived, {name}.\n\nXe'ra was weakened by sending her heart to Azeroth, but she is the prime naaru. She is the Light, and she cannot fade.\n\nLet's head into the Xenedar and look for her. Light willing, she will return to guide us once more.", objectives = "Find Xe'ra within the Xenedar.", progress = "Light Mother... you must have survived...", completion = "Light be praised! This was a dark day, and many lives were lost. \n\nBut the Army endures. The Light Mother's prophecy will be fulfilled.\n\nAll is as it was meant to be." }
WordHunterWoW_QuestEN[47653] = { title = "Light's Return", description = "Xe'ra has been saved! We have won an important victory here.\n\nThe Light Mother should be back on the Vindicaar. No doubt she will want to speak with you. There is so much to explain...\n\nRomuul should be able to teleport us back to the ship now. Let me know when you are ready.", objectives = "Speak with Turalyon to return to the Vindicaar.", completion = "The Army endures. The Light Mother's prophecy will be fulfilled.\n\nAll is as it was meant to be." }
WordHunterWoW_QuestEN[47654] = { title = "Seat of the Triumvirate: The Crest of Knowledge", description = "We have all that we need now, {name}.\n\nAlleria Windrunner awaits your arrival at the Seat of the Triumvirate.\n\nDo not go alone, my friend. You will need allies to recover the Crest of Knowledge... and endure what L'ura has become.\n\nI will prepare the Vindicaar and await your return. Light be with you in that dark place.", objectives = "Slay L'ura and retrieve the Crest of Knowledge.", progress = "It is a heavy burden I have placed upon you, <name>. I have faith you will not fail.", completion = "It is done. My heart mourns the loss of L'ura, but at least you brought her peace.\n\nOnce the Crown is in place, the Vindicaar will stand against the Legion's vile assault. Antorus will fall!" }
WordHunterWoW_QuestEN[47658] = { title = "DNT", description = "", objectives = "" }
WordHunterWoW_QuestEN[47659] = { title = "Hunt the Hunter", description = "Please, help us. De Frogmarsh is under siege! My master, de great loa, Krag'wa, is not willing to bend to de will of de blood trolls and their dark god. So now, dey are taking his power by force! Dey are slaying his children and taking his totems of power. Dey will even take Krag'wa and sacrifice him if we are not able to end dis madness!\n\nStop dem! Slay their leader. Perhaps dat will slow dem down for a while. It will give me time to find a more permanent solution.", objectives = "Slay Warmother Boatema near the Frogmarsh.", completion = "Your deeds do not go unnoticed. Zentimo spoke of you, before his passing.\n\nWhen I did not bend to the blood trolls' corruption, they attacked. Now they seek to sacrifice me to their god.\n\nI have no more followers to work through, but perhaps you will help more." }
WordHunterWoW_QuestEN[47660] = { title = "Fallen Idols", description = "De blood trolls seek to weaken Krag'wa and take his power. Dey steal his idols of power to crack open and feed their magic.\n\nSalvage what idols you can. Dey will be needed to make Krag'wa strong. Strong enough to fight dem off once and for all.", objectives = "Collect Stolen Idols of Krag'wa from the blood troll camp in the Frogmarsh.", progress = "My idols?", completion = "My totems! So many taken, so many broken. I know you saved what you could. It will not be enough.\n\nToo much of their once great power has been drained." }
WordHunterWoW_QuestEN[47661] = { title = "DNT", description = "", objectives = "" }
WordHunterWoW_QuestEN[47663] = { title = "A Timely Summons from Shattrath", description = "The blazing star holds a peculiar alignment this cycle, calling out across the heavens. Seek out the sage Vormu in Shattrath City, and lend her your aid.", objectives = "Meet with Vormu in Shattrath.", progress = "I foresee you will need the strength of many allies to walk this path.", completion = "Oh, is it time?" }
WordHunterWoW_QuestEN[47685] = { title = "Gatekeeper's Challenge: Cunning", description = "Archimonde expected greatness from his pupils. Only the most imaginative minds, the most adroit of intellects, could ever truly fathom the deepest reaches of our magic.\n\nI doubt you can relate.\n\nThe path to the left will take you to a set of three statues. Use them to collect a Mark of Cunning.\n\nTo preserve the integrity of this trial, I will not be able to provide hints. If you do, by some miracle, happen to succeed, I will formally recognize your... brilliance.", objectives = "Collect a Fragment of Acuity, Wit, and Guile and combine them into a Mark of Cunning.", progress = "Display the Mark of Cunning or leave me alone.", completion = "Oh. You were successful.\n\nSurprising." }
WordHunterWoW_QuestEN[47686] = { title = "Not-So-Humble Beginnings", description = "Now we may begin our search for the Crown of the Triumvirate. We will start with the fragment Archimonde carried: the Sigil of Awakening.\n\nTo the east and north you will find all that remains of the greatest school of magic on Argus. It was there that Archimonde gained his mastery of the arcane. I can think of no other place he would stow his treasures.\n\nIt will be guarded, no doubt. We will leverage the expertise of Fareeya's forces here to follow this trail.", objectives = "Meet Archmage Y'mera at the Conservatory of the Arcane.", completion = "This place has its share of secrets. Thankfully, I know enough of them to get us started." }
WordHunterWoW_QuestEN[47687] = { title = "Gatekeeper's Challenge: Mastery", description = "Archimonde was an individual consumed by the pursuit of power. Only those who could match his lust would fare well under his tutelage.\n\nYou will fight what remains of Archimonde's greatest pupils. These three once held such power in their own disciplines that the Conservatory remembers them now.\n\nTheir echoes will try to kill you.\n\nBest all three with all your limbs intact and I will recognize your strength.", objectives = "Defeat Grand Vizier Jarasum, Arc-Consul Velara, and High Wakener Aargon.", completion = "I must admit, I am impressed." }
WordHunterWoW_QuestEN[47688] = { title = "Invasive Species", description = "We should seek out an alternate source of energy just in case I am wrong about the conduits.\n\nLuckily enough, I think I know where we can find one.\n\nThe panthara native to Argus are solitary creatures, but it seems whatever magic the Wakeners possessed has drawn them here in great numbers.\n\nThis is no time to be gentle with the environment--panthara devour energy to survive.\n\nSlay them and see if you cannot reclaim some of the power they have consumed.", objectives = "Collect 30 Partially Digested Arcana.", progress = "There is always room for a backup plan. Did you find what we seek?", completion = "I had not imagined the final product to be so... sticky.\n\n<Y'mera wipes her hands on her robes.>\n\nIt will do." }
WordHunterWoW_QuestEN[47689] = { title = "Gatekeeper's Challenge: Tenacity", description = "My master Archimonde was not known for his willingness to suffer indecision.\n\nHe preferred to teach by rewarding frustration with more frustration-- punishment with more punishment. Absolute conviction was required to succeed under him.\n\nAt the opposite end of the Conservatory you will find a large structure. Once inside, your goal is to overcome all the obstacles placed before you.\n\n Emerge unscathed and I will be forced to consider your will strong enough to proceed.", objectives = "Overcome the Trial of Tenacity.", progress = "Take all the time you need. Failure is an art, I hear.", completion = "You may be worthy of the Conservatory's secrets, if you survive that long." }
WordHunterWoW_QuestEN[47690] = { title = "The Defiler's Legacy", description = "It seems you are not so easily deterred. Very well.\n\nYour deeds qualify you to seek the Sigil. To be clear, I am only permitting you to move on. This does not guarantee your success.\n\nThe greatest of your challenges lies before you.\n\nYou must go to the Praetorium and face Archimonde himself. Only by defeating the master of the Conservatory will you be worthy of the Sigil.\n\nFew have overcome this obstacle. I hope he does not make too much of a mess of you.", objectives = "Defeat Archimonde and retrieve the Sigil of Awakening.", progress = "Archimonde himself... what have we gotten ourselves into?", completion = "I have never felt power like this before...\n\n<Y'mera handles the shard cautiously.>\n\nWe should get this to Velen as soon as we can." }
WordHunterWoW_QuestEN[47691] = { title = "A Non-Prophet Organization", description = "I have complete faith that Velen is nearby. We would know if he had been captured.\n\nAll the same, we must not delay. The Legion has a vested interest in finding him after all he has done to resist them. I shudder to think what they might do, given the chance.\n\nThat is why I am going with you.\n\nWe will find Velen and help him track down the Crest of Knowledge. We must have faith in his mission or all will be lost.", objectives = "Locate Velen.", completion = "You came upon me in a moment of reflection.\n\n<Velen peers at you with a tired expression.>\n\nThere is no time for such sentiment. We must press on." }
WordHunterWoW_QuestEN[47695] = { title = "Sound the Alarm", description = "Sirens are nothing but trouble! All they do is capture our men, never to be seen again. How is anybody supposed to get their goods to Boralus quickly with them around?\n\nSince you're already going down there... mind culling their numbers a bit?", objectives = "Kill 8 Wailing Sirens in Fogcliff Strand." }
WordHunterWoW_QuestEN[47696] = { title = "Krag'wa the Terrible", description = "Your previous attack has angered the blood trolls. They now send an army to take everything. They are too late! I am Krag'wa! I will not be eaten, I do the eating!\n\nMeet me at the edge of Razorjaw River. You will bear witness to my power, and I will bear witness to yours.", objectives = "Use the power of Krag'wa to defeat the blood troll counterattack.", progress = "Do you now see my power?", completion = "The savages flee at the sight of Krag'wa! This pleases me! \n\nBut, they will come back in larger numbers soon unless their dark god is stopped. As long as you oppose them, I will grant you my boon.\n\nWhen the day of reckoning comes, you will have my aid." }
WordHunterWoW_QuestEN[47697] = { title = "Krag'wa's Aid", description = "Well done, {name}!\n\nBefore we left, I heard dat Princess Talanji be headed ta Gloom Hollow. She should be dere by now.\n\nWe better be headin' back. She would want ta hear da tale of ya success!", objectives = "Report to Princess Talanji on your success.", completion = "Krag'wa will make a powerful ally in de coming battle. When de blood trolls are defeated, I have no doubt many Zandalari will come to worship him." }
WordHunterWoW_QuestEN[47699] = { title = "DNT", description = "", objectives = "" }
WordHunterWoW_QuestEN[47700] = { title = "DNT", description = "", objectives = "" }
WordHunterWoW_QuestEN[47704] = { title = "Ranishu Feeding Frenzy", description = "", objectives = "" }
WordHunterWoW_QuestEN[47705] = { title = "Behind Legion Lines", description = "", objectives = "" }
WordHunterWoW_QuestEN[47706] = { title = "Hunt for King K'tal", description = "Hunters! Dis challenge be for de King of de Preserves.\n\nKing K'tal is a mighty predator, smart and fast. Gold and honor await de hunter who brings me de head of de King.", objectives = "Recover the Skull of K'tal.", progress = "Good hunting.", completion = "Impressive. De King has been dethroned." }
WordHunterWoW_QuestEN[47707] = { title = "Melting Down", description = "", objectives = "" }
WordHunterWoW_QuestEN[47709] = { title = "The Great Gnomeregan Run", description = "Ready for the big race today, {name}?\n\nEvery year, gnomes from near and far gather to run all the way from Gnomeregan to Booty Bay!\n\nIt reminds us that no goal is too tall, even for us!  Whether you run fast or slow, alone or with friends, you'll make it as long as you keep trying! So make sure to stretch, then get out there and show the world what we gnomes are made of!", objectives = "Race to Booty Bay.", completion = "One small step for <name>, one giant leap for gnomekind!" }
WordHunterWoW_QuestEN[47711] = { title = "Head of the Viper", description = "While I was scouting out the area, I saw a big armored naga bossing the rest of the snakes around. Call it a hunch, but I'm pretty sure he's their leader.\n\nAs long as the Naga have a commander our operations here will be threatened. Take him out.", objectives = "Kill Lord Slithin at the Sundered Span.", completion = "Good job, that should take some of the heat off us." }
WordHunterWoW_QuestEN[47712] = { title = "The Devastator", description = "", objectives = "" }
WordHunterWoW_QuestEN[47715] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47716] = { title = "Searching the Ruins", description = "Dese dunes are crawling with assassins. Nowhere is safe, but we must press on.\n\nDe ruins aren't far from here. \n\nLet's continue our search on foot.", objectives = "Find Julwaba within Zul'Ahjin.", completion = "Serrik is weak from poison. We're running out of time." }
WordHunterWoW_QuestEN[47720] = { title = "Eternal Vengeance", description = "", objectives = "" }
WordHunterWoW_QuestEN[47724] = { title = "Besieged", description = "", objectives = "" }
WordHunterWoW_QuestEN[47725] = { title = "Tomb of Sargeras: Aegwynn's Path", description = "As we sealed the tomb, I entrusted the final piece of Sargeras' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.", objectives = "Collect 4 Fragment of the Guardian's Seal from the Maiden of Vigilance in the Tomb of Sargeras on Normal Difficulty.", progress = "Without the power of the seal we cannot bypass my wards.", completion = "With the remnants of this seal, we can dispel the wards and enter my sanctum." }
WordHunterWoW_QuestEN[47726] = { title = "Tomb of Sargeras: Aegwynn's Path", description = "As we sealed the tomb, I entrusted the final piece of Sargeras' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.", objectives = "Collect 4 Fragment of the Guardian's Seal from the Maiden of Vigilance in the Tomb of Sargeras on Heroic Difficulty.", progress = "Without the power of the seal we cannot bypass my wards.", completion = "With the remnants of this seal, we can dispel the wards and enter my sanctum." }
WordHunterWoW_QuestEN[47727] = { title = "Tomb of Sargeras: Aegwynn's Path", description = "As we sealed the tomb, I entrusted the final piece of Sargeras' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.", objectives = "Collect 4 Fragment of the Guardian's Seal from the Maiden of Vigilance in the Tomb of Sargeras on Mythic Difficulty.", progress = "Without the power of the seal we cannot bypass my wards.", completion = "With the remnants of this seal, we can dispel the wards and enter my sanctum." }
WordHunterWoW_QuestEN[47728] = { title = "Talestra the Vile", description = "", objectives = "" }
WordHunterWoW_QuestEN[47733] = { title = "The Loa-Speaker's Betrayal", description = "Listen, stranger. I don't have a lot of time left.\n\nI was in de village when Zolani brought de king to us. Said to keep it a secret, or else Zul would find us.\n\nLook around. Dey found us!\n\nBut I know... I know it was not de prophet's doing. Our loa-speaker gave Zolani her pretty words, said she would help, then turned around and sold us out.\n\nIt is Kihara's fault dat we are dying now. She brought dis upon us!\n\nKill her... Make her pay!", objectives = "Slay Loa-Speaker Kihara.", completion = "Dat snake of a womon helped Zul find de king! It is good dat she is dead, but I would have liked to kill her myself.\n\n<Zolani spits.>\n\nBwonsamdi can keep her." }
WordHunterWoW_QuestEN[47734] = { title = "Partners in Heresy", description = "Rezan struggles against his bonds, but we cannot reach him.\n\nDe mogu dat Zul called here have raised a shield dat rejects my magic. Find and kill de creatures dat stand between me and my loa.\n\nI must gather myself for de fight to come. They will know de wrath of TWO kings before dis day is done.", objectives = "Slay Soulrender Gao'tan and Darkweaver Ji'tan.", progress = "Finish dis, <name>.", completion = "Good. De way forward is clear." }
WordHunterWoW_QuestEN[47735] = { title = "Ancient Tortollan Remedies", description = "Ah, yes, the situation is urgent. We must act quickly, but not hastily.\n\nThere is a way to save Rastakhan, but it will require three very specific ingredients. Listen well, young one.\n\nThe first, foam bubbling from the mouth of a crab. The older, the better.\n\nThe second, the spine of a puffer fish. Venomous!\n\nThe third, a brutosaur scale.\n\nWhy? These are the secrets of my people, {name}. Longevity is cultivated like the rarest of flowers... carefully, and with much practice.", objectives = "Collect an envenomed puffer spine, a brutosaur scale, and aged crab foam for Jol the Ancient.", progress = "The quality of the healing depends very much on the quality of the ingredients.", completion = "They are satisfactory. I will explain in due time what they are for." }
WordHunterWoW_QuestEN[47736] = { title = "Heads Will Roll", description = "Zul's forces try to lay claim to de loa of kings's temple.\n\nYou must teach dese traitors de meaning of their actions.\n\nSweep de temple of de filth dat defiles it. Destroy those who spit in de face of de loa. Bring me their heads so I may remind others of what happens to those who betray their faith and their king.\n\nWhen you are finished dealing with de unworthy, come find us. Rezan's altar lies deep within de temple grounds.\n\nIn Rastakhan's name, heads will roll!", objectives = "Collect 12 Traitorous Zandalari Heads.", progress = "Time for us to send dese traitors a message.", completion = "When leaving a message, it is always good to use a language dey can easily understand." }
WordHunterWoW_QuestEN[47737] = { title = "The Temple of Rezan", description = "De chronicler's words are dire. If Zul truly does wish to sacrifice Rezan...\n\nDis will not come to pass! I will defend my loa with my life.\n\nCome, {name}, we go to de Temple of Rezan. We must stop dis heresy at once!", objectives = "Meet King Rastakhan at the Temple of Rezan.", completion = "<Rastakhan glowers at the priest's corpse before him.>\n\nZul will pay for dis. Those who follow him will suffer, mark my words." }
WordHunterWoW_QuestEN[47738] = { title = "The Will of the Loa", description = "Jol's remedy healed Rastakhan's flesh. But his spirit is still lost. Dere is only one thing stopping him now.\n\nDeath.\n\nHe is walking in Bwonsamdi's shadow. For most, dere would be nothing to be done. But... he is bound to another loa. A loa who gives life to his faithful.\n\nYou must call on Rezan, loa of kings, and ask him to claim back Rastakhan's soul.\n\nUp de path, you will find my tent. Place dis idol and wait dere. If we are lucky, he will aid us.\n\nIf not... It was nice knowing you.", objectives = "Place an Idol of Rezan at Jamil's hut and persuade Rezan to retrieve Rastakhan's soul.", completion = "<Rastakhan smiles grimly at you.>\n\nYou look like you have seen a loa. I know de feeling. Rezan will have words for me when I see him again." }
WordHunterWoW_QuestEN[47739] = { title = "The Scent of Vengeance", description = "I know my king, and I know he is not weak willed. His spirit struggles under de weight of dis betrayal, and confusion roots his spirit too close to death for my comfort.\n\nWe will need to remind him of his purpose. His anger.\n\nI have heard shouts of terror from de village below. Zul's followers torment Zeb'ahari while dey hunt for him. Slay those who would harm his people and bring me their blood.\n\nPerhaps de scent of vengeance can revive de devilsaur inside ol' Rastakhan.", objectives = "Gather 12 Traitor's Blood from Zul's followers in Zeb'ahari.", progress = "I hope we are not too late, <name>.", completion = "De scent of blood is a reliable way to wake a devilsaur. De blood of traitorous wretches, even moreso." }
WordHunterWoW_QuestEN[47740] = { title = "House of the King", description = "I hear Rezan's call. I will answer, but first you must help me.\n\nOur loa give us many boons, and we repay dem in worship. Offerings, sacrifices, and idols are our tools to earn favor, but dey are much more to our loa.\n\nDey are sources of strength.\n\nZul's dogs have begun to corrupt de great golden statues dedicated to Rezan. Even now, I can feel his power dwindling.\n\nStop dem. Cleanse de idols to de great hunter. Teach dem to respect de house of de king.", objectives = "Cleanse the 3 Statues of Rezan.", completion = "My loa is not dead yet. Now ensure he stays dat way." }
WordHunterWoW_QuestEN[47741] = { title = "To Sacrifice a Loa", description = "Rezan's power is fading. My usurpers have nearly completed their task.\n\nI have read of de horrors of Zul'Drak, and I have seen de results of dese acts. To think one of my own people would bring dis heresy here is... unimaginable.\n\n<Rastakhan snarls in anger.>\n\nCome! We will end dis traitor who spits in de face of all loa!\n\nDi chuka Rezan!", objectives = "Slay Vilnak'dor and stop the sacrifice of Rezan.", completion = "<Rezan's great sides heave as he recovers from his rampage. He is covered in gore.>\n\nHeretics." }
WordHunterWoW_QuestEN[47742] = { title = "Zul's Mutiny", description = "A ship such as Rastakhan's Might does not readily sail without her crew.\n\nDat means de Zandalari aboard have succumbed to Zul's machinations and have betrayed their king as surely as he has.\n\nBoard my ship. Kill those who think to rise against their king. We will take no prisoners.\n\nDe punishment for de crime of mutiny is death!", objectives = "Slay 10 mutinous Zandalari trolls aboard the flagship Rastakhan's Might.", progress = "Have you answered dem, <name>?", completion = "Your hands are bloody. Good. Mutiny has no other price." }
WordHunterWoW_QuestEN[47743] = { title = "The Child of Light and Shadow", description = "It is time, {name}.\n\nXe'ra is returned to us. We have Light's Heart. We have her Chosen One.\n\nCome, let us restore her. Let us forge a bright new path against our foes.\n\nSpeak to me when you are ready to begin.", objectives = "Speak with Turalyon to revive Xe'ra.", progress = "Xe'ra...", completion = "I did not expect this of Xe'ra. Nor could I have foreseen Illidan's reaction.\n\nWe must ensure these events do not crush the spirits of our allies." }
WordHunterWoW_QuestEN[47744] = { title = "Smoke, Meat, and Pretty Flowers", description = "Back of town's on lockdown, kid. And yes, I do have a key, but you're a stranger.\n\n<Emery pats his pocket gingerly.>\n\nListen, I'd like to help you out. You've got an honest look to you. Fetch me some venison, some pipe tobacco, and a bundle o' yellow flowers, and I might be able to make an exception.", objectives = "Obtain some Salted Venison Jerky, Grimm's Special Pipe Blend, and a Marigold Bouquet.", progress = "You're not in a hurry, are you?", completion = "The smoke and the meat are for me. The flowers, on the other hand, are for the kids at the orphanage down the street." }
WordHunterWoW_QuestEN[47745] = { title = "Yeah, Definitely for the Kids", description = "I don't know if you've ever seen Orphan Matron Meliana before, but she is a goddess come down to humble Lordaeron. Her hair, those cheekbones, and...\n\n...and anyhow, these flowers are for the kids at the orphanage where she works. Tell Meliana that they're from me. For the kids.", objectives = "Deliver the Marigold Bouquet to Orphan Matron Meliana.", progress = "What's this?", completion = "These are from Emery, I assume?\n\n<Meliana blushes.>\n\nThat dummy. Gotta admire his persistence, though..." }
WordHunterWoW_QuestEN[47746] = { title = "Holing Up", description = "Did... did you see that? Prince Arthas just struck that person down in cold blood! Right in the middle of the street!\n\n<Meliana regains her composure.>\n\nI need to protect the children. Please, help us, visitors. I need a gun, bandages, and some venison jerky.\n\nChildren! Everybody, get into the house!", objectives = "Obtain a Refurbished Military Rifle, Basic Cloth Bandages, and Salted Venison Jerky.", progress = "The children are priority one.", completion = "I don't know how long we'll need to stay holed up in the orphanage, but there's no way I'm letting the kids out while our prince walks the streets like some sort of madman." }
WordHunterWoW_QuestEN[47747] = { title = "Fight Plague with Fire", description = "One final request of you, stranger. I've seen what's happening outside, and I've heard about this \"plague\". I don't want to go down without a fight.\n\nI have enough rum in the back of this bar to set this whole tavern on fire, but I don't have the tools to do it safely. Fetch me a flint and some rope, and I'll give you my key to the backstreets of Stratholme.", objectives = "Obtain a Flinty Firestarter and some Heavy Straw Rope.", progress = "Mad Prince or drooling zombie - nobody's going to take this bar away from me without a fight!", completion = "This'll do, <class>.\n\nTake this key. You've earned it." }
WordHunterWoW_QuestEN[47748] = { title = "FLAG - Holing Up Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[47749] = { title = "FLAG - Fight Plague With Fire Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[47750] = { title = "For Emery", description = "We do have plenty of food here, however. If you're braving the streets, please deliver this venison to that big dummy at the tavern.\n\nTell him it's from the kids.", objectives = "Deliver the Salted Venison Jerky to Emery Neill.", progress = "Say, what've you got there?", completion = "From the kids, you say?\n\n<Emery struggles to conceal a smile as he pockets the jerky.>" }
WordHunterWoW_QuestEN[47751] = { title = "A Winter Veil Gift", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[47752] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47753] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47754] = { title = "Lightly Roasted", description = "Can you hear me, {name}? Good.\n\nLight's Judgment has been installed on the Vindicaar. We should be able to harness its power immediately.\n\nWe can use it both to clear the rubble blocking the Xenedar as well as destroy our enemies.\n\nAs with any new piece of technology, we should test it out. Thoroughly. I trust you have plenty of targets down there.", objectives = "Use Light's Judgment to destroy the rubble blocking the entrance to the Xenedar.", completion = "Excellent. The path is clear." }
WordHunterWoW_QuestEN[47755] = { title = "Captured and Enraptured", description = "You gotta help me! Me and my crew were running late on a delivery, so we decided to take a detour through this grotto ahead. Boy... that was a mistake. This place is crawling with sirens!\n\nIf there's one thing my men like more than women, it's grog! Here, take some. Use it to bring them back to their senses. Might be best to rough 'em up a bit to weaken the enchantment.", objectives = "Free 6 Enthralled Sailors in Fogcliff Strand.", progress = "Were you able to free my men? Without them, I'm stranded!", completion = "My men have been reporting back to me. Thanks for freeing them, <name>." }
WordHunterWoW_QuestEN[47756] = { title = "The Libation's Liberation", description = "", objectives = "" }
WordHunterWoW_QuestEN[47767] = { title = "Death Metal Knight", description = "", objectives = "" }
WordHunterWoW_QuestEN[47771] = { title = "Locating the Longshot", description = "We're going to need a bigger gun if we hope to free Xe'ra.\n\nOne of the other bunkers crashed closer to the Xenedar. If Baraat was on it, he will have already begun surveying the area. Perhaps he's found the main cannon of the ship.\n\nIf you head over that way, make sure he hasn't died, will you?", objectives = "Find Baraat the Longshot.", completion = "We're under too much pressure here. And it's so close to us..." }
WordHunterWoW_QuestEN[47772] = { title = "Sky Ablaze With Cannonfire", description = "Oh! It's me! And {name}, was it? I remember this!\n\nI seem to have found myself in the middle of a battle between the Horde and the Alliance, which wouldn't USUALLY be a big deal, except for that enormous cannon that seems to be trained on me anytime I try to fly away.\n\nThink you could take it out for me?", objectives = "Destroy the Horde Siege Cannon.", progress = "Any luck? I just need the Horde cannon taken disabled if I want to escape.", completion = "You did it! Now hurry along... if I remember this correctly, you don't have much time left!" }
WordHunterWoW_QuestEN[47773] = { title = "Sky Ablaze With Cannonfire", description = "Oh! It's me! And {name}, was it? I remember this!\n\nI seem to have found myself in the middle of a battle between the Horde and the Alliance, which wouldn't USUALLY be a big deal, except for that enormous cannon that seems to be trained on me anytime I try to fly away.\n\nThink you could take it out for me?", objectives = "Destroy the Alliance Siege Cannon.", progress = "Any luck? I just need the Alliance cannon taken disabled if I want to escape.", completion = "You did it! Now hurry along... if I remember this correctly, you don't have much time left!" }
WordHunterWoW_QuestEN[47790] = { title = "Unsettled Power", description = "The release of the energy previously trapped in the Nightwell has... complicated the influence of Aman'Thul scattered about the Broken Isles. Sadly, the results of my previous work have been invalidated, much like the contents of this vial.\n\nI must understand what has caused this change! Please, bring me more samples so that I may continue my work. It goes without saying that you will be the beneficiary of any breakthroughs I may find.", objectives = "Bring 50 Writhing Essence to Arcanomancer Vridiel.", progress = "The people of Suramar spent 10,000 years tapping into the latent energies of a dead titan. I wonder if any of them considered what might happen if they suddenly stopped doing so.", completion = "I've managed to stabilize the mixture without diminishing its potency. No simple task, mind you, and I do hope you will appreciate the hard work it took to get this far.\n\nI feel a great sense of unease regarding what might have been the source of this disruption. One would have expected that releasing Aman'thul's power would bring harmony, not chaos." }
WordHunterWoW_QuestEN[47791] = { title = "Unsettled Power", description = "It is deeply disconcerting that the power of Aman'thul grows increasingly unstable. We must pursue this matter further.\n\nIs this volatility the result of the Legion's corruption? No, that is too recent an influence. Something else must have...\n\n<Vridiel trails off absentmindedly, not looking directly at you.>", objectives = "Bring 50 Writhing Essence to Arcanomancer Vridiel.", progress = "I must discover the source of the unrest present in these samples.", completion = "Maddening! I am no closer to a breakthrough on this matter. Such a failure is unacceptable!\n\n<Vridiel breathes deeply and composes himself.>\n\nThank you, <name>. I must not let this setback deter me from further attempts. Please, take this. You will no doubt find a use for it." }
WordHunterWoW_QuestEN[47793] = { title = "The Spoiled Sample", description = "<You pick up a vial of thick, inky liquid. Its contents react to your touch, boiling and popping furiously for a moment before settling down into a persistent glow. The substance resembles arcwine in this form, but the reaction reminds you of the breakdown of obliterum.\n\nYou tuck the vial in your bags. Someone in Dalaran familiar with the obliterum forge might know more.>", objectives = "Bring the Spoiled Sample to Arcanomancer Vridiel in Dalaran on the Broken Isles.", completion = "This is worrisome. Gul'dan's defeat may have disrupted forces far more fundamental than anyone realized. \n\nHmm... perhaps we can turn that to our advantage." }
