WordHunterWoW_QuestEN[47807] = { title = "Worried About My Friends", description = "I've heard about some trouble over at the black dragonshrine. I know, I'm a bronze dragon, but still! I worry about them sometimes! They weren't ALWAYS so grumpy.\n\nIf you're going there anyways, would you mind taking care of... whatever's causing so much of a disturbance?", objectives = "Slay Zorathides at the Obsidian Dragonshrine.", progress = "I don't know what I'd do without my aspect. Must be tough.", completion = "It was a dreadlord? That's... unusual. I mean, I know we're in Northrend and everything, so risen skeletons aren't all that rare, but demons?\n\nOh well! Thanks for taking the time to calm my worries." }
WordHunterWoW_QuestEN[47808] = { title = "The Dead Walk", description = "Greetings, {race}. I know you are here in the service of the bronze, but I have a request of you.\n\nThe Ruby Dragonshrine is plagued by undead. My shrine's wardens were unprepared, and we risk losses if an intervention is not done quickly. Would you assist us?", objectives = "Slay Talar Icechill at the Ruby Dragonshrine.", progress = "Thank you for hearing my request.", completion = "You have my thanks, <race>.\n\nI know that you are here today in service to the Bronze Dragonflight. Perhaps this gift will aid you in your journeys." }
WordHunterWoW_QuestEN[47809] = { title = "Darkness in the Ley", description = "A strange, dark disturbance perturbs the ley lines in my flight's dragonshrine. Do you have the time to investigate?", objectives = "Slay the Void Gargantuan at the Azure Dragonshrine.", progress = "<Kalecgos eyes you cautiously.>", completion = "Your assistance is appreciated." }
WordHunterWoW_QuestEN[47810] = { title = "Darkened Dreams", description = "The ancients at the Emerald Dragonshrine suffer in their dreams. With Ysera gone, I am shorthanded and unable to investigate the matter myself. Would you help me cleanse the nightmare from the Emerald Dragonshrine?", objectives = "Slay Thalas Vylethorn at the Emerald Dragonshrine.", progress = "I appreciate you taking the time to listen to my concern, <race>.", completion = "With your assistance, the ancients have fallen back into their restful slumber. Thank you, <race>." }
WordHunterWoW_QuestEN[47811] = { title = "Whispers from the Shadows", description = "It seems the Necrodark cult has been lurking in the shadows, waiting for their chance to free the Grey One. My absence from Highmountain weaked the wards and gave them their chance.\n\nThe final ward lies deep with the twisting tunnels of Neltharion's Vault. Navarrogg knows those tunnels like the back of his hand. Seek out his aid.\n\nYou have learned much by walking in the footsteps of ancient heroes, {name}. But the future of our mountain depends upon what you do this day.", objectives = "" }
