WordHunterWoW_QuestEN[47835] = { title = "The Hand of Fate", description = "{name},\n\nWe have won many battles against the Burning Legion, but it is time to end this war once and for all. \n\nFinal preparations have begun to depart for Argus.\n\nMake haste to Bladefist Bay. A ship awaits you there to grant you and your allies passage to Azuremyst.", objectives = "Meet your escort to the Exodar at Bladefist Bay.", completion = "I knew you would be among those called to fight. It will be an honor to fight by your side." }
