WordHunterWoW_QuestEN[47851] = { title = "Sealing Fate: Marks of Honor", description = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present.\n\nRemember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", objectives = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present.\n\nRemember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", progress = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present.\n\nRemember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", completion = "A simple exchange with complex results.  That's the art of doing business." }
WordHunterWoW_QuestEN[47852] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47853] = { title = "Flanking Maneuvers", description = "I will take command of Fareeya's lieutenants and we will escort Velen to the Crest of Knowledge. His mission must not fail.\n\nWe face an old foe-- one the Army of the Light has encountered on numerous occasions. Talgath will try to block us in and prevent our retreat.\n\nYou must not let that happen. Find out how he is bringing in his forces and cut them off. All we need is time to get in and get out.\n\nWe are counting on you.", objectives = "Close 3 Legion Portals.", completion = "<Velen stares at the shattered statue before him and says nothing.>" }
WordHunterWoW_QuestEN[47854] = { title = "Wrath of the High Exarch", description = "Where the Legion is concerned, violence is always the answer.\n\n<Turalyon hefts his blade with a grim expression.>\n\nThey are between us and Velen. Nothing will stop them from finding him unless we act. Now is not the time to hold back.\n\nTogether we will sow chaos among their ranks.", objectives = "Disrupt the Legion forces in Arinor Gardens.", completion = "If I have learned anything about the Legion, it is that we have no other option but to fight back.\n\nIt was a pleasure to have you at my side." }
WordHunterWoW_QuestEN[47855] = { title = "What Might Have Been", description = "<Velen continues to stare at the statue as he speaks.>\n\nThousands of years ago, when I was young, I made a choice.\n\nA choice that allowed my world to fall to ruin. A choice that made my people exiles. A choice that forever separated me from my beloved brothers.\n\n<Velen shakes his head.>\n\nI cannot leave, not yet. Not until I have had a chance to reflect.", objectives = "Witness Velen's memory.", progress = "Memory roots me in place, more surely than the heaviest stone.", completion = "<Prophet Velen peers solemnly at you.>\n\nThank you." }
WordHunterWoW_QuestEN[47856] = { title = "Across the Universe", description = "Talgath. There was a time I called him an ally, a friend.\n\nI put my trust in him when it came time to leave Argus. I asked him to call out to the others who would join me.\n\nI gave him all that he needed to betray me and slaughter my followers.\n\nI do not know what brought this hatred to lurk in his heart, but his machinations repeatedly forced my people to flee world after world. He made it his mission to hunt us across the universe.\n\nThis must end, {name}. Talgath must die.", objectives = "Defeat Talgath.", completion = "It is done. This one wrong, of many, is finally set to rights." }
WordHunterWoW_QuestEN[47857] = { title = "REUSE ME", description = "Hey you've finished part 1 of the Velen arc. Stop here. Nothing past this point is done.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Stop here. Do not pass go. Do not collect 200 dollars.Hey you've finished part 1 of the Velen arc. Stop here. Nothing past this point is done.You will receive:\n\nUpon completion of this quest you will gain:" }
