WordHunterWoW_QuestEN[47864] = { title = "Sealing Fate: Additional Marks of Honor", description = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present.\n\nRemember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", objectives = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present.\n\nRemember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", progress = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present.\n\nRemember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", completion = "A simple exchange with complex results.  That's the art of doing business." }
WordHunterWoW_QuestEN[47865] = { title = "Sealing Fate: Piles of Marks of Honor", description = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present.\n\nRemember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", objectives = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present.\n\nRemember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", progress = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present.\n\nRemember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", completion = "A simple exchange with complex results.  That's the art of doing business." }
WordHunterWoW_QuestEN[47866] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47867] = { title = "Two If By Sea", description = "The draenei have crafted a vessel to take us to Argus safely. They are gathering the invasion force on Azuremyst Isle as we speak. \n\nWe will join them there by sea. The Legion is no doubt keeping a close eye on the gateway to their world. We must retain the element of surprise.\n\nLet me know when you are ready.", objectives = "Speak to Lady Liadrin to set sail for the Exodar.", completion = "May the Light protect us all this day." }
WordHunterWoW_QuestEN[47868] = { title = "The Necropolis", description = "A deal is a deal, and I pay my debts.\n\nBwonsamdi is a mighty loa and you are going to need a powerful ritual to obtain his attention.\n\nYou are in luck. I already know exactly what needs to be done.\n\nBwonsamdi's temple, de Necropolis, is just to de north. Meet me in de courtyard and we shall see about obtaining an audience with de loa of death.", objectives = "Speak with Hanzabu in the courtyard of the Necropolis.", completion = "Ah, there you are. We are ready to start." }
WordHunterWoW_QuestEN[47870] = { title = "Dead Men Tell No Tales", description = "I'm an employee of the Ashvane Company. We're number one in the Azerite trade. \n\nWhen I took this job, no one told me it would be a one-way trip!\n\nI'd do just about anything to escape these dunes, including working with you.\n\nMaybe we can help each other out?\n\nI'd be willing to part with the code to the captain's lockbox, if you're willing to help me escape this wretched desert.\n\nFor my plan to succeed, my expedition party needs to die. Can't have them telling anyone I'm missing...", objectives = "Kill the remaining members of Randall's expedition party.", completion = "So it's done then? I never really liked Hendricks, anyway." }
WordHunterWoW_QuestEN[47871] = { title = "Seafaring Necessities", description = "She might not be much to look at, but this boat will take me back to Boralus. \n\nBefore my voyage can begin, I'll need a few seafaring necessities. \n\nLuckily, everything I need can be found in the Ashvane encampment.", objectives = "Collect a Seafaring Hat, Nautical Map, and Weathered Spyglass.", progress = "Have you had any luck securing those items I asked for?", completion = "This should all help me get to where I need to go." }
WordHunterWoW_QuestEN[47873] = { title = "The Captain's Cache", description = "Well, I'm sure you've figured it out by now, eh?\n\nI never was fixing to abandon the crew, I just wanted to move up the ranks. You've helped me out a great deal in that respect.\n\nSpeaking of respect, I believe there's the matter of Captain Hartford's lockbox...\n\nHere's the code, courtesy of the fallen captain. Just as I promised. It's all yours!\n\nNow, don't go telling anyone about our little arrangement, okay? I wouldn't want something like that to spoil such a profitable partnership!", objectives = "Loot Captain Hartford's cache.", completion = "<The chest creaks open.>" }
WordHunterWoW_QuestEN[47874] = { title = "Clearing the Fog", description = "Did you lead Kaja here? I told her not to come after me. It isn't safe...\n\nMy mind remains fogged, but de memories are slowly returning. Jakra'zet... de weapon...\n\nCome, let us find some fresh air. I will tell you what I've discovered.", objectives = "Follow Warguard Rakera.", completion = "Talanji was right not to trust de general. If he succeeds in finding de weapon, our great city will fall." }
WordHunterWoW_QuestEN[47880] = { title = "A Tribute for Death", description = "Everything for de ritual is together. Now, it is time to begin. \n\nFor dis to work, I must chant de words of old. It is an exhausting task, so I need you to take my mojo fetish and draw de ritual circle, then beat upon de drums.\n\nIf all goes well, Bwonsamdi may invite us into de temple.\n\nIf not, our souls are forfeit.\n\nLet's not make any mistakes.", objectives = "With Hanzabu's Ritual Fetish, draw the ritual circle and sound the Drum of the Spirits to complete the ritual.", completion = "Ya be brave ta come here, but ya need ta have more than just bravery if ya be wantin' Bwonsamdi's favor." }
WordHunterWoW_QuestEN[47881] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47882] = { title = "Conservation of Magic", description = "I have an idea. This construct will be of use to us. We simply need to jolt it awake.\n\nWe once stored great quantities of energy in conduits throughout the Conservatory. They are still functional, but only just.\n\nTake this.\n\n<Y'mera hands you a brightly glowing crystal.>\n\nIt will provide a small burst of magic that should help stabilize an erratic conduit. I think I have enough stored for eight or so.\n\nStabilizing a few should allow us to access the whole network.", objectives = "Stabilize 8 Erratic Power Conduits.", completion = "Yes, excellent. The conduits are back online.\n\nThe construct however is proving a little more difficult to awaken than I had hoped." }
WordHunterWoW_QuestEN[47883] = { title = "The Longest Vigil", description = "It was a good thing we sought two sources of energy. Even with the conduits active, the construct has not stirred.\n\nIt has likely been inactive a long while. Perhaps as long as Eredath has floated above Argus.\n\nWhat a long, lonely vigil it must have been.\n\n<Y'mera is silent for a moment as she peers at the construct.>\n\nGo ahead and jostle it a little. That combined with one last burst of magic ought to do the trick.", objectives = "Wake the Gatekeeper.", completion = "Prepare yourself, stranger." }
WordHunterWoW_QuestEN[47885] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47889] = { title = "The Speaker Calls", description = "Magni sent for you to meet him in the Krokul Hovel. He has found something that he believes could help us overcome the Legion's infinite armies.\n\nWe need every advantage we can muster if we are to see this war through. You should seek him out.", objectives = "Meet Magni in the Krokul Hovel.", completion = "Thank ye fer joinin' me, lad. There's somethin' ye have to see." }
WordHunterWoW_QuestEN[47890] = { title = "Visions of Torment", description = "I've been hearin' whispers ever since we got to Argus. They're just like Azeroth's, only... they ain't hers.\n\nI'm convinced that Argus has a titan of its own that's reachin' out to us!\n\nThe broken have a relic stowed away that's darn near holy to 'em. Hatuun says they hear whispers from it... I think it might have some sort o' link to Argus itself!\n\nIt's just in this chamber. Let's see what we can learn.", objectives = "Activate the Sacred Stone to witness Argus' vision with Magni.", progress = "I know, I know, it's a lot to ask, but we need all the help we can get lad!", completion = "I don't know how Sargeras managed to raise Aggramar, but it's bad news for us, believe you me." }
WordHunterWoW_QuestEN[47891] = { title = "Dire News", description = "Azeroth was right in sendin' us here, {name}. We have to stop whatever it is Sargeras is plannin', or we may not have a home left to save when this is all over.\n\nYe should go back to Turalyon and let him know what ye've seen. I'll stay here and see if I can't glean anything else that might help us.", objectives = "Return to Turalyon on the Vindicaar.", completion = "What did Magni have to show you?" }
WordHunterWoW_QuestEN[47892] = { title = "Storming the Citadel", description = "We have already secured ground near Nath'raxas Hold. It is one of the Legion's chief military fortifications on Argus.\n\nStriking it now, and hard, may be our only opportunity to tip the scales in our favor.", objectives = "Travel to Destiny Point.", completion = "If we do not act quickly, the demons stationed here are more than enough to overwhelm us." }
WordHunterWoW_QuestEN[47894] = { title = "Jump Around", description = "", objectives = "" }
WordHunterWoW_QuestEN[47895] = { title = "Bert's Bots", description = "If I'm going to clean up Gnomeregan, I've got to be ready to battle all manner of rat, roach, and potentially even the dreaded mutant rat-roach.\n\nWhat I'm saying is that I need to put these bots to the test! A real, live-action field demo.\n\nAre your pets up for a code review?", objectives = "Defeat Bert in a pet battle.", progress = "Better bots, by Bert!", completion = "I'm going to have to go back to the drawing board!" }
WordHunterWoW_QuestEN[47897] = { title = "Zanchuli Traitors", description = "Dey are trying to cast down our loa, claiming dem to be false gods.\n\nDey have turned to de old ways of blood, sacrifice, and subjugation.\n\nI cannot even begin to say how offensive dis is. Kill any of dese traitors you find.", objectives = "Kill 10 Zanchuli traitors.", completion = "You killed how many? Well, dat is a start." }
WordHunterWoW_QuestEN[47904] = { title = "Preserve the True Future", description = "I know how this looks, {name}. I'm not asking for your help simply because I don't want to get killed.\n\nI need your help because this isn't how I'm SUPPOSED to die. I will die - I've seen it! - but it happens much later than this. Besides, meddling with the timeways for personal reasons - well, it goes against pretty much everything my dragonflight stands for.\n\nLet's stop all four of the dragonshrine attacks. That should do the trick.", objectives = "Stop the attacks from the Obsidian, Ruby, Azure, and Emerald Dragonshrines in one attempt of the Deaths of Chromie scenario.", completion = "We've stopped all four attacks from the dragonshrines - but the timelines are still incorrect. I'm still being assassinated, elsewhere, at the same time.\n\nLooks like our work isn't done yet, <name>!" }
WordHunterWoW_QuestEN[47906] = { title = "The Deaths of Chromie", description = "It looks like we're going to have to stop all eight attacks on me. In one fifteen-minute span.\n\nEven to me, that doesn't seem like a lot of time.\n\nStill, if anybody can do it, it's us. Are you ready, {name}?", objectives = "Stop all eight attacks on Chromie in one attempt in the Deaths of Chromie scenario.", completion = "We've done it! The timelines are exactly as they're supposed to be again. With me, alive." }
WordHunterWoW_QuestEN[47915] = { title = "Rescuing the Taken", description = "We are doing our best to contain de fighting in Zanchul and not let it spill out into de other terraces, but we can't hold for long.\n\nIf you are going to help, start by freeing Wardruid Loti. Dey are trying to break her on de platform above with a dark ritual.\n\nHer soul is bound to a fetish. You must find dat fetish if you are going to free her.", objectives = "Recover the Fetish of Loti.", progress = "Find... de... fetish.", completion = "Free at last! Oh, de pain is coming for dem now." }
WordHunterWoW_QuestEN[47918] = { title = "To Serve Krag'wa", description = "There are other forces who seek to disturb my frogs. The vile naga attack my shores and drain my frogs of their magic!\n\nThey seek to use my followers as a feast for their thirst for mana. It must be stopped!\n\nA powerful shadow hunter named Narez is currently fighting them. You must go aid her and stop the naga from feasting on my frogs!", objectives = "Meet Shadow Hunter Narez in the Upper Frogmarsh.", completion = "<name>! Krag'wa himself sent ya? By da loa, I be blessed dis day ta have him recognize me. I need ya help." }
WordHunterWoW_QuestEN[47919] = { title = "Just Say No to Cannibalism", description = "Of course the Natha'vor trolls have Shoak! Why would it be easy?\n\nI'm sick and tired of running from these trolls. That's why you're going in to end this.\n\nThe Natha'vor trolls have three powerful troll witch doctors called \"corpse mongers\". Take them out and you'll send the tribe into disarray.\n\nOf course, this could all fail spectacularly and make my terrible day even worse.", objectives = "Kill Corpse Mongers Jal'aka, Yon'gi, and Nog'shra", completion = "Good work. The Natha'vor trolls should be in disarray now that those... things are out of the picture." }
WordHunterWoW_QuestEN[47920] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47921] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47922] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47923] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47924] = { title = "Profanity Filter", description = "I hate this place! I just want to go home, but I can't because that oaf, Shoak, is missing.\n\nListen, {race}t, I'll make it worth your while if you help me find that dunce.\n\nI've got a way to find Shoak, but of COURSE these stupid totems are blocking my magic! Why wouldn't they?\n\nTake this scroll and use its magic to burn these totems. I'm going to look around to see if that bonehead is just sleeping somewhere.", objectives = "Destroy 5 Profane Totems with Kajosh's scroll of inferno.", progress = "You destroy those totems yet?", completion = "Looks like that dunce got himself captured by blood trolls.\n\nThis is going to get violent really fast." }
WordHunterWoW_QuestEN[47925] = { title = "Shoak's on the Menu", description = "I don't know what stupid thing Shoak did to get captured by the Natha'vor trolls, we'll find out once you rescue him.\n\nI bet they're getting ready to make a meal out of Shoak. You need to work fast and get him out! \n\nShoak's one of the largest oafs that I know, those trolls won't be happy that you're taking their \"meal\" away.", objectives = "Rescue Shoak from the Natha'vor trolls.", completion = "Thanks again, I thought I was done for!" }
WordHunterWoW_QuestEN[47928] = { title = "Offering for the Loa", description = "The time has come for you to make contact with the great loa Eraka no Kimbul.\n\nI can only imagine what it will be like to be in the presence of such an ancient and powerful deity. You have earned the Ring of Tides, so it must be you that addresses the loa. \n\nPlease present the loa with this offering from our tribe. Tell him of our plight against the naga.\n\nEraka no Kimbul is our only hope of survival now.", objectives = "Meet with Eraka no Kimbul.", progress = "You must meet with the loa. Are you ready?", completion = "It has been many years since I've had a visitor to my temple and been found worthy to wear the Ring of Tides." }
WordHunterWoW_QuestEN[47934] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47935] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47936] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47937] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47938] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47939] = { title = "If the Key Fits...", description = "These Ashvane are unreasonable. I've tried to bargain for my release, but they refuse any offer I bring to the table. \n\nAll they want is whatever's bubbling up in that mine. My kind know better than to go near that stuff. It's volatile.\n\nThere are prisoners in the mine being forced to extract it. Us in the cages? We're back up. When someone dies in the mines, they just send another in. \n\nIf you release me, I'll make sure you're rewarded! We just need to find the right key for this cage...", objectives = "Collect 6 Ashvane Trader Keys.", progress = "We need to find the right key to open this cage.", completion = "None of these keys work! We're going to have to find another way..." }
WordHunterWoW_QuestEN[47943] = { title = "Crab Trapping", description = "We are trapped here with little in the way of food and supplies.\n\nThe territorial sethrak control the land to the west, and the spiteful naga the waters to the east. We are caught between a barren desert and a hostile ocean.\n\nIf you are headed to the lagoon to face the naga, will you bring us back some crabs to eat?\n\nI fear that our tribe will soon perish without food...", objectives = "Catch 8 Clampclaw Clackers.", progress = "Do you have a case of crabs?", completion = "You've arrived just in time, our supplies were getting dangerously low. The Tortaka tribe thanks you, traveler." }
WordHunterWoW_QuestEN[47945] = { title = "To Market, To Market", description = "Thanks heaps for getting us out of that pickle, mainlander. I'd hate to ask, but would you be willing to help with another matter?\n\nEven before this curse struck the village, our sausage shipments from Carver's Harbor started slowing down. If we don't get them sausages, I won't be able to feed my family!\n\nCan you help an honest sausage merchant out? Carver's Harbor is just down the road from here.", objectives = "Meet Thomas Staughton at Carver's Harbor.", completion = "Thank the Light someone came!\n\nI can't handle this myself!" }
WordHunterWoW_QuestEN[47946] = { title = "Save Their Bacon", description = "This is going to sound strange, {class}, but some of my workers were turned into pigs! Lucky I was out on an errand, or I'd have been caught too! Now my people are tied up awaiting... processing. \n\n<Thomas suppresses the urge to retch.>\n\nI can't get past those monsters, but you look like the sort who could. Not sure if this helps, but I coulda sworn I heard some wild cackling coming from the warehouse.\n\nPlease... save my people!", objectives = "Untie Trevor Hightide, Kyle Sailford, Travis Daybreak and Burke Stevenson.", completion = "Thank you for sending my workers to a safe spot.\n\nHopefully my men won't have to remain pigs for long." }
WordHunterWoW_QuestEN[47947] = { title = "Big Bad Wolves", description = "Wolves with strange, glowing eyes have taken over the area! I don't know what they are or why they're glowing but it cannot mean anything good. They have to be removed!\n\nPlease, {class}, slay them before more of my friends are killed.", objectives = "Slay 10 Hexed Howlers in Carver's Harbor.", completion = "With those monsters gone, no more of my people are going to get killed." }
WordHunterWoW_QuestEN[47948] = { title = "Pork Chop", description = "Roland Hacksaw was the best butcher I've ever worked with... but he's gone insane! He's still processing pigs into sausage!\n\nYou have to stop him!", objectives = "Slay Roland the Butcher.", completion = "Poor Roland. He was... very good at his work. One of the finest butchers in Drustvar. It is a true shame his talents were put to such horrible use." }
WordHunterWoW_QuestEN[47949] = { title = "That's Not My Fetish", description = "<The glassy eyes of the pig fetish seem to follow you as you approach. The dark power emanating from the witch's fetish must be what is keeping the workers transformed. \n\nPerhaps Thomas Staughton might have some idea what to do with it.>", objectives = "Bring the Pig Fetish to Thomas Staughton.\n\nProvided item:", completion = "Removing it didn't break the curse? Damn. We'll have to try something else." }
WordHunterWoW_QuestEN[47950] = { title = "Cured Ham", description = "That foul thing has to be what's keeping my men transformed into pigs.\n\nHmm. Well there isn't too much that can withstand a good cleansing fire! I say we burn it! \n\nToss it into the campfire!", objectives = "Toss the Pig Fetish into the campfire.", progress = "Into the flames with that foul thing!", completion = "You did it! The spell is broken and my men are back to normal!\n\nWell... mostly. They're alive at least.\n\nNow we can get back to normal around here. If you see Elijah in Fallhaven, tell him he'll get his sausages soon." }
WordHunterWoW_QuestEN[47952] = { title = "The Missing Fleet", description = "The tidesage order has a sizable monastery right here in Boralus. I say we start our search for the fleet there.\n\nSomeone there has to know something, right? You don't just lose the entire legendary Kul Tiran fleet on accident!\n\nWe'll need to take a ferry over to the monastery. Make sure you bring your pass with you!", objectives = "Charter a ferry to Stormsong Monastery.", progress = "I've never been to the monastery before.", completion = "Keep your eyes open. I'm not sure we're entirely welcome." }
WordHunterWoW_QuestEN[47953] = { title = "Tereck the Selector", description = "", objectives = "" }
WordHunterWoW_QuestEN[47954] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47956] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47959] = { title = "The Warguard's Trail", description = "Rakera's journal suggested she moved south. It's de only lead we have. \n\nMeerah is headed dat way, and has invited us to travel with her. \n\nThese vulpera know de desert better than any troll I've ever met. \n\nOur chances of survival are highest if we travel together.", objectives = "Travel with Meerah's Caravan in search of Warguard Rakera.", completion = "Ah, you're looking for de warguard? She's de only reason I'm still breathing." }
WordHunterWoW_QuestEN[47960] = { title = "Tiragarde Sound", description = "We must convince Katherine Proudmoore to pledge Kul Tiras to the Alliance. Flynn believes the Ashvane Trading Company's new gunpowder is our best lead.", objectives = "Offer to investigate the Ashvane Trading Company.", completion = "Maybe with your help we can restore the people's faith in Proudmoore leadership." }
WordHunterWoW_QuestEN[47961] = { title = "Drustvar", description = "The stalwart protectors of House Waycrest hold fast along the western border, but recently all contact with them has been lost. We must secure their aid in order to bring Kul Tiras together under the Proudmoore banner.", objectives = "Offer to make contact with House Waycrest.", completion = "I've only been to Drustvar once, on a hunting trip. It's a rugged land with a dark history and superstitious people. Steel yourself for this one." }
WordHunterWoW_QuestEN[47962] = { title = "Stormsong Valley", description = "The Kul Tiran fleet has been lost at sea. The tidesages of Stormsong, with their mystical oceanic magic, may be our only way to locate the fleet of legend.", objectives = "Offer to investigate the missing Kul Tiran fleet.", completion = "Even under normal circumstances, the tidesages would be wary of outsiders. I'll accompany you on this mission and maybe we can finally get some answers." }
WordHunterWoW_QuestEN[47963] = { title = "The Ancient One", description = "Dis is far worse than I thought. Pa'ku is crying out in my mind. Dey are doing something to her. Something old and terrible, smelling of de old ways.\n\nShe is nearby, just south of here. Come, {name}, meet me at Pa'ku's roost and we'll rescue her.", objectives = "Rescue Pa'ku.", progress = "What kind of world we live in where da faithful must be da ones to rescue da gods?", completion = "Heretics and ingrates! All of them! I will drop every last one of them on a ROCK!\n\nGo, little <race>, and make sure the other loa are not falling into the same trap I did." }
WordHunterWoW_QuestEN[47964] = { title = "Shoe Shine Kit Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47965] = { title = "The Ruined Temple", description = "The loa may be our only hope against the naga, but the temple lies abandoned and broken.\n\nTwo of my tribe have gone ahead to scout the ruins. They may be able to help you make contact with Eraka no Kimbul.\n\nIf the spirit of the loa remains at the temple, we must find a way for him to hear our plight.", objectives = "Speak with Teekcha.", completion = "I am afraid that we haven't had much success contacting the loa. The entrance to the temple is sealed and the rest of the ruins are overrun with jungle spiders." }
WordHunterWoW_QuestEN[47967] = { title = "An Argus Roper", description = "My warriors stand no chance against even the smallest of the Legion's forces without our Cragscalers. If you can capture a few and bring them here, my warriors can better defend our people.", objectives = "Return 3 Wild Cragscalers to Lead Rider Jerek.", progress = "We need those talbuk!", completion = "With these new steeds our forces stand a chance." }
WordHunterWoW_QuestEN[47968] = { title = "Signs and Portents", description = "<The bulletin that Mayor White was posting at the time he was struck by the spell indicates that there have been some strange happenings in the town lately. \n\nIt is likely these events are connected to whatever cast this spell on the village.\n\nPerhaps there might be records from other villagers that could shed some light on the source of this magic.>", objectives = "Investigate the villagers' writings in Fallhaven.", progress = "<The town's ledger lists a record of the comings and goings of people and goods through the city of Fallhaven.>", completion = "<The writings you were able to find all have one common thread - an old woman who recently arrived in town.\n\nThis ledger may contain some information to her whereabouts.>" }
WordHunterWoW_QuestEN[47969] = { title = "Fallhaven's Curse", description = "", objectives = "" }
WordHunterWoW_QuestEN[47978] = { title = "The Wayward Crone", description = "<The ledger indicates that an old woman named Helena Gentle recently took up residence in a house down the road from the town.\n\nThe villagers' writings point to her being involved somehow with a variety of maladies that struck the village recently. \n\nIt's possible that she may know what's behind this spell, if it hasn't afflicted her as well.>", objectives = "Confront Helena Gentle in her home outside of Fallhaven.", completion = "Why hello there, young man.\n\nWe don't get many visitors to Fallhaven. What brings you to my home?" }
WordHunterWoW_QuestEN[47979] = { title = "Witch Hunt", description = "A curse on the villagers? Oh my, how dreadful!\n\nAlthough, to be honest, there have been some strange happenings around Fallhaven of late. I wonder if these could be culprit?\n\nTake a seat and have a spot of tea. I'll tell you all that I know.", objectives = "Listen to Helena Gentle's story in the Shrouded Foothills.", completion = "<The crone is defeated, and will no longer pose a threat to the people of Fallhaven.  \n\nHowever, her curse on the village still lingers...>" }
WordHunterWoW_QuestEN[47980] = { title = "Furious Familiars", description = "<The wildlife in the foothills appear to be under Helena's spell, and this villager appears to be one of their victims. \n\nThey must be the cause of the recent disappearances from Fallhaven.\n\nPerhaps if their numbers were cut down, they would pose less of a threat to the townspeople.>", objectives = "Kill 10 enthralled animals in the Shrouded Foothills." }
WordHunterWoW_QuestEN[47981] = { title = "Cracking the Curse", description = "<In her haste, it looks like Helena left her spellbook behind. The pages of this book detail the ritual that she used to entrap the villagers of Fallhaven. \n\nIt seems the effigy holding the spell in the village is protected by smaller ones surrounding the town. If these are destroyed, you may be able to affect the one holding the spell on the townsfolk.>", objectives = "Destroy the 4 Lesser Effigies in the Shrouded Foothills.", completion = "<The magical energies surrounding the effigy have dissipated.>" }
WordHunterWoW_QuestEN[47982] = { title = "The Final Effigy", description = "<The effigy's protection has been broken.\n\nAll that remains is to break the effigy itself.>", objectives = "Destroy the Cursed Effigy in Fallhaven.", completion = "What's... going on? How long have I been standing here?\n\nA curse!? You're saying the whole village was just... stuck? I knew there was something terribly wrong with that old crone...\n\nIt seems that Fallhaven owes you a great debt, stranger." }
WordHunterWoW_QuestEN[47986] = { title = "Scars of the Past", description = "The Army of the Light's warframes have won countless battles on Argus. Despite their power, not all who descend into the fray return.\n\nMy modifications to this frame should give us the edge we need, but several critical components are still missing.\n\nThere are remains of battles past in Nath'raxas that we can still scavenge. If you can find the pieces I need, the Legion will feel our fury yet.", objectives = "Recover an Invocation Array, Vindicator Plating, and a Judgment Core.", progress = "Do you have the components?", completion = "Perfect! Thank you, <name>." }
WordHunterWoW_QuestEN[47987] = { title = "Preventive Measures", description = "There is no end to the Legion's depravity. Every battle won, every world conquered, yields more souls to fuel their war machine.\n\nThey have not yet defiled all of the fallen warriors in the hold, but I fear it is only a matter of time. Please, take this talisman with you into the hold and use it to sanctify any corpses you encounter.\n\nThey deserve a better fate.", objectives = "Use the Talisman of the Prophet to sanctify 9 fallen Army of the Light warriors.", completion = "Thank you, <name>. Your actions deny the Legion power and grant the dead the peace they deserve." }
WordHunterWoW_QuestEN[47988] = { title = "Chaos Theory", description = "Despite their strength and their numbers, even the Burning Legion requires order to fight. Disrupt that order... and they fall like the rabble they are.\n\nThe plan is simple. Let chaos reign in their ranks, and the day will be ours.", objectives = "Kill 12 Nath'raxxan Fleshcarvers, Nath'raxxan Doomshots, or Ravenous Soulhunters, and 1 Nathrezim Banelord.", progress = "We must do whatever it takes to see this done.", completion = "Now that their forces are in disarray, let us proceed." }
WordHunterWoW_QuestEN[47989] = { title = "Heralds of Apocalypse", description = "We've been presented with a rare opportunity.\n\nOur scouts have spotted two shivarra priestesses in the western fel pools enhancing the Legion's war effort.\n\nThe inner circle of Sargeras' chosen never leave the walls of Antorus. If we take them out, we might be able to sow fear among those closest to the Dark Titan.", objectives = "Slay Lady Heretica and Mistress Apostriss.", completion = "Impressive. Without the shivarra bolstering their strength we just might stand a chance." }
WordHunterWoW_QuestEN[47990] = { title = "A Touch of Fel", description = "Our warframe is almost operational! It just needs a good jolt to revitalize its systems.\n\nWarlocks in the pools below infuse pieces of Argus with fel energy to create living siege weapons. If you can extract one, we can use it to jumpstart the warframe's Judgment Core!", objectives = "Collect an Immaculate Felcore.", progress = "Remember - immaculate!", completion = "Yes! This is it!" }
WordHunterWoW_QuestEN[47991] = { title = "Dark Machinations", description = "Eredar are adept at manipulating the fel that courses through this world. Those who do not shape it into living weapons build other armaments, like the Spires of Woe.\n\nThe spires will make it difficult for even a small force to penetrate the main stronghold. We must dismantle enough of them to clear the way before we advance upon it.", objectives = "Dismantle 3 Spires of Woe.", progress = "We do not have time for failure.", completion = "No war is won by a single act, but without the spires protecting them the rest of the hold will fall as well." }
WordHunterWoW_QuestEN[47992] = { title = "Dawn of Justice", description = "Thanks to your efforts, our enemy is in disarray and their defenses inoperable.\n\nWe must take the ground at the spire's base and tighten the noose around their commander's neck.\n\nYou have more than earned the honor to take the warframe into battle. We will follow your lead once the way is clear.", objectives = "Use the Lightforged Warframe to take control of the Court of the Avenger.", completion = "Well fought! Now for the commander." }
WordHunterWoW_QuestEN[47993] = { title = "Lord of the Spire", description = "Lord Nath'raxas rules over this hold as thanks for his role in delivering Argus to the Legion many years ago.\n\nMake no mistake, he is powerful, but he has also grown overconfident in his seat.\n\nTake advantage of his hubris and make use of the warframe's firepower while you can. We will storm the courtyard shortly!", objectives = "Defeat Lord Nath'raxas.", completion = "By the Light..." }
WordHunterWoW_QuestEN[47994] = { title = "Forming a Bond", description = "", objectives = "Now that it has been thoroughly tested, I will direct our artificers to energize the warframe once more so that you may call it into battle. If you wish, you may select it at the Matrix Core at your leisure." }
WordHunterWoW_QuestEN[47995] = { title = "Overt Ops", description = "My soldiers are out there, {name}.\n\nI need you to find Baraat, Sorvos, and Telaamon. They were in the process of securing this area for Velen when the Legion came down on top of our heads.\n\nInform them that their orders are to regroup with the Prophet at once.\n\nThe time for subtlety has passed. There is a small army between us and them. Do what you must.\n\nLight keep you safe.", objectives = "Locate Baraat the Longshot, Grand Vindicator Sorvos, and Blademaster Telaamon.", completion = "Fareeya's forces are the best the Army of the Light has to offer. Our mission is that much more likely to succeed with them at our side." }
WordHunterWoW_QuestEN[47996] = { title = "Mawfiend Extermination", description = "", objectives = "" }
WordHunterWoW_QuestEN[47997] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[47998] = { title = "Killing Cannibals", description = "Shoak and I have had a few run-ins with the Natha'vor trolls. Must be why they wanted to capture that idiot.\n\nThe women in that tribe actually eat the men... and anyone else they can get their hands on. I'm sure they're getting ready to eat Shoak.\n\nDo us all a favor and kill some of those cannibals. The world would be a better place without them.", objectives = "Kill 10 Natha'vor Cannibals.", progress = "Well? Did you take care of those cannibals?", completion = "I could hear their screams from here.\n\nThese blood trolls are monsters, <race>. Who eats their own people?" }
WordHunterWoW_QuestEN[47999] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48000] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[48002] = { title = "Limited Supplies", description = "Hello, {name}. It's good to see a fellow alchemist again.\n\nI've been supplying our camp with necessary potions to deal with the demons, but lately I've been running low on supplies. Normally when scouting parties go out, they return with empty vials, but as of late fewer have been returning.\n\nI try to recycle as much as I can, so you see, those vials are precious to me. If you'd be willing to go out and retrieve them, I could show you what I've been making to help combat the demons.", objectives = "Go to the Petrified Forest and reclaim 12 Used Vials.", progress = "How goes the search? Any luck on finding my vials?", completion = "You've found some! These will certainly be enough to get us by for a good while longer.\n\nAs promised, here is a recipe for one of the potions I brew to help in our fight against the Legion." }
WordHunterWoW_QuestEN[48003] = { title = "The Lord's Behest", description = "Lord Norwington will want to thank you for saving his son himself. Why don't you come to the estate? We're preparing for a festival, and everybody's welcome.\n\nWe'll go ahead and tell him of all that has happened. See you there!", objectives = "Meet Lord Aldrius Norwington at the Norwington Estate.", completion = "You're <name>? The hero that saved my son from the troggs?\n\nHohoho! You are very welcome at my estate! You must regale me with your tales of your gallant rescue!" }
WordHunterWoW_QuestEN[48004] = { title = "Beginner Equitation", description = "You may know how to ride already, but you don't know how to ride like a Kul Tiran!\n\nWe'll let you borrow a horse for the festivities. Take one of our lesson masters, Cooper. He's trained many a beginner in his day!\n\nMount up, get in the ring, and show us what you've got! I'm sure you'll be a quick learner!", objectives = "Mount Cooper and practice your Kul Tiran riding skills.", progress = "Kul Tiran riding is a true show of mastery and sport!", completion = "Well done, <name>! I think you're ready to take it to the next level!" }
WordHunterWoW_QuestEN[48005] = { title = "Be Our Guest", description = "My dear friend {name}, I do hope you enjoy the festival. I throw it every year to bring riders from all over Kul Tiras together for a grand celebration of the sport!\n\nIn fact, you deserve the whole nine yards. Please, tour the estate at your leisure and partake in the delicious food and drink, introduce yourself to the people. I insist!", objectives = "Tour the estate and partake in the festivities.", progress = "Have you taken your tour yet? Take a break from adventuring and relax!", completion = "How are you enjoying the grounds? We are still setting up, so it will be even more marvelous soon!\n\nTo tell you the truth, I have to one-up myself every year. It's quite exhausting organizing it all, but it's so very rewarding!" }
WordHunterWoW_QuestEN[48008] = { title = "Dangerous Cargo", description = "By the time I realized what was happening, it was too late.\n\nPeople had been acting strange, but I thought nothing of it. After all, they seemed to still be doing their jobs.\n\nWhile inspecting some of the cargo, this grub jumped out in an attempt to latch onto my face. I managed to take it out, but it was too late.\n\nAll of the shipments are infected. Take this torch. Destroy them.", objectives = "Burn 5 Infested Cargo.", progress = "If I had only noticed sooner, perhaps some of this could be avoided.", completion = "All we can do now is try to contain the threat." }
WordHunterWoW_QuestEN[48009] = { title = "Betrayal of the Guard", description = "My boys have gotten in too deep.\n\nThey've given in to whatever dark forces are at work here.\n\nDo not hesitate to do what you need to and put them down. They knew what they were signing up for when they picked the wrong side.", objectives = "Kill 10 Mind-Addled  Enforcers.", completion = "You did what needed to be done." }
WordHunterWoW_QuestEN[48013] = { title = "Tracking the Trackers", description = "{name}, have I told you about my tracking potion? Our scouts use it to track demons, especially their \"fiends\".\n\nThose particular creatures tend to consume the astral glory in the area, making it difficult to replenish our stores of the herb.\n\nIf you could help thin their numbers out, it would greatly help us from having to search elsewhere for supplies. You can find many of them in the Annihilan Pits.\n\nI could also teach you the recipe for this potion for your effort.", objectives = "Kill 14 Feflame Scavengers at the Annihilan Pits.", completion = "You're an honorable ally, <name>. Thank you for helping us.\n\nAs promised, here is the recipe for the potion." }
WordHunterWoW_QuestEN[48014] = { title = "Clear the Riffraff", description = "The naga sent their tiny, foul, muck-smelling minions into our camp. They are quite bothersome. \n\nIf we do nothing, and their numbers continue to grow, they could pose a threat.\n\nYou look quick and handy. Could you perhaps expunge a few for us?", objectives = "Slay 6 Gilblins at the Scavenger's Strand.", completion = "Maybe, some day, they will learn to think for themselves. Or at least choose a master more wisely." }
WordHunterWoW_QuestEN[48015] = { title = "The Scrolls of Gral", description = "These gilblins are ridiculous! They are like a swarm of angry bees, buzzing around.\n\nHmm, maybe not bees. Bees are useful, and make honey, and don't steal things.\n\nThey ransacked our scrolls. Most were unusable, but there were three that are quite... potent. \n\nIt would be most unfortunate if those made it back to their masters, the naga. Please clean up their mess and bring back our scrolls.", objectives = "Collect the 3 Tortollan Scrolls.", progress = "Ah, <race>. I was always fascinated by your native language.", completion = "These scrolls must be kept safe.\n\nI dare not think how the naga could have used the secrets within, should they have deciphered them." }
